window.JASTROW_CHUNKS[33]={"13200":{"h":"מִינְיָין","r":"M01224","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"מֵינִיקוּת\">מִנְיָ׳</a>.</div>","alt":["מִינְיָינָא","מִינְיָן","מִינְיָנָא"]},"13201":{"h":"מֵינִיקָה","r":"M01225","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יָנַק\">יָנַק</a></div>","alt":[]},"13202":{"h":"מֵינִיקוּת","r":"M01226","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָנַק\">יָנַק</a>) <i>nursing</i>. <span class=\"citation\">Y. Nidd. I, 49ᵃ</span> bot.; ib.ᶜ top <span dir=\"rtl\">ימי מֵינִיקוּתָהּ</span> the time during which she nurses; Bab. <span class=\"citation\">Nidd. 36ᵃ</span>; <span class=\"citation\">10ᵇ</span>; a. fr.—[<span class=\"citation\">Tosef. Kel. B. Mets. IV, 5</span>, v. <a href=\"#\" data-headword=\"מֵינֶקֶת\">מֵינֶקֶת</a>.]</div>","alt":["מֵנִי׳"]},"13203":{"h":"מֵינֶיקֶת","r":"M01227","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵינֶקֶת\">מֵינֶקֶת</a></div>","alt":[]},"13204":{"h":"מֵינִיקְתָּא","r":"M01228","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יְנַק\">יְנַק</a></div>","alt":[]},"13205":{"h":"מִינָּן","r":"M01229","html":"<div class=\"sense\"><i>whence?</i>, v. <a href=\"#\" data-headword=\"מְנָן\">מְנָן</a>.</div>","alt":[]},"13206":{"h":"מֵינַס","r":"M01230","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲנַס\">אֲנַס</a>) <i>oppression, violence</i>. <span class=\"citation\">Targ. Is. X, 1</span> (h. text <a href=\"#\" data-headword=\"אָוֶן\">אָוֶן</a>).</div>","alt":[]},"13207":{"h":"מְיַנְּקָא","r":"M01231","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> name of an <i>undergarment</i> (perh. a corrupt. of manica = tunica manicata). <span class=\"citation\">Targ. Esth. VIII, 15</span> (some ed. <a href=\"#\" data-headword=\"מְיַנְּקָא\">מִיַּנְקָא</a>).</div>","alt":["מְיַי׳"]},"13208":{"h":"מְיַנְּקוּתָא","r":"M01232","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"מֵינִיקוּת\">מֵינִיקוּת</a>. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד מאת׳ 6) <span dir=\"rtl\">עשרין … ירחי מ׳</span> twenty-four months of nursing.</div>","alt":[]},"13209":{"h":"מֵינֶקֶת","r":"M01233","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>a woman giving such, wet-nurse</i>, v. <a href=\"#\" data-headword=\"יָנַק\">יָנַק</a>.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"אֲנַק\">אָנַק</a>) <i>siphon, tube</i>; <i>small cup.</i> <span class=\"citation\">Kel. IX, 2</span>. <span class=\"citation\">Ab. Zar. 58ᵃ</span> <span dir=\"rtl\">קדח במ׳</span> tapped with a siphon. <span class=\"citation\">Kel. XIV, 2</span> <span dir=\"rtl\">עשה בראשו מ׳</span> if he put a knob (cup) on the top of the cane. <span class=\"citation\">Tosef. Kel. B. Mets. IV, 5</span> <span dir=\"rtl\">מיניקות שעשאה לתחת וכ׳</span> ed. Zuck. (R. S. to <span class=\"citation\">Kel. XIV, 2</span> <a href=\"#\" data-headword=\"מֵינֶקֶת\">מניקת</a>) a cup which one put under a door (as a pivot). <span class=\"citation\">Tosef. Dem. III, 6</span> <span dir=\"rtl\">מניקית</span> ed. Zuck.; Y. ib. II, 22ᵈ bot. <a href=\"#\" data-headword=\"מֵינֶקֶת\">מניקת</a>.—<span class=\"citation\">Y. Ab. Zar. IV, 44ᵇ</span> top <a href=\"#\" data-headword=\"מֵינֶיקֶת\">מיניקת</a>.—[<span class=\"citation\">Pirké d’R. El. ch. XLIII</span> <span dir=\"rtl\">מ׳ ראשו</span>, v. <a href=\"#\" data-headword=\"*מָנִיכָה\">מָנִיכָה</a>.]—Pl. <span dir=\"rtl\">מֵינִיקִיּוֹת</span>, <a href=\"#\" data-headword=\"מוּנְיָיק\">מֵנִ׳</a>. <span class=\"citation\">Tosef. Zeb. I, 12</span> <span dir=\"rtl\">בין במ׳</span> ed. Zuck. (ed. <a href=\"#\" data-headword=\"מֵנִיקָה\">מֵנִיקוֹת</a>) or when he made the libation out of tubes.—V. <a href=\"#\" data-headword=\"*מְנַקִּיּוֹת\">מְנַקִּיּוֹת</a>.</div>","alt":["מֵנֶיקֶת"]},"13210":{"h":"מִינְקַת","r":"M01234","html":"<div class=\"sense\"> (read <a href=\"#\" data-headword=\"חֵיוָא\">חֵיוָא</a> or <a href=\"#\" data-headword=\"חִיוֵי\">חֵיוַיָּא</a>) f. (<a href=\"#\" data-headword=\"יְנַק\">יְנַק</a>) [<i>sucker of animals</i>,] <i>hedge-hog</i>. <span class=\"citation\">Targ. Y. Lev. XI, 30</span>, v. <a href=\"#\" data-headword=\"יָילָא\">יָילָא</a>.—V. <a href=\"#\" data-headword=\"פָּלְיַית\">פָּלְיַית</a>.</div>","alt":["מ׳ חִיוְיָא"]},"13211":{"h":"מִינְתָּא","r":"M01235","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (mentha, μένθα) <i>mint.</i> <span class=\"citation\">Ukts. I, 2</span> (Mish. ed. <span dir=\"rtl\">המיתנא</span>, corr. acc.; Var. in R. S. a. l. <a href=\"#\" data-headword=\"אַמִּיתָא\">אַמִּיתָא</a> q. v.). <span class=\"citation\">Y. Dem. II, 22ᶜ</span> bot.</div>","alt":["מִינְתָּה"]},"13212":{"h":"מִיס","r":"M01236","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְאִיס\">מְאִיס</a></div>","alt":[]},"13213":{"h":"מִיסָּא","r":"M01237","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסָּא\">מִסָּא</a></div>","alt":[]},"13214":{"h":"מיסא","r":"M01238","html":"<div class=\"sense\">, Y’lamd. to <span class=\"citation\">Num. I</span>, quoted in Ar., v. <a href=\"#\" data-headword=\"מִיסּוּן\">מִיסּוּן</a></div>","alt":[]},"13215":{"h":"מִיסַּב","r":"M01239","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסַב\">נְסַב</a>) <i>taking, lifting up</i>.—<span dir=\"rtl\">מ׳ אפין</span> = h. <span dir=\"rtl\">משוא פנים</span>, <i>partiality</i>. <span class=\"citation\">Targ. Y. Ex. XXIII, 3</span>; a. e.—<span class=\"citation\">Targ. Y. I Gen. IV, 8</span> (not <a href=\"#\" data-headword=\"מתיב\">מתיב</a>). <span class=\"citation\">Targ. Prov. XXVIII, 21</span> <span dir=\"rtl\">מ׳ באפי</span> (read: <a href=\"#\" data-headword=\"אָפֵי\">אַפֵּי</a>).—<span dir=\"rtl\">מ׳ וּמִיתַּן</span> taking and giving, <i>dealing</i>. <span class=\"citation\">Targ. Is. IX, 4</span>.</div>","alt":["מֵיסַב","מֵסַב","מְסַב"]},"13216":{"h":"מֵיסֵב","r":"M01240","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵסֵב\">מֵסֵב</a></div>","alt":[]},"13217":{"h":"מיסוון","r":"M01241","html":"<div class=\"sense\">, read:</div>","alt":[]},"13218":{"h":"מִיסוֹן","r":"M01242","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μέσος -ον,) <i>middle</i>. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד מאת׳ 7) <span dir=\"rtl\">במ׳ דאורחא</span> in the middle of the road. Ib. <span dir=\"rtl\">במ׳ דחנותא</span> (<span dir=\"rtl\">חד מירוש׳</span>) Ar. (ed. <span dir=\"rtl\">במצעי</span>) in the middle of the shop.</div>","alt":[]},"13219":{"h":"מִיסּוּן","r":"M01243","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (missus) <i>course</i> at dinner. Tanḥ. ed. Bub. <span class=\"citation\">B’resh. 2</span> <span dir=\"rtl\">מ׳ מ׳</span> course after course.—Pl. same. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כמה מ׳ היה לך</span> how many courses had you?—Y’lamd. to Num. I, quot. in Ar. <span dir=\"rtl\">כמה מיסא</span> (corr. acc.).</div>","alt":[]},"13220":{"h":"מִיסְטוּרִין","r":"M01244","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"מִסְטְרִין\">מִסְט׳</a>.</div>","alt":["מִיסְטֵירין"]},"13221":{"h":"מִיסִּים","r":"M01245","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַס I\">מַס</a></div>","alt":["מִיסִּין"]},"13222":{"h":"מיסיק","r":"M01246","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָסִיק\">מָסִיק</a></div>","alt":[]},"13223":{"h":"מִיסְכּ־","r":"M01247","html":"<div class=\"sense\">, v. <span dir=\"rtl\">מִסְכּ׳</span></div>","alt":[]},"13224":{"h":"מִיסְמֵס","r":"M01248","html":"<div class=\"sense\"><i>semissis</i>, v. <a href=\"#\" data-headword=\"מְסִימִיס\">מְסִימִיס</a>.</div>","alt":[]},"13225":{"h":"מיסמרא","r":"M01249","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַסְמָר ²\">מַסְמְרָא</a></div>","alt":[]},"13226":{"h":"מיסן","r":"M01250","html":"<div class=\"sense\">, <span class=\"citation\">Y. Gitt. I, 43ᵇ</span>, a corrupt., prob. for (<a href=\"#\" data-headword=\"כְּעַס\">כְּעַס</a>) <a href=\"#\" data-headword=\"כַּעֲסָא\">כַּעֲסָן</a> <i>hot-tempered</i>. [Comment.: = <a href=\"#\" data-headword=\"אסיא\">אסיא</a> <i>physician</i>,—does not fit the context.]</div>","alt":[]},"13227":{"h":"מִיסְפָּק","r":"M01251","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסְפְּק\">מִסְפָּק</a></div>","alt":[]},"13228":{"h":"מִיסַּק","r":"M01252","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְסַק\">נְסַק</a>) <i>rising</i>, (<i>sun</i>-) <i>rise</i>. <span class=\"citation\">Targ. Ps. XXII, 5</span>. <span class=\"citation\">Targ. Cant. III, 6</span>, a. e., v. <a href=\"#\" data-headword=\"קְרִיצְתָּא\">קְרִיצְתָּא</a>.</div>","alt":["מִסַּק"]},"13229":{"h":"מֵיסָרָא","r":"M01253","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲסַר\">אֲסַר</a>) <i>bunch</i>.—Pl. <a href=\"#\" data-headword=\"*מִיסְרָן\">מֵיסָרָן</a>. <span class=\"citation\">Y. Shebi. II, 34ᵃ</span> bot., v. <a href=\"#\" data-headword=\"לוּבִי\">לוּבִי</a>.</div>","alt":[]},"13230":{"h":"*מִיסְרָן","r":"M01254","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סוּר\">סוּר</a>) <i>seducer, tempter</i>. <span class=\"citation\">Pes. 107ᵃ</span> Ar., v. <a href=\"#\" data-headword=\"פִּיס\">פִּיס</a> h.</div>","alt":[]},"13231":{"h":"מִיסַּת","r":"M01255","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסַּת\">מִסַּת</a>, <a href=\"#\" data-headword=\"מִסְתּוּ\"><a href=\"#\" data-headword=\"מִסְתּוּ\">מִסְתּוּ</a>.</a></div>","alt":["מִיסְתּוּ"]},"13232":{"h":"מִיסְתּוֹסִיס","r":"M01256","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (μίσθωσις) <i>lease, rent</i>. Y. Pes. VI, 31ᵇ bot. <span dir=\"rtl\">מיסתיו׳</span> (corr. acc.); v. <a href=\"#\" data-headword=\"אוֹנִי I\"><span dir=\"rtl\">אוֹנִי</span> I</a>.</div>","alt":[]},"13233":{"h":"מִיסְתְּיָא","r":"M01257","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">מִסְתְּ׳</span>.</div>","alt":["מִיסְתְּיָיא"]},"13234":{"h":"מיסתיוסיס","r":"M01258","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִיסְתּוֹסִיס\">מִיסְתּוֹסִיס</a></div>","alt":[]},"13235":{"h":"מִיעוּט","r":"M01259","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָעַט\">מָעַט</a>) </div><div class=\"sense\"><b>1)</b> <i>reduction of size, the space reduced</i>. <span class=\"citation\">Erub. 77ᵃ</span> <span dir=\"rtl\">אם יש במִיעוּטוֹ וכ׳</span> if the reduction of the height (by lowering the wall or raising the embankment) extends over four handbreadths; <span dir=\"rtl\">כנגד המ׳</span> only as far as the reduction extends.</div><div class=\"sense\"><b>—2)</b> <i>minority</i>. <span class=\"citation\">Y. Pes. VII, 34ᶜ</span> bot. <span dir=\"rtl\">כרוב או כמ׳</span> (not <span dir=\"rtl\">כרוב׳ במ׳</span>) do we treat the case as if it were a majority (of unclean persons), or as if it were a minority? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אין תימר כמ׳</span> (not <span dir=\"rtl\">במ׳</span>) if you will consider it a minority. <span class=\"citation\">Y. Kidd. I, 59ᵇ</span> top. <span class=\"citation\">Yeb. 119ᵃ</span> <span dir=\"rtl\">מ׳ מפילות</span> a minority of women miscarry; a. e.</div><div class=\"sense\"><b>—3)</b> <i>the least of</i>. <span class=\"citation\">R. Hash. 11ᵃ</span>; <span class=\"citation\">Yeb. 42ᵃ</span>; <span class=\"citation\">Nidd. 38ᵇ</span> (ref. to <span class=\"citation\">I Sam. I, 20</span>) <span dir=\"rtl\">מ׳ תקופות וכ׳</span> the least of <i>t’kufoth</i> (plural number) is two (seasons, of three months each), the least of <i>yamin</i> is two days; a. e.</div><div class=\"sense\"><b>—4)</b> <i>narrowing qualification, limitation</i>. <span class=\"citation\">Yoma 43ᵃ</span>; <span class=\"citation\">B. Kam. 86ᵇ</span>, a. fr. <span dir=\"rtl\">הוי מ׳ אחר מ׳ ואין מ׳ אחר מ׳ אלא וכ׳</span> this is a limitation following a limitation, and a double limitation serves to widen the scope (because the repetition indicates that no limitation is meant, but only an exemplification); Y. Peah V, end, 19ᵈ (corr. acc.). <span class=\"citation\">Y. Hor. I, beg. 45ᶜ</span> <span dir=\"rtl\">מ׳ אחר מ׳ אחר מ׳</span> three successive limitations. <span class=\"citation\">Lev. R. s. 24</span>, end <span dir=\"rtl\">ת&quot;ל רק לשון מ׳</span> it says ‘only’ (<span class=\"citation\">Deut. XXVIII, 13</span>) which intimates a limitation; a. fr.—Pl. <span dir=\"rtl\">מִיעוּטִים</span>, <span dir=\"rtl\">מִיעוּטִין</span>, <a href=\"#\" data-headword=\"מַעְשְׂרָא\">מִע׳</a>. <span class=\"citation\">Tosef. Shebu. I, 7</span> <span dir=\"rtl\">הוה דורש ריבויין ומ׳</span> interpreted the Bible texts with a view to widening and narrowing the limits of the respective laws. <span class=\"citation\">Y. Sabb. VII, 10ᵇ</span> אך הוא הרי אלו מ׳ וכ׳ <i>akh</i> and <i>hu</i> (<span class=\"citation\">Ex. XII, 16</span>, are limiting qualifications intimating that you must not cut, grind &amp;c. (on the Holy Day). <span class=\"citation\">Y. Ber. IX, 14ᵇ</span> bot., v. <a href=\"#\" data-headword=\"אַךְ I\"><span dir=\"rtl\">אַךְ</span> I</a>; a. fr.</div>","alt":["מִעוּט"]},"13236":{"h":"מִיעוּטָא","r":"M01260","html":"<div class=\"sense\"> <span class=\"citation\">Erub. 77ᵃ</span> <span dir=\"rtl\">אי אהני מ׳</span> if the reduction has any effect. <span class=\"citation\">Yeb. 119ᵃ</span> <span dir=\"rtl\">סמוך מ׳ דמפילות וכ׳</span> add the minority of miscarrying women to the half of female births, and the male births will be a minority. <span class=\"citation\">Ḥull. 6ᵃ</span>, a. fr. <span dir=\"rtl\">חייש למ׳</span> takes into consideration the minority (the possibility of the rarer cases). <span class=\"citation\">Yeb. 119ᵇ</span>, a. e. <span dir=\"rtl\">מ׳ דמ׳ לא חייש</span> a minority of a minority he does not take into consideration. <span class=\"citation\">Kidd. 80ᵃ</span> <span dir=\"rtl\">מ׳ כמאן דליתא דמי</span> a minority is considered as non-existent.—Pl. <span dir=\"rtl\">מִיעוּטֵי</span>. <span class=\"citation\">Snh. 45ᵇ</span>, sq. <span dir=\"rtl\">דריש ריבויי ומ׳</span>, v. <a href=\"#\" data-headword=\"מִיעוּט\">preced.</a></div>","alt":[]},"13237":{"h":"מֵיעַיִם","r":"M01261","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"מַעְשְׂרָא\">מֵעַ׳</a>.</div>","alt":["מֵיעַיִן"]},"13238":{"h":"מֵיעֵין","r":"M01262","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"עַיִן\">עַיִן</a></div>","alt":[]},"13239":{"h":"מֵיעִירְקָא","r":"M01263","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְעַרְקָא\">מְעַרְקָא</a></div>","alt":[]},"13240":{"h":"מֵיעֲלָא","r":"M01264","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵעֲלָא\">מֵעֲלָא</a></div>","alt":["מֵיעֲלֵי"]},"13241":{"h":"מִיפְּחַזְנָא","r":"M01265","html":"<div class=\"sense\"> (a feigned part. Ithp. of <span dir=\"rtl\">פחז</span>, denomin. of <span dir=\"rtl\">פחיז</span>, a substitute of <a href=\"#\" data-headword=\"פָּזִיחַ\">פזיח</a> which again is a substitute of <span dir=\"rtl\">נזיר</span>, v. <a href=\"#\" data-headword=\"כִּינּוּי\">כִּינּוּי</a>) <i>I will be a paḥiz</i>. <span class=\"citation\">Ned. 10ᵇ</span> <span dir=\"rtl\">מ׳ מאי</span> how is it, if one says <i>mipp’ḥazna</i> (for <i>mipp’ziḥna</i>)?</div>","alt":[]},"13242":{"h":"מִיפַּטְרָא","r":"M01266","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִפְטְרָא\">מִפְטְרָא</a></div>","alt":[]},"13243":{"h":"מֵיפַךְ","r":"M01267","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲפַךְ\">אֲפַךְ</a></div>","alt":[]},"13244":{"h":"מִיפְסוֹלַת","r":"M01268","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִפְסַלְתָּא\">מִפְסַלְתָּא</a></div>","alt":["מִיפְסְלַת"]},"13245":{"h":"מִיפְּקָא","r":"M01269","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְפַק\">נְפַק</a>) </div><div class=\"sense\"><b>1)</b> <i>exit, end</i>. <span class=\"citation\">Targ. Ex. XXXIV, 22</span> (ed. Berl. <span dir=\"rtl\">מִיפְּקַהּ</span>; cod. 7 <span dir=\"rtl\">מַפְּקָהּ</span>; oth. <a href=\"#\" data-headword=\"מִפְקָא\">מִפְקָא</a>, <span dir=\"rtl\">מִפְקַת</span>; v. Berl. Targ. O. II, p. 31); ib. XXIII, 16.—Pl. <span dir=\"rtl\">מִיפְּקֵי</span>, <span dir=\"rtl\">מִפְקֵי</span>. <span class=\"citation\">Y. Ter. VIII, 46ᵇ</span> bot., sq. <span dir=\"rtl\">במ׳ שובתא</span> = h. <span dir=\"rtl\">מוצאי שבת</span>, v. <a href=\"#\" data-headword=\"מוֹצָא III\"><span dir=\"rtl\">מוֹצָא</span> III</a>.</div><div class=\"sense\"><b>—2)</b> <i>going out</i>, v. <a href=\"#\" data-headword=\"מֵעֲלָא\">מֵעֲלָא</a>.</div>","alt":["מִפְקָא"]},"13246":{"h":"מִיץ","r":"M01270","html":"<div class=\"sense\"><i>to suck</i>, v. <a href=\"#\" data-headword=\"מוּץ\">מוּץ</a>.</div>","alt":[]},"13247":{"h":"מִיץ ²","r":"M01271","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>that which is won by squeezing</i>,] <i>juice</i>. <span class=\"citation\">Y. Naz. I, 51ᵇ</span> <span dir=\"rtl\">מ׳ של ערלה</span> the juice of ‘Orlah fruits (v. <a href=\"#\" data-headword=\"עָרְלָה\">עָרְלָה</a>).</div>","alt":[]},"13248":{"h":"מִיצַּב","r":"M01272","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַצָּבָא\">מַצָּבָא</a></div>","alt":[]},"13249":{"h":"מִיצָה","r":"M01273","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוּץ\">מוּץ</a>) [<i>that which is squeezed in</i>,] <i>the joint</i> or <i>collar</i> of reeds, stalks &amp;c. <span class=\"citation\">Kel. IX, 8</span> <span dir=\"rtl\">מ׳ שניה של שיפון</span> the second joint of a stem of oats; <span dir=\"rtl\">מ׳ … של קנה</span> of reeds.</div>","alt":[]},"13250":{"h":"מִיצּוּי","r":"M01274","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָצָה\">מָצָה</a>) </div><div class=\"sense\"><b>1)</b> <i>squeezing, wringing out</i> (of the blood of the sacrifice). <span class=\"citation\">Zeb. 52ᵃ</span>. <span class=\"citation\">Ib. 65ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"בֵּירוּר\">בֵּירוּר</a>) <i>exact measure</i>. <span class=\"citation\">Bets. III, 8</span> <span dir=\"rtl\">אף בחול … מפני מ׳ המדות</span> in week-days he did the same (filled the measures beforehand) for the sake of exact measure (in order to allow the liquids to settle). <span class=\"citation\">Ib. 29ᵃ</span> they collected three hundred <i>garab</i> of oil <span dir=\"rtl\">ממ׳ המדות</span> as the surplus in his accounts realized from the remnants in the measures; <span class=\"citation\">Tosef. ib. III, 8</span> (v. ed. Zuck. Var.).—Trnsf. <span dir=\"rtl\">מ׳ הנפש</span> [<i>the squeezing of the soul out of the body</i>,] <i>agony of death</i>. Tanḥ. Mick. 10 (ref. to <a href=\"#\" data-headword=\"מָצָא\">מְצֹא</a>, <span class=\"citation\">Ps. XXXII, 6</span>) <span dir=\"rtl\">יתפלל על מ׳ הנ׳</span> let him pray that he may be spared the agony of death.—<span dir=\"rtl\">מ׳ היום</span> [<i>the pressing through of the day</i>,] <i>sunrise</i> and <i>sunset</i>. <span class=\"citation\">Gen. R. s. 92</span> (ref. to Ps. l. c.) <span dir=\"rtl\">לעת מ׳ היום</span> at evening-time; <span class=\"citation\">Y. Ber. IV, 7ᵇ</span> bot. <span dir=\"rtl\">לעת מִיצּוּיָו של יום</span> (pl.) at morning and at evening, v. <a href=\"#\" data-headword=\"דִּמְדּוּם\">דִּמְדּוּם</a>.—מ׳ הדין <i>final</i> (<i>exact</i>) <i>judgment</i> (after death); <span dir=\"rtl\">מ׳ החשבון</span> final count (of sins). Gen. R. l. c.—Pl. <span dir=\"rtl\">מִיצּוּיִין</span>, with suffix <span dir=\"rtl\">מִיצּוּיָו</span> (cmp. <span dir=\"rtl\">מְנוּיָו</span> for <span dir=\"rtl\">מְנוּיָיו</span> s. v. <a href=\"#\" data-headword=\"מני\">מָנָה</a>); v. supra.</div>","alt":["מִצּ׳"]},"13251":{"h":"מִיצּוּעַ","r":"M01275","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְצַע\">מְצַע</a>) <i>middle, midst</i>. <span class=\"citation\">Targ. Job VII, 12</span> (Ms. <span dir=\"rtl\">מִיצְּע׳</span>). <span class=\"citation\">Targ. Y. Deut. XXIII, 11</span>.</div>","alt":["מִצּ׳"]},"13252":{"h":"מִיצְטְרָא","r":"M01276","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μύστρος, -ον) <i>spoon</i>.—<span dir=\"rtl\">מ׳ מכירין</span> (v. <a href=\"#\" data-headword=\"מְכֵירִין\">מְכֵירִין</a>) <i>mystromacherion</i>, an instrument having a spoon on one side and a knife on the other (cmp. Sm. Ant. s. v. Cochlear). <span class=\"citation\">Lev. R. s. 33</span>, beg. (ref. to <span class=\"citation\">Prov. XVIII, 21</span>) <span dir=\"rtl\">תרגם עקילס מ׳ מ׳ וכ׳</span> Aquila interpreted it, ‘a spoon-knife’, death on one side and life on the other; Yalk. ib. 661 <span dir=\"rtl\">מציטאר מ׳</span>; Yalk. Ps. 768 <span dir=\"rtl\">מצטרו ומ׳</span> (read: <span dir=\"rtl\">מצטרומ׳</span>).</div>","alt":["מִצְ׳"]},"13253":{"h":"מיצטרו","r":"M01277","html":"<div class=\"sense\">, <span class=\"citation\">Sabb. 154ᵇ</span>, v. <a href=\"#\" data-headword=\"צְרָא\">צְרָא</a></div>","alt":[]},"13254":{"h":"מִיצְלַת","r":"M01278","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְצִילְתָּא\">מְצִילְתָּא</a></div>","alt":[]},"13255":{"h":"מִיצַּע","r":"M01279","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"מִיצּוּעַ\">מִיצּוּעַ</a>. <span class=\"citation\">Targ. Y. Num. XVII, 12</span>, sq. (ed. Amst. <a href=\"#\" data-headword=\"מִצַּע\">מַצַּע</a>). <span class=\"citation\">Targ. Y. I ib. XXII, 24</span>. <span class=\"citation\">Targ. Y. I Ex. XIV, 27</span>; a. fr.—<span class=\"citation\">B. Mets. 108ᵃ</span> [read:] <span dir=\"rtl\">במ׳ דנכסיה</span> (Rashi: <span dir=\"rtl\">בי מִיצְּעֵי</span>) in the centre of his (the seller’s) land).</div>","alt":["מִיצְּעָא","מַצּ׳"]},"13256":{"h":"מִיצָּעָא","r":"M01280","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"מְצִיעַ\">מְצִיעָא</a>) <i>central, middle, between extremes.</i> <span class=\"citation\">Targ. Y. Lev. XIV, 17</span>, v. <a href=\"#\" data-headword=\"גְּדֵירָא\">גְּדֵירָא</a>.—<span class=\"citation\">Ned. 31ᵇ</span> top <span dir=\"rtl\">זבינא מ׳</span> (R. N. <a href=\"#\" data-headword=\"מְצִיעַ\">מציעא</a>) middle goods (holding the mean between goods which the seller is anxious to get rid of, and such as are sought after eagerly), v. <a href=\"#\" data-headword=\"חֲרִיפָא\">חְרִיפָא</a>.—Pl. <a href=\"#\" data-headword=\"מִיצַּע\">מִיצְּעָאֵי</a>, <span dir=\"rtl\">מִיצְּעֵי</span>. <span class=\"citation\">Targ. II Chr. VI, 18</span> (ed. Lag. <span dir=\"rtl\">מְצִיעָאֵי</span>).—<span class=\"citation\">Ber. 18ᵇ</span>. <span class=\"citation\">Ker. 6ᵇ</span> <span dir=\"rtl\">במ׳</span> in between (the other ingredients). <span class=\"citation\">B. Mets. 108ᵃ</span>, v. preced.—<span class=\"citation\">Naz. 56ᵇ</span> <span dir=\"rtl\">מ׳ לא אמרינן</span> those intermediate in the chain of tradition need not be mentioned (only the first and the last). V. <a href=\"#\" data-headword=\"מְצִיעַ\">מְצִיעָא</a>.</div>","alt":["מִיצְעָא"]},"13257":{"h":"מֵיצֵף","r":"M01281","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צוּף\">צוּף</a></div>","alt":[]},"13258":{"h":"מֵיצַר","r":"M01282","html":"<div class=\"sense\"><b>1)</b>  part. Hif. of part. Hif. of <a href=\"#\" data-headword=\"צָרַר\">צָרַר</a> q. v.</div><div class=\"sense\"><b>—2)</b> <i>pathway, narrow, balk</i>, v. <a href=\"#\" data-headword=\"מֵצַר\">מֵצַר</a>.</div>","alt":[]},"13259":{"h":"מִיצְרָא","r":"M01283","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"מִיצְטְרָא\">מִצְ׳</a>.</div>","alt":["מִיצְרָאָה"]},"13260":{"h":"מִיק","r":"M01284","html":"<div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"מוּק\">מַיֵּיק</a>, v. <a href=\"#\" data-headword=\"מוּק\">מוּק</a>.</div>","alt":[]},"13261":{"h":"מֵיקֵל","r":"M01285","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָלַל\">קָלַל</a>, <a href=\"#\" data-headword=\"קְלַל\"><a href=\"#\" data-headword=\"קְלַל\">קְלַל</a>.</a>—[Y. Dem. III, beg. 26ᵃ <span dir=\"rtl\">מי׳ בלשי</span>, read: <a href=\"#\" data-headword=\"מַקֵּל\">מַקַּל</a>.]</div>","alt":["מֵיקַל"]},"13262":{"h":"מֵיקַם","r":"M01286","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קוּם\">קוּם</a>) <i>standing</i>. <span class=\"citation\">Targ. Josh. IV, 3</span> <span dir=\"rtl\">אתר מ׳</span> (h. text <span dir=\"rtl\">מצב</span>).</div>","alt":["מֵקַם"]},"13263":{"h":"מִיקְמַת","r":"M01287","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְקָם\">מְקָמָא</a></div>","alt":[]},"13264":{"h":"מִיקַן","r":"M01288","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"מִיק\">מִיק</a>; cmp. <a href=\"#\" data-headword=\"*דַּאֲבַן\">דַּאֲבַן</a> <i>to mock</i>. <span class=\"citation\">Targ. Ps. CXIX, 51</span> <span dir=\"rtl\">מְמִיקְנִין</span> ed. Lag. (ed. … <a href=\"#\" data-headword=\"נַן\">נָן</a>, … <a href=\"#\" data-headword=\"נַן\">נַן</a>).</div>","alt":[]},"13265":{"h":"מֵיקַר","r":"M01289","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרַר I\">קָרַר</a>) <i>cooling</i>. <span class=\"citation\">Tosef. Sabb. XVII</span> (<span class=\"citation\">XVIII), 18</span>; <span class=\"citation\">Sabb. 151ᵇ</span> <span dir=\"rtl\">כלי מ׳</span> cooling vessels (glass &amp;c.). <span class=\"citation\">Ib. 53ᵇ</span> <span dir=\"rtl\">אין מ׳ לבהמה</span> cooling (as placing in water) is not generally done to beasts (unless they are sick).—[Part. <i>Hif.</i> <a href=\"#\" data-headword=\"מֵיקַר\">מיקר</a>, v. <a href=\"#\" data-headword=\"קָרַר I\">קָרַר</a>.]</div>","alt":[]},"13266":{"h":"מֵירָא","r":"M01290","html":"<div class=\"sense\"><i>myrrh</i>, v. <a href=\"#\" data-headword=\"מוֹר ²\">מוּרָא</a>.</div>","alt":[]},"13267":{"h":"מֵירְדָא","r":"M01291","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵרַד\">מֵרְדָא</a></div>","alt":[]},"13268":{"h":"מירה","r":"M01292","html":"<div class=\"sense\">, Yalk. Zeph. 567, v. <a href=\"#\" data-headword=\"מוֹרָא II\"><span dir=\"rtl\">מוֹרָא</span> II</a></div>","alt":[]},"13269":{"h":"מֵירוּג","r":"M01293","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <span dir=\"rtl\">מְאָרֵג</span>, v. <a href=\"#\" data-headword=\"אָרַג\">אָרַג</a>) <i>selecting the green and tender onions in the bed</i>. <span class=\"citation\">Y. Peah III, 17ᶜ</span> top <span dir=\"rtl\">ואי דינו מ׳</span> and what is <i>merug?</i> [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">המירוג</span>, read: <span dir=\"rtl\">המְאָרֵג</span>, v. <a href=\"#\" data-headword=\"אָרַג\">אָרַג</a>.]</div>","alt":[]},"13270":{"h":"מֵירוֹן","r":"M01294","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵרוֹן\">מֵרוֹן</a></div>","alt":[]},"13271":{"h":"מֵירוּק","r":"M01295","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָרַק\">מָרַק</a>) <i>polishing, finishing</i>. Pesik. Naḥ., p. 127ᵃ <span dir=\"rtl\">דבריכם צריכין מ׳</span> your words require polishing (are incomplete).—Euphem. <i>sexual gratification attended with effusion of semen</i>. <span class=\"citation\">Yeb. 55ᵇ</span></div>","alt":[]},"13272":{"h":"מירוק","r":"M01296","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Dem. IV, 13</span>, v. <a href=\"#\" data-headword=\"מֵרוֹן\">מֵרוֹן</a></div>","alt":[]},"13273":{"h":"מֵירוּר","r":"M01297","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָרַר\">מָרַר</a>) <i>embittering, hard labor</i> (with ref. to <span class=\"citation\">Ex. I, 14</span>). <span class=\"citation\">Num. R. s. 3</span> the family was called M’rari, <span dir=\"rtl\"><span dir=\"rtl\">על</span> (<a href=\"#\" data-headword=\"שֵׁם I\">שם</a>) <a href=\"#\" data-headword=\"מ׳\">מ׳</a></span> an allusion to their bitter task (of carrying the wooden material of the Tabernacle). <span class=\"citation\">Pesik. R. s. 15</span> מרים … לשון מ׳ Miriam intimates the bitterness (of slavery); <span class=\"citation\">Yalk. Cant. 986</span>. [<span class=\"citation\">Cant. R. to II, 11</span>, a gloss.]</div>","alt":[]},"13274":{"h":"מִירְטוֹם","r":"M01298","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָרַט\">מָרַט</a>) <i>a bird that has lost its feathers</i>. <span class=\"citation\">Y. Meg. I, 72ᵇ</span></div>","alt":[]},"13275":{"h":"מִירִי","r":"M01299","html":"<div class=\"sense\"> (μυρι-μυριάδες) <i>ten thousand times ten thousand</i>. Pesik. Baḥod., p. 107ᵇ; <span class=\"citation\">Yalk. Ps. 796</span> (corr. acc.); v., however, <a href=\"#\" data-headword=\"כִּילִי\">כִּילִי</a>.</div>","alt":["מ׳ מִירְיָאדִין"]},"13276":{"h":"מירין","r":"M01300","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Neg. III, 10</span> <span dir=\"rtl\">והמ׳</span> ed. Zuck. (Var. <span dir=\"rtl\">והמידק</span>), read: <span dir=\"rtl\">והמוֹרְדִין</span>, v. <a href=\"#\" data-headword=\"מָרַד II\"><span dir=\"rtl\">מָרַד</span> II</a></div>","alt":[]},"13277":{"h":"מִירָם","r":"M01301","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲמִירָם\">הֲמִירָם</a></div>","alt":["מירָס"]},"13278":{"h":"מִירְסִינָטוֹן","r":"M01302","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μυρσινᾶτον, S. = Lat. myrtatum) (<i>wine</i> or <i>oil</i>) <i>flavored with myrtle-leaves</i>. Y. Shebi. VII, 37ᵇ (some ed. <span dir=\"rtl\">מור׳</span>).</div>","alt":[]},"13279":{"h":"מֵירַע","r":"M01303","html":"<div class=\"sense\"><i>weakening</i>, v. <a href=\"#\" data-headword=\"מֵרַע\">מֵרַע</a>.</div>","alt":[]},"13280":{"h":"מִירְעָא","r":"M01304","html":"<div class=\"sense\"><i>pasture</i>, v. <a href=\"#\" data-headword=\"מַרְעֵי I\"><span dir=\"rtl\">מַרְעֵי</span> I</a>.</div>","alt":[]},"13281":{"h":"מירקו","r":"M01305","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Mikv. VI</span> (<span class=\"citation\">VII), 13</span> ed., read with ed. Zuck. <a href=\"#\" data-headword=\"סִידְקִי\">סִידְקֵי</a>, v. <a href=\"#\" data-headword=\"סֶדֶק\">סֶדֶק</a>.</div>","alt":[]},"13282":{"h":"מֵירַת","r":"M01306","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יְרֵת\">ירת</a>, as <a href=\"#\" data-headword=\"תִּירוֹשׁ\">תִּירוֹשׁ</a> fr. <a href=\"#\" data-headword=\"יָרַשׁ\">ירש</a>, v. Fl. to Levy Targ. Dict. II, p. 568<sup>1</sup>) <i>must, juice</i>. <span class=\"citation\">Targ. Y. Deut. XXIX, 5</span> (h. text <span dir=\"rtl\">שכר</span>). V. <a href=\"#\" data-headword=\"מְרֵית\">מְרֵית</a>.</div>","alt":["מֵרַת"]},"13283":{"h":"מֵישָׁא I","r":"M01307","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מֵישָׁא II\">next w.</a>) <i>Mesha</i>, </div><div class=\"sense\"><b>1)</b>  a place in northern Galilee (v. Hildesh., Beitr. p. 38). <span class=\"citation\">Tosef. Shebi. IV, 11</span> ed. Zuck. note (Var. <a href=\"#\" data-headword=\"מַיְישָׁא\">מַיְישָׁא</a>).</div><div class=\"sense\"><b>—2)</b>  M. in Babylonia, in the district of Mesene, v. <a href=\"#\" data-headword=\"מֵישָׁן\">מֵישָׁן</a>. <span class=\"citation\">Y. Yeb. I, 3ᵇ</span>; <span class=\"citation\">Y. Kidd. IV, 65ᵈ</span> top. <span class=\"citation\">Gen. R. s. 37</span> <span dir=\"rtl\">מֵישָׁה</span> (identified with <a href=\"#\" data-headword=\"מֵשָׁא\">מֵשָׁא</a>, <span class=\"citation\">Gen. X, 30</span>; Targ. <a href=\"#\" data-headword=\"מֵשָׁא\">מֵשָׁא</a>, <a href=\"#\" data-headword=\"מֵישָׁא I\">מֵישָׁא</a>). [Talm. Bab. <a href=\"#\" data-headword=\"מֵישָׁן\">מֵישָׁן</a> q. v.]</div>","alt":[]},"13284":{"h":"מֵישָׁא II","r":"M01308","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"מַאיְשָׁא\">מאישא</a>, <a href=\"#\" data-headword=\"מֵיאֲשָׁא\">מיאשא</a>) pr. n. m. <i>Mesha</i> (= <span dir=\"rtl\">משחא</span>, v. Nöld. Mand. Gr., p. 64), name of several persons. <span class=\"citation\">Erub. 13ᵇ</span> לא ר׳ מאיר … אלא מיישא Ms. M. (ed. <a href=\"#\" data-headword=\"נְהוֹרַאי\">נהוראי</a>, v. Rabb. D. S. a. l. note), v. <a href=\"#\" data-headword=\"מֵאִיר\">מֵאִיר</a>. <span class=\"citation\">Peah II, 6</span> מישא Y. ed. (Ms. M. <span dir=\"rtl\">מיי׳</span>; ed. <span dir=\"rtl\">מיא׳</span>, v. Rabb. D. S. a. l. note); <span class=\"citation\">Naz. 56ᵇ</span> <span dir=\"rtl\">מיא׳</span>.—<span class=\"citation\">Ḥull. 121ᵃ</span> <span dir=\"rtl\">מיי׳</span>. <span class=\"citation\">Y. Orl. I, 61ᵃ</span> bot.; <span class=\"citation\">Y. Maasr. V, 51ᵈ</span> top.—<span class=\"citation\">Y. Sabb. I, 3ᵃ</span> bot.; <span class=\"citation\">Y. Ber. II, end, 5ᵈ</span> <a href=\"#\" data-headword=\"יַסָּא\">יסא</a> (corr. acc.).—Ib. 4ᶜ bot. M., grandson of R. Joshua b. Levi.—<span class=\"citation\">Y. Sabb. I, 2ᶜ</span> top.—<span class=\"citation\">Y. Naz. IX, 57ᵈ</span> bot. M., son of R. Jeremiah.—<span class=\"citation\">Y. Pes. IV, 30ᵈ</span> top <span dir=\"rtl\">בני מ׳</span> members of the Mesha family.</div>","alt":["מַיְישָׁא"]},"13285":{"h":"מִישַּׁבַּקְתָּא","r":"M01309","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְשַׁבְּקָא II\"><span dir=\"rtl\">מְשַׁבְּקָא</span> II</a></div>","alt":[]},"13286":{"h":"מֵישׁוֹן","r":"M01310","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵישָׁן\">מֵישָׁן</a></div>","alt":[]},"13287":{"h":"מִישׁוֹר","r":"M01311","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>plain, level; common</i> (cmp. <a href=\"#\" data-headword=\"בִּקְעָה\">בִּקְעָה</a>). <span class=\"citation\">Yoma 75ᵃ</span> (play on <span dir=\"rtl\">מישרים</span>, <span class=\"citation\">Prov. XXIII, 31</span>) <span dir=\"rtl\">עריות כולן דומות עליו כמ׳</span> all forbidden connections appear to him like a common (to which all have access). Ib. <span dir=\"rtl\">כל העולם … כמ׳</span> the entire world appears to him like a common (he disregards other people’s rights); <span class=\"citation\">Num. R. s. 10</span> <span dir=\"rtl\">עושה אותן הפקר כמ׳</span> he considers all sins free like a common. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שנוטלין … בתיהם כמ׳</span> they (the oppressors) carry off all that belongs to them (the Jews), and their houses are left levelled like a common. Tanḥ. R’eh 3 <span dir=\"rtl\">אחת תחלתה קוצים וסופה מ׳ ואחת תחלתה מ׳ וכ׳</span> one road full of thorns in the beginning but level in the end, and one level in the beginning &amp;c.; a. e.</div>","alt":[]},"13288":{"h":"מִישְׁחָא","r":"M01312","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">מִשְׁח׳</span>.</div>","alt":["מִישְׁחָן","מִישְׁחֲתָא"]},"13289":{"h":"מִישְּׁכּוֹנָא","r":"M01313","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">משׁכּ׳</span>.</div>","alt":["מִישְׁכָּן","מִישְׁכְּנוּתָא"]},"13290":{"h":"מִישְׁלָם","r":"M01314","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִשְׁלָם\">מִשְׁלָם</a></div>","alt":[]},"13291":{"h":"מֵישָׁן","r":"M01315","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מֵישָׁא I\"><span dir=\"rtl\">מֵישָׁא</span> I</a>) <i>Meshan, Mesene</i>, the island formed by the Euphrates, the Tigris and the Royal Canal. Kil. 49ᵇ <span dir=\"rtl\">תשעה נטלה מ׳</span> nine measures (of impudence) M. has carried off. Ib. 71ᵇ, a. e. <span dir=\"rtl\">מֵישׁוֹן מיתה</span> M. is dead (for purity of descent), v. <a href=\"#\" data-headword=\"גֹּוסֵס\">גּוֹסֵס</a>. <span class=\"citation\">Yoma 10ᵃ</span> (expl. <span dir=\"rtl\">רחבת עיר</span>, <span class=\"citation\">Gen. X, 11</span>) <span dir=\"rtl\">פרת דמ׳</span> <i>Perath Meshan</i> (v. Berl. Beitr. z. Geogr., p. 44). <span class=\"citation\">B. Kam. 97ᵇ</span> <span dir=\"rtl\">יכול … הוציאו במ׳</span> he may say to him, pass it (the repealed coin) in Mesene. <span class=\"citation\">B. Bath. 73ᵃ</span> <span dir=\"rtl\">דמיאשן</span>; <span class=\"citation\">Sabb. 101ᵃ</span> <span dir=\"rtl\">דמיש׳</span>, v. <a href=\"#\" data-headword=\"בִּיצִּיתָא\">בִּיצִּיתָא</a>. <span class=\"citation\">Kidd. 72ᵇ</span>, v. <a href=\"#\" data-headword=\"אִסְטַנְדְּרָא\">אִסְטַנְדְּרָא</a>.</div>","alt":["מֵישׁוֹן"]},"13292":{"h":"מֵישָׁנִי","r":"M01316","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מֵישָׁן\">preced.</a>) <i>Mesenian</i>. <span class=\"citation\">Kidd. 71ᵇ</span> <span dir=\"rtl\">הא דמשתעיא מ׳</span> that Apamea where the Mesenian dialect is spoken.</div>","alt":["מֵישָׁנִית"]},"13293":{"h":"מֵישַׁר","r":"M01317","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>straight line, horizontal, level</i>. <span class=\"citation\">Kidd. II, 6</span> <span dir=\"rtl\">לעשות שדהו מ׳ מ׳</span> to divide his field in straight lines (beds) of various seeds (instead of squares, <a href=\"#\" data-headword=\"מְרוּבָּע\">מרובע</a>). Y. ib. II, 28ᵃ top. Y. Erub. IV, 21ᵈ bot. a telescope (v. <a href=\"#\" data-headword=\"מְצוֹפוֹת\">מְצוֹפוֹת</a>) <span dir=\"rtl\">שהיה משער בה עיניו במ׳</span> the horizontal range of which he had tested before (v. Bab. <span class=\"citation\">Erub. 43ᵇ</span>).—Y. ib. V, 22ᵈ top [read:] <span dir=\"rtl\">מביא מצופות ומשער … במ׳ וכ׳</span></div>","alt":["מֵשַׁר"]},"13294":{"h":"מֵישָׁרָא","r":"M01318","html":"<div class=\"sense\"><b>1)</b> <i>bed</i>.—Pl. <a href=\"#\" data-headword=\"מֵישְׁרָא II\">מֵישָׁרֵי</a>, <span dir=\"rtl\">מֵשָׁארֵי</span>. <span class=\"citation\">Kidd. 39ᵃ</span> זרע … מישרי מ׳ Ar. (ed. <a href=\"#\" data-headword=\"מֵשָׁא\">מֵשָׁא׳</a>) planted the garden of the school-house in beds (of various plants), v. <a href=\"#\" data-headword=\"מֵישַׁר\">preced.</a></div><div class=\"sense\"><b>—2)</b> <i>plain, valley</i>. <span class=\"citation\">Targ. Gen. XII, 6</span> (h. text <a href=\"#\" data-headword=\"אַלֹּון I\">אֵלוֹן</a>). Ib. O. XXXV, 8 (h. text <a href=\"#\" data-headword=\"אַלֹּון I\">אַלּוֹן</a>). <span class=\"citation\">Targ. Deut. XI, 30</span> (h. text <a href=\"#\" data-headword=\"עֲרָבָה I\">עֲרָבָה</a>). <span class=\"citation\">Ib. III, 10</span> (h. text <a href=\"#\" data-headword=\"מֵישַׁר\">מִישֹׁר</a>); a. fr.—<span class=\"citation\">Lev. R. s. 12</span>, beg. <span dir=\"rtl\">סוף דהוא עביד ביתיה מ׳</span> finally he (the drunkard) will make his house a level (v. <a href=\"#\" data-headword=\"מִישׁוֹר\">מִישׁוֹר</a>). <span class=\"citation\">Sabb. 110ᵇ</span> <span dir=\"rtl\">הב לי מי׳ דכרתי</span> (sub. <span dir=\"rtl\">מבתוותא ד־</span>) give me of what grows in the waste places of the valley (or bed) of leek.—Pl. <span dir=\"rtl\">מֵישְׁרַיָּא</span>, <span dir=\"rtl\">(<a href=\"#\" data-headword=\"מֵשָׁא\">מֵשָׁא׳</a>) <a href=\"#\" data-headword=\"מֵישְׁרָא II\">מֵישָׁרֵי</a></span>. <span class=\"citation\">Targ. O. Num. XXII, 1</span> (Y. <a href=\"#\" data-headword=\"מַשְׁרִיתָא\">מַשִּׁרְיָא</a>, corr. acc.). <span class=\"citation\">Targ. O. Deut. XI, 30</span>; a. e.—<span class=\"citation\">Gen. R. s. 42</span> (transl. <span dir=\"rtl\">אֵיל</span>, <span class=\"citation\">Gen. XIV, 6</span>) <span dir=\"rtl\">משריא דפארן</span>. Ib. end (ref. to <span dir=\"rtl\">אֵלוֹנֵי</span>, ib. 13) <span dir=\"rtl\">מ׳ דממרא</span>.—Sabb. l. c. <span dir=\"rtl\">דמישרי</span> (Rashi <a href=\"#\" data-headword=\"מַשְׁרִיתָא\">משריא</a>, Ms. M. <span dir=\"rtl\">מֵשָׁארֵי</span>), v. <a href=\"#\" data-headword=\"*בַּתְוָא\">בַּתְוָא</a> a. <a href=\"#\" data-headword=\"כָּתָא\"><a href=\"#\" data-headword=\"כָּתָא\">כָּתָא</a>.</a></div>","alt":["מֵישְׁרָא","מֵשְׁ׳ I"]},"13295":{"h":"מֵישְׁרָא II","r":"M01319","html":"<div class=\"sense\"><i>camp</i>, v. <a href=\"#\" data-headword=\"מַשְׁרֵי\">מֵשְׁרֵי</a>.</div>","alt":["מֵישְׁרֵי"]},"13296":{"h":"מִישְׁתּוּתָא","r":"M01320","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"מַשְׁכְּבָא\">מִשְׁ׳</a>.</div>","alt":["מִישְׁתֵּי"]},"13297":{"h":"מִית I","r":"M01321","html":"<div class=\"sense\"><i>to die, be dead</i>. Imperf. <a href=\"#\" data-headword=\"יְמוֹת\">יְמוּת</a>, <span dir=\"rtl\">יֵימוּת</span>. <span class=\"citation\">Targ. Gen. V, 8</span>. <span class=\"citation\">Ib. XLIV, 20</span>. <span class=\"citation\">Targ. O. Num. XX, 29</span> <span dir=\"rtl\">ארי מית</span> (Var. <span dir=\"rtl\">דהא מ׳</span>, <span dir=\"rtl\">דְּהָמִית</span>, v. Berl. Targ. O. II, p. 44). <span class=\"citation\">Targ. O. Gen. II, 17</span> <span dir=\"rtl\">מְמַת תְּמוּת</span> (ed. Amst. <span dir=\"rtl\">מֵימַת</span>); a. v. fr.—<i>Part.</i> <a href=\"#\" data-headword=\"מָאִית\">מָאִית</a>, <a href=\"#\" data-headword=\"מָיֵית\">מָיֵית</a>, <a href=\"#\" data-headword=\"מִית I\">מִית</a>, <a href=\"#\" data-headword=\"מֵת\">מִת</a>; f. <span dir=\"rtl\">מָיְתָא</span>; pl. <span dir=\"rtl\">מָיְיתִין</span>, <span dir=\"rtl\">מָיְתִין</span>, <a href=\"#\" data-headword=\"מְתִין\">מֵתִין</a>. <span class=\"citation\">Targ. Y. Num. XXII, 30</span> <span dir=\"rtl\">מָיְתָא</span> (ed. Amst. <a href=\"#\" data-headword=\"מִיתָא\">מִיתָא</a>). <span class=\"citation\">Targ. Ex. XII, 33</span>; a. fr.—<span class=\"citation\">Ber. 31ᵃ</span> <span dir=\"rtl\">דמִיתְנָן</span> that we must die. <span class=\"citation\">Y. Peah I, 15ᶜ</span> bot. <a href=\"#\" data-headword=\"מִיתַת\">מִיתַת</a> she (his mother) died. <span class=\"citation\">Snh. 97ᵃ</span> <span dir=\"rtl\">לא הוה מָיֵית איניש וכ׳</span> none of that place ever died before his time; a. fr.</div><div class=\"sense\"><b>Af. אָמִית</b> <div class=\"sense\"><i>to cause death, slay</i>. <span class=\"citation\">Targ. O. Gen. V, 24</span> <a href=\"#\" data-headword=\"מִית I\">אַמִית</a> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"מִית I\">אַמִּית</a>, <span dir=\"rtl\">אֲמִ׳</span>). Ib. XXXVIII, 7 <span dir=\"rtl\">אַמִּיתֵיה</span> ed. Berl. <span class=\"citation\">Targ. I Sam. XIV, 13</span> <span dir=\"rtl\">מְמִית</span> (ed. Lag. <span dir=\"rtl\">מְמֹתֵית</span> <i>Polel</i>); a. fr.</div></div>","alt":[]},"13298":{"h":"מִית II","r":"M01322","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"מִית I\">preced.</a>) <i>dead; corpse</i>. <span class=\"citation\">Targ. Deut. XIV, 1</span>. <span class=\"citation\">Targ. O. Num. XIX, 11</span> (ed. Amst. <a href=\"#\" data-headword=\"מֵתָא\">מֵתָא</a>); a. fr.—Y. Bicc. III, 65ᵇ <span dir=\"rtl\">דקיימין מן קומי מ׳</span> who rise before the dead (being carried to burial); a. fr.—Pl. <span dir=\"rtl\">מֵיתַיָּא</span>, <span dir=\"rtl\">מֵתַיָּא</span>. <span class=\"citation\">Targ. Num. XVII, 13</span>; a. fr.—<span class=\"citation\">Y. Kidd. I, 61ᶜ</span> bot. <span dir=\"rtl\">כד הוויין קיימן על מ׳</span> (not <span dir=\"rtl\">קיימין</span>) when they stand by the dead (lamenting); a. e.</div>","alt":["מֵיתָא","מֵתָא I","מִיתָא"]},"13299":{"h":"מֵיתָא","r":"M01323","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (infin. of <a href=\"#\" data-headword=\"אֲתָא\">אֲתָא</a>) <i>coming</i>. <span class=\"citation\">Targ. I Sam. XVI, 4</span> <span dir=\"rtl\">מֵיתָךְ</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">מַתְיָךְ</span>); a. fr.—<span class=\"citation\">Gen. R. s. 60</span> (ref. to <span dir=\"rtl\">בא מבא</span>, <span class=\"citation\">Gen. XXIV, 62</span>) <span dir=\"rtl\">אתא ממ׳ וכ׳</span> he came from coming? Where did he go to?—Pl. <span dir=\"rtl\">מֵיתַיָּא</span> (with sing. sense; cmp. <a href=\"#\" data-headword=\"מֵעֲלָא\">מֵעֲלָא</a>). <span class=\"citation\">Targ. O. Gen. XXIV, 62</span> <span dir=\"rtl\">מֵיתוֹהִי</span>).—<span class=\"citation\">Gitt. 30ᵃ</span> <span dir=\"rtl\">לא שמיה מתיא</span> this is not called ‘coming home’ (as fulfilling the condition). <span class=\"citation\">Keth. 17ᵃ</span> <span dir=\"rtl\">בריך מֵיתַיִיךְ וכ׳</span> blessed by thy coming for peace; <span class=\"citation\">Snh. 14ᵃ</span> <span dir=\"rtl\">מֵתַיִיךְ</span>.</div>","alt":["מֵתא II"]},"13300":{"h":"מִיתָא","r":"M01324","html":"<div class=\"sense\"> f., constr. <a href=\"#\" data-headword=\"מִיתַת\">מִיתַת</a> = h. <a href=\"#\" data-headword=\"מִיתָה\">מִיתָה</a>. <span class=\"citation\">Targ. Y. I Gen. XXXV, 8</span>; a. e.</div>","alt":[]},"13301":{"h":"מִיתְגָּא","r":"M01325","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִתגָּא\">מִתְגָּא</a></div>","alt":[]},"13302":{"h":"מִיתָה","r":"M01326","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>death, penalty of death</i>. <span class=\"citation\">Sabb. 156ᵇ</span> <span dir=\"rtl\">מ׳ משונה</span> an unnatural death; <span dir=\"rtl\">מ׳ עצמה</span> natural death. <span class=\"citation\">Snh. 68ᵃ</span> <span dir=\"rtl\">אם ימותו מִיתַת עצמן</span> if they shall die a natural death. <span class=\"citation\">Ib. XI, 4</span> (<span class=\"citation\">89ᵃ</span>) <span dir=\"rtl\">מ׳ בב&quot;ד</span> death at the hand of the court. <span class=\"citation\">Snh. 5</span> <span dir=\"rtl\">מִיתָתוֹ בידי אדם</span> he must be put to death by man (court); <span dir=\"rtl\">מיתתו בידי שמים</span> he shall be put to death by the Lord. <span class=\"citation\">Keth. 37ᵇ</span> <span dir=\"rtl\">מ׳ אריכתא</span> one continued act of execution (comprising lashes and putting to death); a. fr.—Pl. <span dir=\"rtl\">מִיתוֹת</span>. <span class=\"citation\">Snh. VII, 1</span> <span dir=\"rtl\">ארבע מ׳ נמסרו לב&quot;ד</span> four forms of capital punishment have been entrusted to the courts. <span class=\"citation\">Sot. 8ᵇ</span> <span dir=\"rtl\">דין ארבע מ׳ וכ׳</span> the divine judgment taking the place of the four forms of capital punishment (which the Jewish courts can no longer decree) has not ceased; a. fr.</div>","alt":[]},"13303":{"h":"מִיתּוּחַ","r":"M01327","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָתַח\">מָתַח</a>) <i>stretching, drawing tight</i>. <span class=\"citation\">Y. M. Kat. I, 80ᵈ</span> bot.—<span dir=\"rtl\">מחט של מ׳</span> a pin used in weaving or embroidery to draw the thread tight, <i>spool.</i> <span class=\"citation\">Kel. XIII, 5</span> (Talm. ed. <a href=\"#\" data-headword=\"מִיתּוּן\">מִיתּוּן</a>). Ib. <span dir=\"rtl\">התקינה למ׳</span> (ed. Dehr. <span dir=\"rtl\">למיתא</span>, v. <a href=\"#\" data-headword=\"מֵיתָא\">מֵיתָא</a> II a. <a href=\"#\" data-headword=\"מֵיתָנָא\">מֵיתָנָא</a>). Ib. 8; <span class=\"citation\">Yeb. 43ᵃ</span> <span dir=\"rtl\">לנר או למ׳</span> (Kel. ed. Dehr. <span dir=\"rtl\">למיתא</span>) made for snuffing the light (v. <a href=\"#\" data-headword=\"מָחַט\">מָחַט</a>) or as a spool.</div>","alt":["מִתּ׳"]},"13304":{"h":"מִיתּוּן","r":"M01328","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָתַן\">מָתַן</a>) <i>stretching</i>, v. <a href=\"#\" data-headword=\"מִיתּוּחַ\">preced.</a> <span class=\"citation\">Orl. I, 4</span> <span dir=\"rtl\">מחט של מ׳</span> (Ms. M. <span dir=\"rtl\">מיתין</span>), v. <a href=\"#\" data-headword=\"מִיתּוּחַ\">preced.</a></div>","alt":["מִתּ׳"]},"13305":{"h":"מִיתוֹרְיִין","r":"M01329","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (μεσθόρια) <i>borders, frontiers</i>. <span class=\"citation\">Gen. R. s. 50</span>, beg. Ar. (v. <a href=\"#\" data-headword=\"אוֹרְיָין II\"><span dir=\"rtl\">אוֹרְיָין</span> I</a>); <span class=\"citation\">Lev. R. s. 27</span> <a href=\"#\" data-headword=\"מתורין\">מתורין</a> (corr. acc.).</div>","alt":["מִיתוֹרִין"]},"13306":{"h":"מִיתוּתָא","r":"M01330","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִית I\">מִית</a>) <i>death, dying</i>. <span class=\"citation\">Targ. Y. I Num. XVI, 29</span>; a. fr.—<span class=\"citation\">B. Bath. 16ᵇ</span>; <span class=\"citation\">Taan. 23ᵃ</span>, v. <a href=\"#\" data-headword=\"חַבָּרוּתָא\">חַבְרוּתָא</a>.</div>","alt":[]},"13307":{"h":"מִיתְחַזְנָא","r":"M01331","html":"<div class=\"sense\"> (a feigned part. Ithp. of <span dir=\"rtl\">נחז</span>, denomin. of <span dir=\"rtl\">נחיז</span>, a problematic substitute of <a href=\"#\" data-headword=\"נָזִיחַ\">נזיח</a>, itself a substitute of <a href=\"#\" data-headword=\"נָזִיר\">נָזִיר</a>; v. <a href=\"#\" data-headword=\"כִּינּוּי\">כִּינּוּי</a>) <i>I will be a naḥiz</i>. <span class=\"citation\">Ned. 10ᵇ</span>; v. <a href=\"#\" data-headword=\"מִיפְּחַזְנָא\">מִיפְּחַזְנָא</a>.</div>","alt":[]},"13308":{"h":"מִיתָנָא","r":"M01332","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִית I\">מִית</a>) [<i>death</i>,] <i>the deceased</i>. <span class=\"citation\">Yeb. 37ᵇ</span>, sq. <span dir=\"rtl\">בר מ׳</span> the son of the decceased person.</div>","alt":[]},"13309":{"h":"מֵיתָנָא","r":"M01333","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲתָא\">אֲתָא</a>) <i>bringing home, drawing towards one’s self</i>. <span class=\"citation\">Sabb. 102ᵃ</span>, v. <a href=\"#\" data-headword=\"לֶכְתָּא\">לֶכְתָּא</a>; [Rashi: <a href=\"#\" data-headword=\"מִתְנָא\">מִתְנָא</a> <i>rope</i>].—[<span class=\"citation\">Ukts. I, 2</span> <span dir=\"rtl\">המיתנא</span>, v. <a href=\"#\" data-headword=\"מִינְתָּא\">מִינְתָּא</a>.]</div>","alt":[]},"13310":{"h":"מִיתְנָא","r":"M01334","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִתְנָא\">מִתְנָא</a></div>","alt":[]},"13311":{"h":"מִיתְעַזְנָא","r":"M01335","html":"<div class=\"sense\"> (a feigned part. Ithp. of <span dir=\"rtl\">נעז</span>, as a dialectic substitute of <span dir=\"rtl\">נקז</span>, denom. of <span dir=\"rtl\">נקיז</span>, a substitute of <span dir=\"rtl\">נזיק</span>, itself a substitute of <a href=\"#\" data-headword=\"נָזִיר\">נָזִיר</a>) <i>I will be a naʿiz</i>. <span class=\"citation\">Ned. 10ᵃ</span>; v. <a href=\"#\" data-headword=\"מִיתְחַזְנָא\">מִיתְחַזְנָא</a>.</div>","alt":[]},"13312":{"h":"מֵיתָר","r":"M01336","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>cord, rope</i>.—Pl. <span dir=\"rtl\">מֵיתָרִים</span>, <span dir=\"rtl\">מֵיתָרִין</span>. <span class=\"citation\">Num. R. s. 12</span>, end. <span class=\"citation\">Yalk. Ex. 374</span>; a. e.—[Tanḥ. Ki Thetsé 4 <span dir=\"rtl\">מיתרין</span>, read: <a href=\"#\" data-headword=\"מִיטְרִין\">מִיטְרִין</a>.]</div>","alt":[]},"13313":{"h":"מִיתַּרְכָא","r":"M01337","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְתַרְכָא\">מְתַרְכָא</a></div>","alt":[]},"13314":{"h":"מִיתַת","r":"M01338","html":"<div class=\"sense\">, v, <a href=\"#\" data-headword=\"מִיתָא\">מִיתָא</a>.</div>","alt":[]},"13315":{"h":"מָךְ","r":"M01339","html":"<div class=\"sense\"><i>thy water</i>, v. <a href=\"#\" data-headword=\"מַיִין\">מַיִין</a>.</div>","alt":[]},"13316":{"h":"מָךְ ²","r":"M01340","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>lowly</i>. <span class=\"citation\">Sot. 10ᵇ</span> (play on <span dir=\"rtl\">מ̇כ̇ת̇ם̇</span>, <span class=\"citation\">Ps. LVI, 1</span>) <span dir=\"rtl\">שהיה מ̇ך̇ ות̇ם̇ לכל</span> he was lowly and sincere to everybody. <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">מך שהוא מך לפני כל וכ׳</span> the poor man is called <i>makh</i>, because he is lowly before everybody, he is like the lowest threshold; <span class=\"citation\">Midr. Prov. to ch. XXII</span> <span dir=\"rtl\">מך עד האסקופה וכ׳</span> he is lowly (bent down) to the lowest threshold.</div>","alt":[]},"13317":{"h":"מָכָא","r":"M01341","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">מעכא</span>; <a href=\"#\" data-headword=\"מְעַךְ\">מְעַךְ</a>) <i>crushed, battered</i>.—<span dir=\"rtl\">זוזא מ׳</span> a battered Zuz (which cannot be passed). <span class=\"citation\">Sabb. 129ᵃ</span>; <span class=\"citation\">B. Kam. 37ᵃ</span> (Ms. M. <span dir=\"rtl\">מא׳</span>); <span class=\"citation\">Bekh. 51ᵃ</span> <span dir=\"rtl\">מא׳</span>.</div>","alt":["מָאכָא"]},"13318":{"h":"מְכָא","r":"M01342","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְכִי\">מְכִי</a></div>","alt":[]},"13319":{"h":"מְכַבֵּד","r":"M01343","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <span dir=\"rtl\">מְכַבֶּדֶת</span> f. (<a href=\"#\" data-headword=\"כָּבֵד I\">כָּבַד</a>, <i>Pi.</i>) <i>broom;</i> also <i>the fanshaped twig of the palm-tree.</i> <span class=\"citation\">Ukts. I, 3</span> <span dir=\"rtl\">יד המ׳ של תמרה</span> the stem of ‘the broom’ of the palm-tree; <span class=\"citation\">Tosef. ib. I, 4</span> <span dir=\"rtl\">מכבדת</span>. Tanḥ. Masʿé 13 (ref. to <a href=\"#\" data-headword=\"כָּבֵד I\">הכביד</a>, <span class=\"citation\">Is. VIII, 23</span>) <span dir=\"rtl\">הכבידן כבמ׳</span> he swept them off as with a broom; <span class=\"citation\">Num. R. s. 23</span>, end; Lam. R. introd. (R. Abbahu 2) <span dir=\"rtl\">הממם כבמַכְבֵּיד</span>, v. <a href=\"#\" data-headword=\"הָמַם\">הָמַם</a>. <span class=\"citation\">Tosef. Sabb. VI</span> (<span class=\"citation\">VII), 7</span> <span dir=\"rtl\">שב על המ׳</span> sit on a broom (a superstitious practice); a. e.—Pl. <span dir=\"rtl\">מְכַבְּדוֹת</span>. <span class=\"citation\">Succ. 13ᵇ</span> <span dir=\"rtl\">מ׳ ובהן תמרים</span> palm-twigs on which there are dates; Y. Bets. IV, 62ᶜ top. <span class=\"citation\">Pes. 56ᵇ</span> <span dir=\"rtl\">של מ׳</span> the dates hanging on the branches. <span class=\"citation\">Y. Peah IV, beg. 18ᵃ</span> <span dir=\"rtl\">תמרים במ׳</span> (leave for the poor) dates on the branches. <span class=\"citation\">Y. Maasr. I, 48ᵈ</span> bot.—[<span class=\"citation\">Sabb. 113ᵇ</span> <span dir=\"rtl\">מְכֵבְּדוֹתַי</span>, v. <a href=\"#\" data-headword=\"כָּבֵד I\"><span dir=\"rtl\">כָּבֵד</span> I</a>, <i>Pi.</i>]—[Ruth R. end <span dir=\"rtl\">מכבדות</span> some ed., read: <span dir=\"rtl\">מַכְבֵּרוֹת</span>.]</div>","alt":[]},"13320":{"h":"מַכְבֵּיד","r":"M01344","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְכַבֵּד\">preced.</a></div>","alt":[]},"13321":{"h":"מכבין","r":"M01345","html":"<div class=\"sense\">, <span class=\"citation\">Targ. II Sam. XVII, 28</span>, v. <a href=\"#\" data-headword=\"מַכָּכָא\">מַכָּכָא</a></div>","alt":[]},"13322":{"h":"מַכְבֵּישׁ","r":"M01346","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַכְבֵּשׁ\">מַכְבֵּשׁ</a></div>","alt":[]},"13323":{"h":"מַכְבַּנְתָּא","r":"M01347","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(<a href=\"#\" data-headword=\"כְּבַן\">כְּבַן</a>) = h. <a href=\"#\" data-headword=\"כְּבֵינָה\">כְּבֵינָה</a>, <i>brooch, buckle</i>. <span class=\"citation\">Sabb. 62ᵃ</span>, expl. <a href=\"#\" data-headword=\"כּוֹכְלִיאָר\">כּוֹכְלִיאָר</a>.—<span class=\"citation\">Ib. 156ᵇ</span>, v. <a href=\"#\" data-headword=\"דּוּץ II\"><span dir=\"rtl\">דּוּץ</span> II</a>.</div>","alt":[]},"13324":{"h":"מִכְבַּר","r":"M01348","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִכְוַור\">מִכְוַור</a></div>","alt":["מַכְ׳"]},"13325":{"h":"מַכְבֵּרָה","r":"M01349","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>sieve</i>.—Pl. <span dir=\"rtl\">מַכְבֵּרוֹת</span>. <span class=\"citation\">Gen. R. s. 39</span>; <span class=\"citation\">Yalk. ib. 62</span>; Yalk. Neh. 1071; Ruth R. end (not <span dir=\"rtl\">מכבדות</span>).</div>","alt":[]},"13326":{"h":"מַכְבֵּשׁ","r":"M01350","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּבַשׁ\">כָּבַשׁ</a>) <i>clothes-press; screw, vise</i>. <span class=\"citation\">Tosef. Sabb. XVI</span> (<span class=\"citation\">XVII), 5</span> <span dir=\"rtl\">מ׳ של בעלי … כלים</span> (ed. Zuck. <a href=\"#\" data-headword=\"מַיִם\">מים</a> for <span dir=\"rtl\">כלים</span>, corr. acc.) a domestic clothes-press which has been unscrewed to take out clothes. <span class=\"citation\">Sabb. XX, 5</span> <span dir=\"rtl\">מ׳ … מתירין וכ׳</span> you may unscrew a domestic clothes-press but not screw it (on the Sabbath). Ib. (<a href=\"#\" data-headword=\"מ׳\">מ׳</a>)<span dir=\"rtl\">של כובסין</span> the washers’ clothes-press. <span class=\"citation\">Kel. XVI, 7</span> <span dir=\"rtl\">מ׳ של חרש</span> the carpenter’s vise (for straightening wood), v. <a href=\"#\" data-headword=\"*מְכַוֵּון\">מְכַוֵּון</a>; <span class=\"citation\">Tosef. Kel. B. Bath. I, 8</span> <span dir=\"rtl\">מכביש של נגר</span>. <span class=\"citation\">Ib. 15</span> <span dir=\"rtl\">מ׳ של שכף וכ׳</span> the leather worker’s press on which he stretches the hides. <span class=\"citation\">Y. Sabb. XX, end, 17ᵈ</span>; a. e.</div>","alt":[]},"13327":{"h":"מִכְּדִי","r":"M01351","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּדִי I\"><span dir=\"rtl\">כְּדִי</span> I</a></div>","alt":[]},"13328":{"h":"מַכָּה","r":"M01352","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>wound, plague, stroke, blow</i>. <span class=\"citation\">Sabb. 134ᵇ</span>. <span class=\"citation\">Meg. 13ᵇ</span> (ref. to <span class=\"citation\">Esth. III, 1</span>) <span dir=\"rtl\">אחר שברא … רפואה למ׳</span> after the Lord had prepared the healing of the wound (the means of salvation); a. v. fr.—<span dir=\"rtl\">מַכַּת בצורת</span>, <span dir=\"rtl\">מ׳ בכורות</span>, <span dir=\"rtl\">מ׳ מרדות</span> &amp;c., v. respective determinants. <span class=\"citation\">Sot. III, 4</span> מכת פרושין Y. ed. (Bab. a. Mish. <a href=\"#\" data-headword=\"מָכוּת\">מַכּוֹת</a>) the wound inflicted by the Pharisees, i.e. injury done under the pretext of strict adherence to the letter of the law, or of benevolence; Y. ib. 19ᵃ מ׳ פ׳ זה שהוא נותן עצה וכ׳ ‘the plague of the Pharisees’ is he who advises heirs to evade paying alimentation to the widow. Ib. <span dir=\"rtl\">זו מ׳ פ׳ נגעו בה</span> (collect. pl.) the Pharisean plague has struck her; ib. <span dir=\"rtl\">זה מ׳ פ׳ נגעו בו</span> his friends under the pretext of benevolence have deprived him of the benefit of the poor-law; Y. Peah VIII, 21ᵃ bot.—<span class=\"citation\">Sot. 10ᵇ</span> (play on <span dir=\"rtl\">מ̇כ̇ת̇ם̇</span>, v. <a href=\"#\" data-headword=\"מָךְ\">מָךְ</a>) <span dir=\"rtl\">שהיתה מ̇כ̇תו ת̇מ̇ה וכ׳</span> his defect was a perfection, for he was born circumcised; [Rashi: ‘the place where he was to be wounded’].—Pl. <a href=\"#\" data-headword=\"מָכוּת\">מַכּוֹת</a>. <span class=\"citation\">Ex. R. s. 10</span>; a. fr.—<span class=\"citation\">Snh. I, 2</span> <span dir=\"rtl\">מ׳ בשלשה</span> corporal punishment (lashes, v. <a href=\"#\" data-headword=\"מַלְקוּת\">מַלְקוּת</a>) must be decreed by a court of three. <span class=\"citation\">Ib. 10ᵃ</span> <span dir=\"rtl\">מ׳ הראויות להשתלש</span> a number of lashes which is divisible by three (39); a. fr.—<i>Maccoth</i> (<i>Punishments</i>), a treatise of the Mishnah, Tosefta, Talmud Babli a. Y’rushalmi, of the Order of N’zikin.</div>","alt":[]},"13329":{"h":"מִכְוָה","r":"M01353","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>burnt spot on the skin, burn.</i> <span class=\"citation\">Neg. IX, 1</span> <span dir=\"rtl\">כל שהוא מחמת האש זו היא מ׳</span> all wounds produced through fire (directly or indirectly) are called ‘burns’. <span class=\"citation\">Ib. VIII, 7</span> <span dir=\"rtl\">מחיית המ׳</span> the cicatrization of a burn. <span class=\"citation\">Ib. IX, 2</span>; Sifra Thazr., Neg., Par. 4, ch. VII <span dir=\"rtl\">אין שחין ומ׳ וכ׳</span> an inflammation and a burn cannot be combined (to make up the minimum size required for uncleanness); a. fr.</div>","alt":[]},"13330":{"h":"*מְכַוֵּון","r":"M01354","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּן\">כּוּן</a>) <i>a straightening device, vise</i>. Pesik. Zutr., Haăz. (p. 111 ed. Bub.) <span dir=\"rtl\">נתנו במ׳ ולא וכ׳</span> he placed it (the crooked wood) in a vise, and it was not straightened; (<span class=\"citation\">Sifré Deut. 308</span>; <span class=\"citation\">Yalk. Deut. 942</span>; <span class=\"citation\">Yalk. Ez. 362</span>, corrupt versions); cmp. <a href=\"#\" data-headword=\"מַכְבֵּשׁ\">מַכְבֵּשׁ</a>.</div>","alt":[]},"13331":{"h":"מִכְוַור","r":"M01355","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Mikhvar, Makhvar</i>, a district of Peraea. [The situation of <i>Machaerus</i> forbids its identification with our w.] <span class=\"citation\">Targ. Y. I Num. XXXII, 1</span>, <span class=\"citation\">Targ. Y. II, Num. XXXII, 1</span>; <span class=\"citation\">ib. XXI, 32</span> (Y. I <a href=\"#\" data-headword=\"מִכְבַּר\">מכבר</a>; h. text <span dir=\"rtl\">יעזר</span>). Ib. XXXII, 35 (Y. I <span dir=\"rtl\">מִ׳ גרמתא</span>, II <span dir=\"rtl\">מַ׳ ויגבהה</span>; h. text <span dir=\"rtl\">יעזר ויגבהה</span>).—Y. R. Hash. II, 58ᵃ top <span dir=\"rtl\">הרי מ׳ וגדור</span>; (Bab. ib. 23ᵇ; Tosef. ib. II (I), 2 <span dir=\"rtl\">חרים וכייר</span>), v. <a href=\"#\" data-headword=\"גְּדוֹר\">גְּדוֹר</a>; <span class=\"citation\">Y. Shebi. IX, 38ᵈ</span> bot; (<span class=\"citation\">Tosef. ib. VII, 11</span> <span dir=\"rtl\">חרים וחבירותי׳</span> ed. Zuck., v. Var. ib. note).—<span class=\"citation\">Tam. III, 8</span> <span dir=\"rtl\">הר מ׳</span> (Talm. ed. 30ᵇ <a href=\"#\" data-headword=\"ערי\">ערי</a>); <span class=\"citation\">Yoma 39ᵇ</span> <span dir=\"rtl\">הרי מכמר</span> (Ms. O. <a href=\"#\" data-headword=\"מִכְוַור\">מכוור</a>; Ms. M. <a href=\"#\" data-headword=\"רוּם\">הרים</a>; Ms. M. 2 <span dir=\"rtl\">מכאוור</span>).</div>","alt":["מַכְ׳"]},"13332":{"h":"מְכוֹלִין","r":"M01356","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּל\">כּוּל</a>, <a href=\"#\" data-headword=\"כְּלַל\">כְּלַל</a>; cmp. <a href=\"#\" data-headword=\"כִּילָה\">כּילָה</a>) <i>curtain, cover</i>. <span class=\"citation\">Targ. II Kings XXIII, 7</span> (Ar. <span dir=\"rtl\">מְכִילִין</span>).</div>","alt":[]},"13333":{"h":"מָכוֹן","r":"M01357","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>defined place; plan; residence</i>. <span class=\"citation\">Sot. VIII, 3</span> <span dir=\"rtl\">הבונה בית על מְכוֹנוֹ</span> he who rebuilds a house on its old place and plan. Lam. R. introd. (R. Joḥ. 1) <span dir=\"rtl\">למְכוֹנִי הראשון</span> to my original residence (heaven).—Esp. <i>Makhon</i>, name of one of the seven heavens. <span class=\"citation\">Ḥag. 12ᵇ</span></div>","alt":[]},"13334":{"h":"מְכוֹנָה","r":"M01358","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָכוֹן\">preced.</a>) <i>a place where animals are kept ready for slaughtering; stall, coop</i>.—Pl. <a href=\"#\" data-headword=\"מְכוֹרוֹת\">מְכוֹנוֹת</a>. Ohol. VIII, 1.—[<span class=\"citation\">Y. Sabb. XVII, 16ᵇ</span> top <span dir=\"rtl\">ובמכונה</span>, v. <a href=\"#\" data-headword=\"בּוּכָנָא\">בּוּכְנָא</a>.]</div>","alt":[]},"13335":{"h":"*מְכַוַּנְתָּא","r":"M01359","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (כּוּן <i>Pa</i>.) <i>looking out, lurking</i>.—<span class=\"citation\">Targ. Jud. V, 11</span> <span dir=\"rtl\">בית מְכַוְּנַת ליסטין</span> the place where robbers lie in wait.</div>","alt":[]},"13336":{"h":"מִכְוַר","r":"M01360","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִכְוַור\">מִכְוַור</a></div>","alt":[]},"13337":{"h":"מְכוּרָה","r":"M01361","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְכִירָה\">מְכִירָה</a></div>","alt":[]},"13338":{"h":"מְכוֹרוֹת","r":"M01362","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְכֵרוֹת\">מְכֵרוֹת</a></div>","alt":[]},"13339":{"h":"מכורן","r":"M01363","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּדַן\">כָּדַן</a></div>","alt":[]},"13340":{"h":"מכורסינין","r":"M01364","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בּוּרְסִיוֹן\">בּוּרְסִיוֹן</a></div>","alt":[]},"13341":{"h":"מַכּוֹשׁ I","r":"M01365","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָכַשׁ\">נָכַשׁ</a>) <i>hoe, spud</i>; <i>digging with the spud</i>. <span class=\"citation\">B. Bath. 54ᵃ</span> <span dir=\"rtl\">כיון שהכיש בה מ׳ אחד וכ׳</span> (Ms. R. <span dir=\"rtl\">שנכש בה</span>) as soon as he has inserted the spud once, he has taken possession of the entire field. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מקום מַכּוּשׁוֹ בלבד</span> only the place where he dug.—[<span class=\"citation\">Y. Ned. IV, beg. 38ᶜ</span> <span dir=\"rtl\">קורדום של מ׳</span>, v. <a href=\"#\" data-headword=\"נִיכּוּשׁ\">נִיכּוּשׁ</a>.]</div>","alt":[]},"13342":{"h":"מַכּוֹשׁ II","r":"M01366","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּשַׁשׁ\">כָּשַׁשׁ</a>, v. <a href=\"#\" data-headword=\"כִּשְׁכֵּשׁ\">כִּשְׁכֵּשׁ</a>) </div><div class=\"sense\"><b>1)</b> <i>clapper of a bell</i>. <span class=\"citation\">Midr. Till. to Ps. VII, 10</span> <span dir=\"rtl\">דומה לפעמון … ומַכּוּשׁוֹ של וכ׳</span> like a golden bell whose clapper is made of a jewel.</div><div class=\"sense\"><b>—2)</b> <i>hammer</i>, <i>striking with the hammer</i>. <span class=\"citation\">Ab. Zar. 19ᵇ</span> <span dir=\"rtl\">מ׳ אחרון</span> the last stroke (driving the nail in).—[<span class=\"citation\">Tosef. Mikv. VI</span> (<span class=\"citation\">VII), 17</span> <span dir=\"rtl\">והמכושים</span>, ed. Zuck., read: <span dir=\"rtl\">המכובשים</span>, v. <a href=\"#\" data-headword=\"כָּבַשׁ\">כָּבַשׁ</a>.]</div>","alt":[]},"13343":{"h":"מַכּוֹשׁ","r":"M01367","html":"<div class=\"sense\">, <i>hammer</i>; <i>knocker</i>. <span class=\"citation\">Lev. R. s. 24</span> <span dir=\"rtl\">מאן דהוה ליה מ׳</span> whoever has a hammer (or a <i>hoe</i>, v. <a href=\"#\" data-headword=\"מַכּוֹשָׁא II\">next w.</a>). <span class=\"citation\">Gen. R. s. 44</span> (ed. Wil. <a href=\"#\" data-headword=\"מַכִּישָׁה\">מַכִּישָׁה</a>); <span class=\"citation\">Yalk. ib. 77</span> <a href=\"#\" data-headword=\"מַכּוֹשׁ\">מכושה</a>, v. <a href=\"#\" data-headword=\"כְּשַׁשׁ\">כְּשַׁשׁ</a>. <span class=\"citation\">Y. Meg. III, 73ᵈ</span> bot., v. <a href=\"#\" data-headword=\"*בּכּוּשָׁא\">בַּכּוּשָׁא</a>.</div>","alt":["מַכּוֹשָׁא I","מַכּוֹשָׁה"]},"13344":{"h":"מַכּוֹשָׁא II","r":"M01368","html":"<div class=\"sense\"> , <i>hoe, spade</i>. <span class=\"citation\">Lev. R. s. 25</span> <span dir=\"rtl\">יטעון מַכּוּשֵׁיה וכ׳</span> (Var. in Ar. <span dir=\"rtl\">יסב פסא</span>) shall take up his spade and go out and plant trees.</div>","alt":[]},"13345":{"h":"מָכוּת","r":"M01369","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָךְ\">מָךְ</a>) </div><div class=\"sense\"><b>1)</b> <i>poverty</i>. <span class=\"citation\">B. Mets. 114ᵃ</span>; <span class=\"citation\">Arakh. 17ᵇ</span> (ref. to <a href=\"#\" data-headword=\"מָךְ\">מָךְ</a>, <span class=\"citation\">Lev. XXVII, 8</span>) <span dir=\"rtl\">עד שיהא במָכוּתוֹ וכ׳</span> he must have remained in his impoverished condition from the beginning to the end of the proceedings.</div><div class=\"sense\"><b>—2)</b> <i>humility</i>. <span class=\"citation\">Gen. R. s. 74</span>, end (play on <span dir=\"rtl\">מ̇כ̇ת̇ם̇</span>, <span class=\"citation\">Ps. LX, 1</span>) <span dir=\"rtl\">מ̇כ̇ות ות̇מ̇ות</span> humility (of David) and innocence; <span class=\"citation\">Yalk. Sam. 147</span> <span dir=\"rtl\">מ׳ ותמות לדוד</span>.</div>","alt":[]},"13346":{"h":"מָכוּתָא","r":"M01370","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (Assyr. <i>makua</i>, v. Fränkel Zeitschr. für Assyriol. III, p. 53; Proceed. Soc. for Bibl. Archaeol. 1887, p. 103) a certain kind of <i>boat</i>, (<i>low boat?</i>). <span class=\"citation\">Keth. 69ᵇ</span> <span dir=\"rtl\">אסקריא דמ׳</span>; (<span class=\"citation\">Taan. 21ᵃ</span> <span dir=\"rtl\">דספינתא</span>, v. Rabb. D. S. a. l. note 300), v. <a href=\"#\" data-headword=\"אִסְקַרְיָא\">אִסְקַרְיָא</a>; [Rashi: <i>sail</i>]. <span class=\"citation\">B. Bath. 161ᵇ</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"צְיָיר I\">צייר</a>) <a href=\"#\" data-headword=\"מ׳\">מ׳</a></span> drew a ship in place of his name (Rashb. <i>mast</i>); <span class=\"citation\">Gitt. 36ᵃ</span>; <span class=\"citation\">87ᵇ</span> (Rashi: <i>sail-yard</i>).</div>","alt":[]},"13347":{"h":"מַכּוּתִי","r":"M01371","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְכַת\">נְכַת</a>) <i>a bite</i>. <span class=\"citation\">Koh. R. to VI, 11</span> [read:] <span dir=\"rtl\">או חדא מ׳</span>, v. <a href=\"#\" data-headword=\"*מַעְקוּצִי\">מַעְקוּצִי</a>.</div>","alt":[]},"13348":{"h":"מַכְחוֹל","r":"M01372","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּחַל\">כָּחַל</a>) <i>staff used for painting the eye.</i> <span class=\"citation\">Kel. XIII, 2</span> <span dir=\"rtl\">מ׳ שניטל הכף</span> a painting staff the spoon-shaped side of which is broken off; <span class=\"citation\">Tosef. Kel. B. Mets. III, 5</span>, v. <a href=\"#\" data-headword=\"זָכָר\">זָכָר</a>. <span class=\"citation\">Snh. 68ᵃ</span> <span dir=\"rtl\">כמ׳ בשפופרת</span>; <span class=\"citation\">Cant. R. to I, 3</span>, v. <a href=\"#\" data-headword=\"זַכְרוּת\">זַכְרוּת</a> a. <a href=\"#\" data-headword=\"חָסַר\">חָסַר</a>. <span class=\"citation\">B. Mets. 91ᵃ</span> <span dir=\"rtl\">כמ׳ בשפופרת</span> as the painting stick is inserted in the tube; <span class=\"citation\">Macc. 7ᵃ</span>; a. e.</div>","alt":["מַכְחֹל"]},"13349":{"h":"מַכְחָלָא","r":"M01373","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">B. Kam. 117ᵃ</span> דלו ליה במ׳ דכספא Ar. (ed. … <a href=\"#\" data-headword=\"לָתָא\">לתא</a>) they lifted his eye-lids with a silver stick.—Pl. <span dir=\"rtl\">מַכְחָלֵי</span>. <span class=\"citation\">Gitt. 69ᵃ</span> <span dir=\"rtl\">תלתא מ׳</span> three staff-fuls of paint.</div>","alt":["מַכְחַלְתָּא"]},"13350":{"h":"מְכִי","r":"M01374","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מוּךְ\">מוּךְ</a>) <i>to decline, bend</i>. <span class=\"citation\">Targ. Jud. V, 4</span>; a. e. (v. <a href=\"#\" data-headword=\"מוּךְ\">מוּךְ</a>).</div><div class=\"sense\"><b>Af. אַמְכֵי</b> <div class=\"sense\"><i>to lower</i>. <span class=\"citation\">Gen. R. s. 17</span>, beg. <span dir=\"rtl\">אַמְכַת לאפה</span> she lowered her face (looked down sulkily); <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">אמכת על אפא</span> (corr. acc.).</div></div><div class=\"sense\"><b>Ithpe. אִתְמְכֵי</b> <div class=\"sense\"><i>to be bent down, depressed</i>. <span class=\"citation\">Targ. Ps. XXXVIII, 9</span> <span dir=\"rtl\">אִתְמְכָיִית</span> (ed. Wil. <span dir=\"rtl\">אִתְמַכִית</span>; h. text <span dir=\"rtl\">נדכיתי</span>). <span class=\"citation\">Ib. CVI, 43</span>. <span class=\"citation\">Targ. Job XXIV, 24</span> (Ms. <span dir=\"rtl\">אִתְמַכִּיכוּ</span>).</div></div>","alt":["מְכָא"]},"13351":{"h":"מְכֵי","r":"M01375","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְכִי\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>bent, cowed, timid</i>. <span class=\"citation\">Lev. R. s. 13</span> [read:] <span dir=\"rtl\">הדא חיותא כי סלקא מן ימא היא מ׳ וכ׳</span> Ar. (ed. <span dir=\"rtl\">ממכיא</span>) an animal coming on land from the water is timid, coming out of the forest, it is not; <span class=\"citation\">Cant. R. to III, 4</span> (corr. acc.).</div><div class=\"sense\"><b>—2)</b> <i>low</i>.—Pl. <span dir=\"rtl\">מָכַיָּיא</span>. <span class=\"citation\">Gen. R. s. 32</span> <span dir=\"rtl\">אי מן מ׳ הוא</span> if it is one of the low mounts; (<span class=\"citation\">Cant. R. to IV, 4</span> <span dir=\"rtl\">מַכִּיכַיָּא</span>, v. <a href=\"#\" data-headword=\"מַכִּיךְ\">next w.</a>).</div>","alt":["מַכְיָא","מַכְיָה"]},"13352":{"h":"מַכִּיךְ","r":"M01376","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְכַךְ\">מְכַךְ</a>) </div><div class=\"sense\"><b>1)</b> <i>low</i>; <i>lowly, humble</i>. <span class=\"citation\">Targ. Lev. XIII, 20</span>, sq.—<span class=\"citation\">Targ. Prov. XVIII, 14</span> (ed. Wil. <a href=\"#\" data-headword=\"מְכִכְתָּא\">מְכִכְתָּא</a>). <span class=\"citation\">Ib. XVII, 27</span>; a. fr.—Pl. <span dir=\"rtl\">מַכִּיכִין</span>, <span dir=\"rtl\">מַכִּיכַיָּא</span>. <span class=\"citation\">Targ. Is. LVII, 15</span>. <span class=\"citation\">Targ. Job V, 11</span>; a. fr.—<span class=\"citation\">Cant. R. to IV, 4</span>, v. <a href=\"#\" data-headword=\"מְכֵי\">preced.</a> [</div><div class=\"sense\"><b>—2)</b> <i>bolster, cushion</i>, v. <a href=\"#\" data-headword=\"מַכָּכָא\">מַכָּכָא</a>.]</div>","alt":["מַכִּיכָא","מַכִּיכָא","מַכִּיכְתָּא"]},"13353":{"h":"מַכִּיכוּתָא","r":"M01377","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַכִּיךְ\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>lowliness, humilitg</i>. <span class=\"citation\">Targ. Koh. X, 6</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>languor</i>. Ib. 18 <span dir=\"rtl\">מַכִּיכוּת תפקידתא</span> languor in the observance of the law (h. text <span dir=\"rtl\">שפלות ידים</span>).</div>","alt":[]},"13354":{"h":"מַכִּיכְתָּא","r":"M01378","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַכִּיךְ\">מַכִּיךְ</a></div>","alt":[]},"13355":{"h":"מְכִילָא","r":"M01379","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּל\">כּוּל</a>) </div><div class=\"sense\"><b>1)</b> <i>measure of capacity</i>; trnsf. (v. <a href=\"#\" data-headword=\"מִדָּה\">מִדָּה</a>) <i>retribution, dealing out</i>. <span class=\"citation\">Targ. O. Deut. XXV, 14</span>. <span class=\"citation\">Targ. I Chr. XXIII, 29</span>; a. fr.—<span class=\"citation\">Targ. Job IX, 22</span> <span dir=\"rtl\">חדא מ׳</span> the same destiny.—Pl. <a href=\"#\" data-headword=\"מְכִילָא\">מְכִילָן</a>, <span dir=\"rtl\">מְכִלָן</span>, <a href=\"#\" data-headword=\"מְכִילָא\">מְכִילָתָא</a>, <a href=\"#\" data-headword=\"מְכִילָא\">מְכִלָ׳</a>. Targ. Y. Deut. l. c. <span class=\"citation\">Targ. O. Lev. XIX, 36</span> (Y. <span dir=\"rtl\">מְכִילוּ</span>, read: … <span dir=\"rtl\">לָן</span>). Y. B. Bath. V, end, 15ᵇ <span dir=\"rtl\">הוה מחי על מ׳</span> punished for false measures.</div><div class=\"sense\"><b>—2)</b> <i>a vessel used in connection with the show-bread</i> in the Temple.—Pl. <a href=\"#\" data-headword=\"מְכִילָא\">מְכִילָתָא</a>. <span class=\"citation\">Targ. Ex. XXV, 29</span> (h. text <a href=\"#\" data-headword=\"*מְנַקִּיּוֹת\">מנקיות</a>); a. e.</div><div class=\"sense\"><b>—3)</b>  (cmp. <a href=\"#\" data-headword=\"מִדָּה\">מִדָּה</a>) <i>a collection of rules of interpretation, treatise, tract</i>. <span class=\"citation\">Gitt. 44ᵃ</span> <span dir=\"rtl\">עיין במְכִילְתֵּיךְ</span> read it up in thy collection (Boraitha). <span class=\"citation\">Pes. 48ᵃ</span> <span dir=\"rtl\">ואהדר ליה במ׳ וכ׳</span> and his reply is recorded in another collection.—<span class=\"citation\">Y. Ab. Zar. IV, 44ᵇ</span> top <span dir=\"rtl\">אפיק … מ׳</span> R. Y. produced the M’khilta (v. infra; v. Mekh. Mishp. s. 20, ed. Weiss, p. 107, note 100).—Pl. <a href=\"#\" data-headword=\"מְכִילָא\">מְכִילָאן</a>. <span class=\"citation\">Lev. R. s. 3</span>, beg. <span dir=\"rtl\">רעותיה … בר מ׳</span> he likes to be called a man mastering many Mekhiltas; <span class=\"citation\">Koh. R. to IV, 6</span> <span dir=\"rtl\">מרי מ׳</span> (some ed. <a href=\"#\" data-headword=\"מיכיילא\">מיכיילא</a>, <span dir=\"rtl\">מיכלייאן</span>, v. <a href=\"#\" data-headword=\"מֵיכְלָא II\"><span dir=\"rtl\">מֵיכְלָא</span> II</a>).—Esp. <i>M’khilta</i>, or <i>M. d’bé R. Yishmael</i>, a <i>Halakhic and Midrashic book</i> on Exodus from ch. XII, to XXXV.</div>","alt":["מְכִילְתָּא","מְכִל׳"]},"13356":{"h":"מַכִּיר","r":"M01380","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָכַר\">נָכַר</a></div>","alt":[]},"13357":{"h":"מכיר","r":"M01381","html":"<div class=\"sense\">, <span class=\"citation\">Pirké d’R. El. ch. XXXVIII</span>, read <span dir=\"rtl\">מְכֵירָא</span>, v. <a href=\"#\" data-headword=\"מְכֵירִין\">מְכֵירִין</a></div>","alt":[]},"13358":{"h":"מְכִירָה","r":"M01382","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָכַר\">מָכַר</a>) <i>sale</i>. <span class=\"citation\">R. Hash. 26ᵇ</span>; <span class=\"citation\">Sot. 13ᵃ</span>, v. <a href=\"#\" data-headword=\"כִּירָה I\"><span dir=\"rtl\">כִּירָה</span> I</a>. <span class=\"citation\">Y. Kidd. I, 59ᵃ</span> <span dir=\"rtl\">מ׳ מ׳</span> we draw an analogy between the expressions <span dir=\"rtl\">מכר</span> (<span class=\"citation\">Deut. XV, 12</span> a. <span class=\"citation\">Ex. XXI, 7</span>). Ib. bot. <span dir=\"rtl\">שביעית של מ׳</span> the seventh year counted from the date of sale, opp. <span dir=\"rtl\">של עולם</span> the Sabbatical year. <span class=\"citation\">B. Kam. 68ᵃ</span> <span dir=\"rtl\">מ׳ שאינה חוזרת</span> a sale which cannot be reconsidered; a. fr.—Y. Maas. Sh. III, beg. 54ᵃ <span dir=\"rtl\">מְכוּרָתוֹ מיוחדת</span> its sale is permitted in a special Biblical passage (<span class=\"citation\">Deut. XIV, 24</span>, sq.).</div>","alt":[]},"13359":{"h":"מְכֵירִין","r":"M01383","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (μάχαιρα) <i>knives, daggers</i>. Tanḥ. Vayḥi 9 (play on <a href=\"#\" data-headword=\"מְכֵרוֹת\">מְכֵרוֹת</a>, <span class=\"citation\">Gen. XLIX, 5</span>) <span dir=\"rtl\">לשון יוני הוא שקורין לחרבות מ׳</span> it is Greek, in which swords are called <i>machaerin</i>. <span class=\"citation\">Gen. R. s. 99</span> <span dir=\"rtl\">לשון יוני הוא מ׳</span>; <span class=\"citation\">Pirké d’R. El. ch. XXXVIII</span> <span dir=\"rtl\">שהיונים קוראים לחרב מכיר</span> (read: <span dir=\"rtl\">מְכֵירָא</span>). <span class=\"citation\">Gen. R. s. 88</span> <span dir=\"rtl\">קונדא מ׳ נתנו וכ׳</span> (combine into one word: κονδομάχειρα, v. S. compounds of κοντο) they put short daggers in to their shoes. <span class=\"citation\">Lev. R. s. 33</span>, beg. <a href=\"#\" data-headword=\"מוכירין\">מוכירין</a> (corr. acc.), v. <a href=\"#\" data-headword=\"מִיצְטְרָא\">מיצטרא</a>.</div>","alt":[]},"13360":{"h":"מכיצטרכי","r":"M01384","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מגיסטריני\">מגיסטריני</a></div>","alt":[]},"13361":{"h":"מַכִּישָׁה","r":"M01385","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַכּוֹשׁ\"><span dir=\"rtl\">מַכּוֹשָׁא</span> I</a></div>","alt":[]},"13362":{"h":"מָכַךְ","r":"M01386","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מוּךְ\">מוּךְ</a>), <i>Hif.</i> הֵימֵךְ <i>to bend, lower</i>. <span class=\"citation\">Tosef. Naz. IV, 7</span> הֵימַכְתִּי את וכ׳ I bent my head.</div><div class=\"sense\"><b>Nif. נָמַךְ</b> <div class=\"sense\"><i>to be crushed</i>. <span class=\"citation\">Sifré Deut. 296</span> <span dir=\"rtl\">נָמַכּיּ</span>, v. <a href=\"#\" data-headword=\"חָשַׁל\">חָשַׁל</a>.</div></div><div class=\"sense\"><b>Nithpa. נִתְמַכֵּךְ</b> <div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִכְמֵךְ\">מִכְמֵךְ</a></div></div>","alt":[]},"13363":{"h":"מְכַךְ","r":"M01387","html":"<div class=\"sense\">, <i>to lower, level; to humiliate</i>. <span class=\"citation\">Targ. Y. Ex. XII, 37</span> <span dir=\"rtl\">למֵימַךְ וכ׳</span> to level mountains. <span class=\"citation\">Targ. Ps. XXXV, 15</span> (h. text <span dir=\"rtl\">נכים</span>).—<i>Part. pass</i>.: <a href=\"#\" data-headword=\"מַכִּיךְ\">מְכִיךְ</a>, pl. <span dir=\"rtl\">מְכִיכִין</span> <i>laid under, bolstered</i>. <span class=\"citation\">Targ. Ez. XXIII, 41</span>, v. <a href=\"#\" data-headword=\"מַכָּכָא\">next w.</a></div><div class=\"sense\"><b>Pa. מַכֵּךְ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"מָכַךְ\">same</a>. <span class=\"citation\">Targ. Y. Num. XIV, 14</span>. <span class=\"citation\">Targ. Prov. XXII, 22</span>.—<span class=\"citation\">Targ. Lam. III, 34</span>. <span class=\"citation\">Targ. Ps. CXLVII, 6</span> [read:] <span dir=\"rtl\">מְמַכֵּיךְ</span>, v. <a href=\"#\" data-headword=\"מְאַךְ\">מְאַךְ</a>; a. e.—<span class=\"citation\">Yoma 84ᵇ</span> מַכֵּיךְ מַכּוּכֵי Rashi a. Ms. O. (ed. <span dir=\"rtl\">מְמַכֵּיךְ</span>, v. Rabb. D. S. a. l. note 9; Ms. L. <span dir=\"rtl\">מסכיך סכוכי</span>, v. <a href=\"#\" data-headword=\"סְכַךְ\">סְכַךְ</a>) he subdues the flame (and produces a coal fire which can be utilized).</div></div><div class=\"sense\"><b>Ithpa. אִתְמַכֵּךְ</b> <div class=\"sense\"><i>to be humbled, cast down</i>. <span class=\"citation\">Targ. Ps. XLII, 6</span>; a. e.</div></div>","alt":[]},"13364":{"h":"מַכָּכָא","r":"M01388","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְכַךְ\">preced.</a>; cmp. <a href=\"#\" data-headword=\"מוֹךְ\">מוֹךְ</a>) <i>bolster, cushion</i>. <span class=\"citation\">Targ. Ez. XXIII, 41</span> <span dir=\"rtl\">מְכִיכִין מַ׳ דיקר</span> ed. Lag. (ed. only <span dir=\"rtl\">מַכִּיכִין דיקר</span>, corr. acc.) bolstered with cushions of honor. <span class=\"citation\">Targ. II Sam. XVII, 28</span> ed. Lag. (ed. <a href=\"#\" data-headword=\"מכבין\">מכבין</a>, corr. acc.; h. text <a href=\"#\" data-headword=\"מִשְׁכָּב\">מִשְׁכָּב</a>). <span class=\"citation\">Targ. Am. VI, 7</span> ed. Lag. (ed. <span dir=\"rtl\">מַכִּיכִין</span>).</div>","alt":[]},"13365":{"h":"מְכִכְתָּא","r":"M01389","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַכִּיךְ\">מכִּיךְ</a></div>","alt":[]},"13366":{"h":"מַכָּל","r":"M01390","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְכַל\">נָכַל</a>) <i>fraud, adulteration</i>. Mekh. Mishp. s. 13, v. <a href=\"#\" data-headword=\"דֶּלֶם\">דֶּלֶם</a>.</div>","alt":[]},"13367":{"h":"מֵכְלָא","r":"M01391","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵיכַל\">מֵיכְלָא</a></div>","alt":[]},"13368":{"h":"מְכִלָא","r":"M01392","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְכִילָא\">מְכִילָא</a></div>","alt":["מְכִלְתָּא"]},"13369":{"h":"מִכְלָה","r":"M01393","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>perfection</i>.—Pl. <span dir=\"rtl\">מִכְלוֹת</span>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a>; <span dir=\"rtl\">מ׳ זהב</span> (vessels) <i>made of pure gold</i>. <span class=\"citation\">Men. 29ᵃ</span> (expl. <span dir=\"rtl\">מ׳ זהב</span>, <span class=\"citation\">II Chr. IV, 21</span>) <span dir=\"rtl\">שכילתו לכל זהב וכ׳</span> it used up all the locked up gold of Solomon.</div>","alt":["מִי׳"]},"13370":{"h":"מְכַלֶּה","r":"M01394","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּלָה\">כָּלָה</a>) <i>Destroyer</i>, name of an angel of judgment. <span class=\"citation\">Deut. R. s. 3</span>, v. <a href=\"#\" data-headword=\"הַשְׁמֵד\">הַשְׁמֵד</a>.</div>","alt":[]},"13371":{"h":"מֵכְלוּתָא","r":"M01395","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵיכְלוּתָא\">מֵיכְלוּתָא</a></div>","alt":[]},"13372":{"h":"מִכְּלָל","r":"M01396","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלָל\">כְּלָל</a></div>","alt":[]},"13373":{"h":"מכללה","r":"M01397","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to II, 15</span>, v. <a href=\"#\" data-headword=\"בלטוורא\">בלטוורא</a></div>","alt":[]},"13374":{"h":"מַכְלַלְתָּא","r":"M01398","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּלַל\">כְּלַל</a>) <i>Makhlalta</i> (<i>Crown</i>). <span class=\"citation\">Targ. Y. Num. XXXII, 3</span>; <span class=\"citation\">34</span> (h. text <a href=\"#\" data-headword=\"עֲטָרוֹת\">עֲטָרוֹת</a>, <a href=\"#\" data-headword=\"עֲטָרוֹת\">עֲטָרֹת</a>). <span class=\"citation\">Ib. 35</span> <span dir=\"rtl\">מַכְלְלַת</span> (Y. II <span dir=\"rtl\">מ׳ ד־</span>; h. text <span dir=\"rtl\">עַטְרֹת</span>).</div>","alt":[]},"13375":{"h":"מְכִלְתָּא","r":"M01399","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְכִילָא\">מְכִילָא</a></div>","alt":[]},"13376":{"h":"מכלתייא","r":"M01400","html":"<div class=\"sense\">, Yalk. Dan. 1061 some ed., v. <a href=\"#\" data-headword=\"מצלתייא\">מצלתייא</a></div>","alt":[]},"13377":{"h":"מִכְמוֹר","r":"M01401","html":"<div class=\"sense\"><i>, </i> pl. <a href=\"#\" data-headword=\"*מִכְסוֹרִין\">מִכְמוֹרִין</a>, v. <a href=\"#\" data-headword=\"מִכְמוֹרֶת\">next w.</a></div>","alt":[]},"13378":{"h":"מִכְמוֹרֶת","r":"M01402","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> כמר <i>to hide</i>) <i>trap, small fisher’s net</i>, contrad. to <a href=\"#\" data-headword=\"חֵרֶם\">חֵרֶם</a>. <span class=\"citation\">Y. Pes. IV, 30ᵈ</span> top; <span class=\"citation\">Y. M. Kat. II, end, 81ᵇ</span> <span dir=\"rtl\">צד הוא במ׳</span> one may fish with the small net. <span class=\"citation\">Y. Yeb. XVI, 15ᵈ</span> top (prob. to be read: <span dir=\"rtl\">רוֹת …</span> pl.), v. <a href=\"#\" data-headword=\"כָּמַר\">כָּמַר</a>.—Pl. <a href=\"#\" data-headword=\"מִכְמוֹרֶת\">מִכְמוֹרוֹת</a>, <a href=\"#\" data-headword=\"*מִכְסוֹרִין\">מִכְמוֹרִין</a>, <span dir=\"rtl\">מִכְמֵרוֹת</span>. <span class=\"citation\">Tosef. Bets. III, 1</span>; Y. ib. 62ᵃ top. <span class=\"citation\">Yeb. 121ᵃ</span> <span dir=\"rtl\">מכמורין</span>; <span class=\"citation\">Tosef. ib. XIV, 6</span> <span dir=\"rtl\">מכמרות</span> (Var. <span dir=\"rtl\">מכמרראות</span>, read <span dir=\"rtl\">מַכְמוֹרָאוֹת</span>, fr. <span dir=\"rtl\">מַכְמוֹרִית</span>). <span class=\"citation\">Kel. XXIII, 5</span>. <span class=\"citation\">Makhsh. V, 7</span>. <span class=\"citation\">Pirké d’R. El. ch. LI</span> <span dir=\"rtl\">נאחזין במכמרותיהם</span> will be caught in the nets laid for them; a. e.</div>","alt":["מִכְמֶרֶת"]},"13379":{"h":"מִכְמֵךְ","r":"M01403","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מָכַךְ\">מָכַךְ</a>) <i>to crush</i>.</div><div class=\"sense\"><b>Nithpalp. נִתְמַכְמֵךְ</b> <div class=\"sense\"><i>to be crushed</i>. <span class=\"citation\">Snh. 101ᵇ</span> (Ar. ed. pr. <a href=\"#\" data-headword=\"מָכַךְ\">נִתְמַכֵּךְ</a>); cmp. <a href=\"#\" data-headword=\"מָעַךְ\">מָעַךְ</a>.</div></div>","alt":[]},"13380":{"h":"מכמם","r":"M01404","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִכְמָס\">next w.</a></div>","alt":[]},"13381":{"h":"מִכְמָס","r":"M01405","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Mikhmas</i> in Benjamin. <span class=\"citation\">Men. VIII, 1</span> (Bab. ed. 83ᵇ <a href=\"#\" data-headword=\"מכניס\">מכניס</a>, corr. acc.; v. Rabb. D. S. a. l.); Tosef. ib. IX, 2 <a href=\"#\" data-headword=\"מכמם\">מכמם</a> ed. Zuck. (Var. … <a href=\"#\" data-headword=\"מַס I\">מס</a>).</div>","alt":[]},"13382":{"h":"מִכְמַר","r":"M01406","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּמַר\">כְּמר</a></div>","alt":[]},"13383":{"h":"מִכְמָר","r":"M01407","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"מִכְמוֹרֶת\">מִכְמוֹרֶת</a>) <i>trap, net</i>. <span class=\"citation\">B. Kam. 117ᵃ</span>.—[<span dir=\"rtl\">מכמרים</span>, <span class=\"citation\">Esth. R. to VI, 10</span> ed. Wil., read <span dir=\"rtl\">מסמרים</span>.]</div>","alt":[]},"13384":{"h":"מִכְמֶרֶת","r":"M01408","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִכְמוֹרֶת\">מִכְמוֹרֶת</a></div>","alt":[]},"13385":{"h":"מִכְּמַת־","r":"M01409","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> constr. (compound of <span dir=\"rtl\">מִ</span>, <span dir=\"rtl\">כְּ</span> a. <a href=\"#\" data-headword=\"מָא\">מָא</a>; cmp. <a href=\"#\" data-headword=\"דִּכְמָא\">דִּכְמָא</a>) <i>of those like</i>. <span class=\"citation\">Targ. Ps. LXXIII, 15</span> ed. Lag., v. <a href=\"#\" data-headword=\"דִּכְמָא\">דִּכְמָא</a>.</div>","alt":[]},"13386":{"h":"מִכַּן","r":"M01410","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּאַן\">כַּאַן</a></div>","alt":[]},"13387":{"h":"מִכֵּן","r":"M01411","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֵּן I\">כִּן</a></div>","alt":[]},"13388":{"h":"מִכְנִי","r":"M01412","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּכְנִי\">מוּכְנִי</a></div>","alt":[]},"13389":{"h":"מכניס","r":"M01413","html":"<div class=\"sense\">, <span class=\"citation\">Men. 83ᵇ</span>, v. <a href=\"#\" data-headword=\"מִכְמָס\">מִכְמָס</a>.—(<span class=\"citation\">Gen. R. s. 31</span> <span dir=\"rtl\">מכניסו</span>, some ed., v. next w.].</div>","alt":[]},"13390":{"h":"מִכְנָס","r":"M01414","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּנַס\">כָּנַס</a>) </div><div class=\"sense\"><b>1)</b> <i>storing up, laid-in stock</i>. <span class=\"citation\">Y. Kil. II, beg. 27ᶜ</span> <span dir=\"rtl\">דרך מ׳</span> in the way of storing up (for home consumption). <span class=\"citation\">Gen. R. s. 31</span> <span dir=\"rtl\">רוב מִכְנָסוֹ</span>, v. <a href=\"#\" data-headword=\"דְּבֵילָה\">דְּבֵילָה</a>. Y. Dem. III, 22ᶜ top <span dir=\"rtl\">רוב מכנסו מישראל</span> the larger portion of his storage comes from Jews.</div><div class=\"sense\"><b>—2)</b>  בית מ׳ <i>the lower side of the shovel</i>, v. <a href=\"#\" data-headword=\"כּוֹנֵס\">כּוֹנֵס</a>. Y. B. Mets. IX, beg. 12ᵃ</div>","alt":[]},"13391":{"h":"מִכְנָסַיִם","r":"M01415","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> du. (b. h.; <a href=\"#\" data-headword=\"כָּנַס\">כָּנַס</a>) [<i>clothes of retirement</i>,] <i>undergarment, drawers.</i> <span class=\"citation\">Yoma VII, 5</span>. <span class=\"citation\">Ib. 23ᵇ</span> <span dir=\"rtl\">שלא יהא דבר קודם למ׳</span> that there must be no garment put on before (under) the drawers; a. fr.</div>","alt":["מִכְנָסַיִים"]},"13392":{"h":"מַכְנְסִין","r":"M01416","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Lev. VI, 3</span>; a. e.</div>","alt":["מִכְ׳"]},"13393":{"h":"מַכְנַשְׁתָּא","r":"M01417","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּנַשׁ\">כְּנַשׁ</a>) <i>gathering in</i>. <span class=\"citation\">B. Mets. 21ᵃ</span> <span dir=\"rtl\">מ׳ דבי דרי</span> the season of storing up the grains from the threshing floor; <span class=\"citation\">ib. 21ᵇ</span> <span dir=\"rtl\">מ׳ דביזרי</span> (corr. acc.). [Ar. s. v. <span dir=\"rtl\">כנש</span>, reads <a href=\"#\" data-headword=\"כְּנִישָׁא\">כְּנִישְׁתָּא</a>, and explains: <i>the sweepings</i> of the threshing floor.]</div>","alt":[]},"13394":{"h":"מָכַס","r":"M01418","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מֶכֶס\">next w.</a>) <i>to pay toll on</i>. <span class=\"citation\">Midr. Till. to Ps. CXVIII, 20</span> <span dir=\"rtl\">אם אינך מוֹכֵס כל וכ׳</span> unless thou payest the toll on all thy goods, thou wilt have nothing left.—V. <a href=\"#\" data-headword=\"מוֹכֵס\">מוֹכֵס</a>.</div>","alt":[]},"13395":{"h":"מֶכֶס","r":"M01419","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>marking off, counting</i>,) <i>toll, tax</i>. <span class=\"citation\">Succ. 30ᵃ</span> <span dir=\"rtl\">בית המ׳</span> the custom-house. <span class=\"citation\">Sabb. 33ᵇ</span>; <span class=\"citation\">Ab. Zar. 2ᵇ</span> <span dir=\"rtl\">תקנתם גשרים ליטול בהם מ׳</span> you put up bridges in order to raise toll on them. <span class=\"citation\">Ib. 13ᵃ</span> <span dir=\"rtl\">יניח לו את המ׳</span> to him shall the toll be remitted. Tanḥ. Lekh 5 <span dir=\"rtl\">טלו מ׳ של חטין</span> collect the duty as if it were wheat; a. fr.—Pl. <span dir=\"rtl\">מִכְסָאוֹת</span>. <span class=\"citation\">Ab. d’R. N. ch. XXVIII</span>.</div>","alt":[]},"13396":{"h":"מִכְסָא","r":"M01420","html":"<div class=\"sense\"> <span class=\"citation\">Gen. R. s. 40</span> <span dir=\"rtl\">כיון דמטא למ׳</span> (= <span dir=\"rtl\">לבי מ׳</span>) when he arrived at the custom-house. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הב מ׳</span> pay toll. <span class=\"citation\">Ab. Zar. 4ᵃ</span> <span dir=\"rtl\">שבקו ליה מ׳ וכ׳</span> they released him from taxes for thirteen years. [<a href=\"#\" data-headword=\"מִכְסָא\">מִכְסָא</a>, infin. of <a href=\"#\" data-headword=\"כְּסֵי\">כְּסָא</a>, v. <a href=\"#\" data-headword=\"כְּסַן\">כְּסַן</a>.]—Pl. <span dir=\"rtl\">מִכְסֵי</span>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a>. <a href=\"#\" data-headword=\"מְשָׁכָא\">בי מ׳</a> <i>Custom House</i>, name of a place. <span class=\"citation\">Keth. 112ᵃ</span> top; <span class=\"citation\">Yeb. 45ᵃ</span>; <span class=\"citation\">Gitt. 46ᵇ</span>; v. <a href=\"#\" data-headword=\"כּוּבָּא II\"><span dir=\"rtl\">כּוּבָּא</span> II</a>.</div>","alt":["מִיכְ׳"]},"13397":{"h":"מָכְסָא","r":"M01421","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹכֵס ²\">מוֹכְסָא</a></div>","alt":[]},"13398":{"h":"מכסאני","r":"M01422","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַכְסָנָא\">מַכְסָנָא</a></div>","alt":[]},"13399":{"h":"מִכְסֶה","r":"M01423","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>tent-cover</i>. <span class=\"citation\">Sabb. 28ᵃ</span>; a. e.—Pl. <span dir=\"rtl\">מִכְסָאוֹת</span>. Ib. <span class=\"citation\">Num. R. s. 12</span>, end; a. e.</div><div class=\"sense\"><b>—2)</b>  (v. <span class=\"citation\">Lev. III, 3</span>) <i>the cover of the inwards, peritoneum</i>. <span class=\"citation\">Y. Hor. I, 46ᵃ</span> top <span dir=\"rtl\">ושל מ׳</span> (not <span dir=\"rtl\">ולומ׳</span>) and the fat of the peritoneum.</div>","alt":[]},"13400":{"h":"*מִכְסוֹרִין","r":"M01424","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">כסר</span>, cmp. Arab. <i>kasar</i> and denom.) <i>division, settlement</i> of shares (cmp. <a href=\"#\" data-headword=\"מֶכֶס\">מֶכֶס</a>). Y’lamd. to Num. XXIII, 10, quot. in Ar. <span dir=\"rtl\">לכשתטול את שלך ותעשה המ׳ וכ׳</span> when thou (Balaam) takest thy share and makest a settlement, thou shalt agree with (or thank) me. [Ar. refers to <a href=\"#\" data-headword=\"אַכְסָרָה\">אַכְסָרָה</a>.]</div>","alt":["מַכְסִי׳"]},"13401":{"h":"מכסח","r":"M01425","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. VI, end, 8ᵈ</span> <span dir=\"rtl\">קריב למ׳</span>, read: <span dir=\"rtl\">למָכְסָה</span>, v. <a href=\"#\" data-headword=\"מוֹכֵס ²\">מוֹכְסָא</a></div>","alt":[]},"13402":{"h":"מכסיוטינוס","r":"M01426","html":"<div class=\"sense\">, Mekh. Yithro, Amal., s. 2 end, read: <span dir=\"rtl\">טַכְסְיוֹטֵיסִין</span> m. pl. (ταξεώτης) <i>magistrate’s assistants</i></div>","alt":[]},"13403":{"h":"מַכְסִירִין","r":"M01427","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*מִכְסוֹרִין\">מִכְסוֹרִין</a></div>","alt":[]},"13404":{"h":"מַכְסֵן","r":"M01428","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מַכְסָנָא\">next w.</a>) <i>to chastise</i>. [<span class=\"citation\">Targ. Ps. XCIV, 12</span> <span dir=\"rtl\">מכסניניה</span>, Var. ed. Lag., read: <span dir=\"rtl\">תַּכְסְ׳</span>, v. <a href=\"#\" data-headword=\"כְּסַן\">כְּסַן</a>.]</div><div class=\"sense\"><b>Ithpa. אִתְמַכְסֵן</b> <div class=\"sense\"><i>to be chastised</i>. <span class=\"citation\">Targ. Job XXXIII, 19</span>.</div></div>","alt":[]},"13405":{"h":"מַכְסָנָא","r":"M01429","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּסַן\">כְּסַן</a>) <i>chastiser</i>.—Pl. <span dir=\"rtl\">מַכְסָנֵי</span>. <span class=\"citation\">Targ. Prov. XXIV, 25</span> (ed. Lag. <a href=\"#\" data-headword=\"מאכסני\">מאכסני</a>, Ms. <a href=\"#\" data-headword=\"מכסאני\">מכסאני</a>).</div>","alt":[]},"13406":{"h":"מַכְסָנוּתָא","r":"M01430","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַכְסָנָא\">preced.</a>) <i>chastisement, rebuke</i>. <span class=\"citation\">Targ. Ps. L, 17</span>. <span class=\"citation\">Ib. XXXIX, 12</span> (some ed. <span dir=\"rtl\">מסכ׳</span>, corr. acc.); a. e.—Pl. <a href=\"#\" data-headword=\"מַכְסַנְיָיא\">מַכְסַנְיָיתָא</a> (v. <a href=\"#\" data-headword=\"מַכְסַנְיָיא\">next w.</a>). <span class=\"citation\">Ib. XXXVIII, 15</span>. <span class=\"citation\">Targ. Job XXIII, 4</span> <span dir=\"rtl\">מכסניותא</span> ed. Lag. (corr. <span dir=\"rtl\">מַכְסנְוָו׳</span> or <a href=\"#\" data-headword=\"מַכְסַנְיָיא\">מַכְסַנְיָי׳</a>; oth. ed. sing.).</div>","alt":[]},"13407":{"h":"מַכְסַנְיָיא","r":"M01431","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"מַכְסָנוּתָא\">same</a>. <span class=\"citation\">Targ. Job XXXI, 23</span> מַכְסַנְיֵיה Ms. (ed. Lag. <span dir=\"rtl\">מסּייפ־</span>; ed. Wil. <span dir=\"rtl\">מספיי׳</span>).</div>","alt":[]},"13408":{"h":"מכפה","r":"M01432","html":"<div class=\"sense\">, Y. Succ. II, end, 53ᵇ, read: <a href=\"#\" data-headword=\"מִקְפֶּה\">מִקְפֶּה</a>.</div>","alt":[]},"13409":{"h":"מַכְפֵּלָה","r":"M01433","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>doubling, coupling</i>. <span class=\"citation\">Erub. 53ᵃ</span> <span dir=\"rtl\">היינו מ׳</span> that is the reason why it is called ‘double cave’. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מאי מ׳</span> why is it called &amp;c.?—<span class=\"citation\">Gen. R. s. 98</span> <span dir=\"rtl\">שמע ישראל אבינו ממערת המ׳</span> hear, oh Israel, our father of the double cave!; a. e.</div>","alt":[]},"13410":{"h":"מָכַר","r":"M01434","html":"<div class=\"sense\"><i>to sell</i>. <span class=\"citation\">Sifré Deut. 169</span> (ref. to <span class=\"citation\">Deut. XVIII, 8</span>) <span dir=\"rtl\">מה מָכְרוּ וכ׳</span> what have the fathers sold to one another? (Answ. the weekly turns); <span class=\"citation\">Succ. 56ᵃ</span>; Y. ib. V, end, 55ᵈ. <span class=\"citation\">B. Bath. 64ᵇ</span>, a. fr. <span dir=\"rtl\">מוֹכֵר בעין יפה מוכר</span> the seller is presumed to sell liberally, i.e. to sell all except that which is specified as excluded; <span dir=\"rtl\">מ׳ בעיין רעה מ׳</span> he sells only that which is specified as sold. Ib. IV, 1 …<span dir=\"rtl\">המוכר … לא מ׳ וכ׳</span> if one sells …, he has not implicitly sold &amp;c. <span class=\"citation\">Sot. III, 8</span> <span dir=\"rtl\">אין האשה מוֹכֶרֶת וכ׳</span> a woman cannot sell her daughter; a. v. fr.—Part. pass. <a href=\"#\" data-headword=\"מִכְוַר\">מָכוּר</a>; f. <a href=\"#\" data-headword=\"מְכוּרָה\">מְכוּרָה</a>; <i>pl</i>. <span dir=\"rtl\">מְכוּרִים מְכוּרִין</span>; <a href=\"#\" data-headword=\"מְכוֹרוֹת\">מְכוּרוֹת</a>. <span class=\"citation\">Tosef. Ab. Zar. III</span> (<span class=\"citation\">IV), 18</span> <span dir=\"rtl\">הרי זה מ׳</span> he is sold (the sale is valid). <span class=\"citation\">B. Bath. IV, 3</span>. <span class=\"citation\">Tosef. B. Kam. VII, 8</span> <span dir=\"rtl\">חביות המ׳ וכ׳</span> wine casks which have been sold to the shopkeeper (awaiting delivery); a. v. fr.</div><div class=\"sense\"><b>Nif. נִמְכַּר</b> <div class=\"sense\"><i>to be sold</i>. Sot. l. c. <span dir=\"rtl\">האיש נ׳ … נִמְכֶּרֶת</span> a man can be sold for his theft, but a woman cannot &amp;c. Mekh. Mishp. s. 2; a. fr.</div></div>","alt":[]},"13411":{"h":"*מְכַר","r":"M01435","html":"<div class=\"sense\">, <i>Ithpa.</i> <a href=\"#\" data-headword=\"מְגַר\">אִתְמַכַּר</a> (denom. of <a href=\"#\" data-headword=\"מַכָּר\">מַכָּר</a>) <i>to be made acquainted</i>. <span class=\"citation\">Targ. Prov. XIX, 14</span> Var. ed. Lag. (ed. <span dir=\"rtl\">מתמסרא</span>, v. <a href=\"#\" data-headword=\"מְסַר\">מְסַר</a>).</div>","alt":[]},"13412":{"h":"מֶכֶר","r":"M01436","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>sale</i>. <span class=\"citation\">Kidd. 6ᵇ</span> <span dir=\"rtl\">במ׳ לא קנה</span> if the transaction is a sale (of land), he has not acquired possession (by delivering the purchasing money as a loan). <span class=\"citation\">Ib. 47ᵃ</span> <span dir=\"rtl\">ושוין במ׳</span> and they agree in the case of a sale. <span class=\"citation\">Keth. XI, 4</span> <span dir=\"rtl\">מִכְרָהּ בטל</span> her sale is invalid; a. fr.—V. <a href=\"#\" data-headword=\"מִמְכָּר\">מִמְכָּר</a>.</div>","alt":[]},"13413":{"h":"מַכָּר","r":"M01437","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>acquaintance, friend</i>. <span class=\"citation\">Y. Gitt. III, 45ᵃ</span> <span dir=\"rtl\">ויש מ׳ לעני</span> has the poor man a friend?, i.e., is he who separates the poor man’s tithes permitted to reserve them for a certain person?—Pl. <span dir=\"rtl\">מַכָּרִים</span>, constr. <span dir=\"rtl\">מַכָּרֵי</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">במ׳ כהונה וכ׳</span> the Mishnah speaks of friends of priests or Levites (to whom the owner is in the habit of giving the priestly shares); Bab. <span class=\"citation\">Gitt. 30ᵃ</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">במ׳ לא קתני</span> (sub. <a href=\"#\" data-headword=\"כְּהוּנָּה\">כהונה</a>) the Mishnah does not distinctly speak of friends. <span class=\"citation\">Ḥull. 133ᵃ</span>; a. fr.</div>","alt":[]},"13414":{"h":"מַכָּרָא","r":"M01438","html":"<div class=\"sense\"> <span class=\"citation\">Targ. II Kings XII, 6</span>.—Pl. <a href=\"#\" data-headword=\"מכרין\">מַכָּרִין</a>. <span class=\"citation\">Ib. 8</span>.</div>","alt":[]},"13415":{"h":"מְכֵרוֹת","r":"M01439","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"><b>1)</b>  (<a href=\"#\" data-headword=\"מָכַר\">מָכַר</a>) <i>sales</i>, trnsf. m. (cmp. <a href=\"#\" data-headword=\"לְקוּחוֹת\">לְקוּחוֹת</a>) <i>seller</i>. <span class=\"citation\">Gen. R. s. 98</span> (ref. to <span class=\"citation\">Gen. XLIX, 6</span> <span dir=\"rtl\">מְכֵרֹת־</span>) for whom are those weapons fit? <span dir=\"rtl\">למְכֵרוֹתֵיהֶן וכ׳</span> to their seller, to Esau who sold the birth-right (to their father).</div><div class=\"sense\"><b>—2)</b>  (= <a href=\"#\" data-headword=\"מְכֵרוֹת\">מְכֹרוֹת</a>, fr. <a href=\"#\" data-headword=\"נָכַר\">נָכַר</a>, cmp. <a href=\"#\" data-headword=\"מַכָּר\">מַכָּר</a>) <i>friendship, neighborhood, neighbors</i>. Tanḥ. Vayḥi 9; <span class=\"citation\">Gen. R. s. 99</span> (ref. to Gen. l. c.) <span dir=\"rtl\">וי&quot;א מכרותיהם מגורותיהם וכ׳</span> (ed. Wil. <span dir=\"rtl\">מְכוֹר׳</span>) and some say <i>m’kherothehem</i>, means their neighborhoods (ed. Wil.: and some say, read it <i>m’khorothehen</i>) as we read (<span class=\"citation\">Ez. XVI, 3</span>) &amp;c.—V. <a href=\"#\" data-headword=\"מְכֵירִין\">מְכֵירִין</a></div>","alt":[]},"13416":{"h":"מכרין","r":"M01440","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ḥall. I, 58ᵃ</span> top <span dir=\"rtl\">עיסת מ׳</span> (ed. Krot. <a href=\"#\" data-headword=\"מברין\">מברין</a>) prob. to be read <span dir=\"rtl\">מוֹכְרִין</span>, the dough prepared by sellers (intended to be used as leaven).</div>","alt":[]},"13417":{"h":"מִכְשׁוֹל","r":"M01441","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>hindrance</i>. <span class=\"citation\">Succ. 52ᵃ</span> ישעיה קראו מ׳ Isaiah called the evil inclination ‘hindrance’ (<span class=\"citation\">Is. LVII, 14</span>).</div>","alt":[]},"13418":{"h":"מַכְשִׁיר","r":"M01442","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּשֵׁר I\">כָּשֵׁר</a>) </div><div class=\"sense\"><b>1)</b> <i>preparatory means, preliminary acts</i>. <span class=\"citation\">Meg. 7ᵇ</span> <span dir=\"rtl\">מַכְשִׁירֵי אוכל נפש</span> acts preliminary to the preparation of food (as grinding the slaughtering knife &amp;c.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הוא ולא מַכְשִׁירָיו</span> it says (<span class=\"citation\">Ex. XII, 16</span>) ‘that’ (alone may be done), but not its preliminaries. Ib. <span dir=\"rtl\">מ׳ שאפשר וכ׳</span> acts which might have been done a day before. <span class=\"citation\">Erub. 102ᵇ</span>, sq. <span dir=\"rtl\">מ׳ מצוה</span> requirements of a religious act (to be performed on the Sabbath, v. <a href=\"#\" data-headword=\"דָּחָה\">דָּחָה</a>). <span class=\"citation\">Sabb. 136ᵃ</span> <a href=\"#\" data-headword=\"מילי ²\">מ׳ מילה</a> requirements for circumcision. <span class=\"citation\">Tosef. Pes. V, 1</span>; <span class=\"citation\">Y. Sabb. XIX, 17ᵃ</span> top; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>Makhshirin</i> (things which make an object fit for levitical uncleanness), name of a treatise of the Mishnah and Tosefta, of the Order of Tohăroth.</div>","alt":["מַכְשִׁירִין"]},"13419":{"h":"מְכַשֵּׁף","r":"M01443","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>sorcerer</i>. <span class=\"citation\">Snh. VII, 4</span>. <span class=\"citation\">Ib. 11</span> <span dir=\"rtl\">המ׳ העושה מעשה</span> a sorcerer, that is, he who performs a real act of sorcery; a. fr.—Pl. <span dir=\"rtl\">מְכַשְּׁפִים</span>. Tanḥ. Vaëra 3. <span class=\"citation\">Snh. 67ᵇ</span> אוב … בכלל מ׳ היו <i>Ob</i> and <i>Yidʿoni</i> are included in the law against sorcerers; a. fr.</div>","alt":[]},"13420":{"h":"מְכַשֵּׁפָה","r":"M01444","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מְכַשֵּׁף\">preced.</a>) <i>sorceress</i>. <span class=\"citation\">Snh. 67ᵃ</span> <span dir=\"rtl\">מ׳ אחד האיש וכ׳</span> by the expression ‘sorceress’ (<span class=\"citation\">Ex. XXII, 17</span>) both man and woman are meant. Y. ib. II, end, 25ᵈ <span dir=\"rtl\">בפרשת מ׳</span> on the section treating of sorcery; a. e.</div>","alt":[]},"13421":{"h":"מְכַשֵּׁפוּת","r":"M01445","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְכַשֵּׁפָה\">preced.</a>) <i>sorcery</i>. Tanḥ. Vayetsé 12 <span dir=\"rtl\">במ׳</span> (some ed. <span dir=\"rtl\">במכשפו</span>, corr. acc.) with sorcerous charms, v. <a href=\"#\" data-headword=\"צִיץ II\"><span dir=\"rtl\">צִיץ</span> II</a>.</div>","alt":[]},"13422":{"h":"מִכְתָּב","r":"M01446","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>writ, letter.</i> <span class=\"citation\">Ab. V, 6</span>, a. e. <span dir=\"rtl\">הכתב והמ׳</span>, v. <a href=\"#\" data-headword=\"כְּתָב\">כְּתָב</a>.—Pl. <span dir=\"rtl\">מִכְתָּבִים</span>, <span dir=\"rtl\">מִכְתָּבִין</span>. <span class=\"citation\">Tosef. Sabb. XVII</span> (<span class=\"citation\">XVIII), 8</span> <span dir=\"rtl\">המ׳ שבכרכים</span> (ed. Zuck. <span dir=\"rtl\">המִכְתָּמִין</span>) the public announcements in cities.</div>","alt":[]},"13423":{"h":"מִכְתָּב ²","r":"M01447","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Esth. IX, 27</span>.—Pl. <span dir=\"rtl\">מִכְתָּבִין</span>. <span class=\"citation\">Targ. Y. I Deut. XXXII, 8</span>.</div>","alt":["מִכְתָּבָא"]},"13424":{"h":"מְכַתֵּב","r":"M01448","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִכְתָּב ²\">preced.</a> wds.) <i>writing tool, pencil, stylus.</i> <span class=\"citation\">Kel. XIII, 2</span>; <span class=\"citation\">Tosef. Kel. B. Mets. III, 4</span> <span dir=\"rtl\">מ׳ שנטל הכותב וכ׳</span> the stylus of which the pointed end is broken off, v. <a href=\"#\" data-headword=\"כּוֹתֵב\">כּוֹתֵב</a>; <span class=\"citation\">Y. Sabb. VIII, 11ᵇ</span> bot. <span class=\"citation\">Kidd. 21ᵇ</span>; a. e.—Pl. <span dir=\"rtl\">מְכַתְּבִים</span>, <span dir=\"rtl\">מְכַתְּבִין</span>. Y. Taan. VI, 69ᵃ top <span dir=\"rtl\">במ׳ הללו אנו וכ׳</span> (not <span dir=\"rtl\">במכתובים</span>) with these our pencils we shall march out and stab them; <span class=\"citation\">Lam. R. to II, 2</span>; <span class=\"citation\">to III, 49</span>.</div>","alt":[]},"13425":{"h":"מְכַתְּבָא","r":"M01449","html":"<div class=\"sense\"> <span class=\"citation\">Ab. Zar. 22ᵇ</span>, v. <a href=\"#\" data-headword=\"דַּגָּלָא\">דַּגָּלָא</a></div>","alt":[]},"13426":{"h":"מִכְתָּבָא","r":"M01450","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִכְתָּב\">מִכְתָּב</a> ch.</div>","alt":[]},"13427":{"h":"מכתובים","r":"M01451","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְכַתֵּב\">מְכַתֵּב</a></div>","alt":[]},"13428":{"h":"מַכְתְּוָותָא","r":"M01452","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כָּתָא\">כָּתָא</a>) <i>after-crop</i>. <span class=\"citation\">Sabb. 110ᵇ</span> ממ׳ Ms. M., v. <a href=\"#\" data-headword=\"כָּתָא\">כָּתָא</a>.</div>","alt":[]},"13429":{"h":"מַכְתִּיר","r":"M01453","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּתַר\">כָּתַר</a></div>","alt":[]},"13430":{"h":"מִכְתָּם","r":"M01454","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>impression, writ</i>.—Pl. <span dir=\"rtl\">מִכְתָּמִין</span>. <span class=\"citation\">Tosef. Sabb. XVII</span> (<span class=\"citation\">XVIII), 8</span> ed. Zuck., v. <a href=\"#\" data-headword=\"מִכְתָּב\">מִכְתָּב</a> h.</div>","alt":[]},"13431":{"h":"מַכְתֵּשׁ","r":"M01455","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>mortar</i>. <span class=\"citation\">Y. Peah II, 17ᵃ</span> top, v. <a href=\"#\" data-headword=\"כָּתַשׁ\">כָּתַשׁ</a>.</div><div class=\"sense\"><b>—2)</b> <i>mortar-shaped cavity</i>;</div><div class=\"sense\"><b>—3)</b> <i>jaw</i>. <span class=\"citation\">Gen. R. s. 98</span> (expl. <span class=\"citation\">Jud. XV, 19</span>) <span dir=\"rtl\">המקום ההוא מ׳ שמו</span> that place was named <i>Makhtesh</i> (Cavity); ib. <span dir=\"rtl\">מלמד שהביא לו וכ׳</span> it intimates that the Lord opened to him a spring from between his (the ass’) teeth (taking <a href=\"#\" data-headword=\"מ׳\">מ׳</a> as <i>jaw</i>).</div><div class=\"sense\"><b>—4)</b> <i>an instrument of torture</i>. <span class=\"citation\">Tosef. Kel. B. Mets. VII, 8</span>, v. <a href=\"#\" data-headword=\"פֶּתִי\">פֶּתִי</a>. Pesik. Shek. p. 15ᵃ, v. <a href=\"#\" data-headword=\"חֲמוֹר\">חֲמוֹר</a>.</div>","alt":[]},"13432":{"h":"מַכְתַּשׁ","r":"M01456","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּתַשׁ\">כְּתַשׁ</a>) </div><div class=\"sense\"><b>1)</b> <i>wound, plague, affliction</i>. <span class=\"citation\">Targ. Ex. XI, 1</span>. <span class=\"citation\">Targ. Lev. XIII, 29</span>; a. fr.—[<span class=\"citation\">Targ. Y. Gen. XII, 19</span> <i>fem</i>.]—Pl. <span dir=\"rtl\">מַכְתָּשִׁין</span>, <span dir=\"rtl\">מַכְתְּ׳</span>. <span class=\"citation\">Targ. Gen. XII, 17</span>. <span class=\"citation\">Targ. Ps. LXXXIX, 33</span>.</div><div class=\"sense\"><b>—2)</b>  [<i>pounding</i>.—Pl. <a href=\"#\" data-headword=\"מַכְתַּשׁ\">מַכְתָּשֵׁי</a>, <span dir=\"rtl\">מַכְתְּ׳</span>. <span class=\"citation\">Targ. Prov. XXVII, 22</span>, combining massoretic vers. with one from which LXX. a. Pesh. are translated, v. <a href=\"#\" data-headword=\"*אוּרְדָּךְ\">אוּרְדָּךְ</a>.]</div>","alt":["מַכְתָּשָׁא"]},"13433":{"h":"מַכְתֶּשֶׁת","r":"M01457","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַכְתַּשׁ\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>mortar</i>. <span class=\"citation\">B. Bath. IV, 3</span> <span dir=\"rtl\">המ׳ הקבועה</span> the stationary mortar in the house. <span class=\"citation\">Ib. 65ᵇ</span>; Tosaf. ib. III, 1 <span dir=\"rtl\">המ׳ חקוקה</span> a mortar hewn out of a rock in the house. <span class=\"citation\">Taan. 28ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>cavity</i>. <span class=\"citation\">Tosef. Nidd. VIII, 6</span>; <span class=\"citation\">Nidd. 61ᵃ</span> <span dir=\"rtl\">מ׳ מלאה עצמות</span> a hole in the ground full of bones.</div>","alt":[]},"13434":{"h":"מָל","r":"M01458","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּל\">מוּל</a></div>","alt":[]},"13435":{"h":"מַל","r":"M01459","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָלַל I\">מָלַל</a>) <i>brittle, easily crushed</i>. Sifra Vayikra, N’dab., ch. XIV, Par. 13 (play on <span dir=\"rtl\">כ̇ר̇מ̇ל̇</span>, <span class=\"citation\">Lev. II, 14</span>) <span dir=\"rtl\">ר̇ך̇ מ̇ל̇</span> tender, yet brittle; <span class=\"citation\">Men. 66ᵇ</span> <span dir=\"rtl\">רך ומל</span> (Ms. M. <span dir=\"rtl\">כר ומלא</span>, v. Rabb. D. S. a. l. note); <span class=\"citation\">Y. Sabb. I, 2ᵈ</span> bot. <span dir=\"rtl\">רך מלא</span> (corr. acc.), v. <a href=\"#\" data-headword=\"כַּרְמֶל\">כַּרְמֶל</a>.</div>","alt":[]},"13436":{"h":"מִלָּא","r":"M01460","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִלְּתָא\">מִלְּתָא</a> a. <a href=\"#\" data-headword=\"מִלָּה\"><a href=\"#\" data-headword=\"מִלָּה\">מִלָּה</a>.</a></div>","alt":[]},"13437":{"h":"מָלֵא I","r":"M01461","html":"<div class=\"sense\"> (b. h.) <i>to be full</i>, v. <a href=\"#\" data-headword=\"מָלֵא II\"><span dir=\"rtl\">מָלֵא</span> II</a>.—<span class=\"citation\">Tosef. Dem. V, 24</span> <span dir=\"rtl\">היאך מְלָאֲךָ ליבך</span> how could thy heart be so full of thyself, i.e. how daredst thou?</div><div class=\"sense\"><b>Pi. מִלֵּא  מִילֵּא</b> <div class=\"sense\"><i>to fill, to draw</i> (water). <span class=\"citation\">Erub. VIII, 6</span> <span dir=\"rtl\">אין מְמַלְּאִין וכ׳</span> (Y. ed. <span dir=\"rtl\">מְמַלִּין</span>) you must not draw water out of it on the Sabbath. <span class=\"citation\">B. Bath. 162ᵇ</span> <span dir=\"rtl\">מִילְּאֵהוּ בקרובים</span> if he filled the vacant space on the document with the signatures of relatives; <span class=\"citation\">Gitt. 87ᵇ</span>. <span class=\"citation\">Hor. 11ᵇ</span> <span dir=\"rtl\">ממלא מקום אבותיו הוה</span> he was filling his ancestors’ place, was a direct successor; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְמַלֵּא</b> </div><div class=\"sense\"><b>Nithpa. נִתְמַלֵּא</b> <div class=\"sense\"><i>to be filled</i>. <span class=\"citation\">Ber. 3ᵇ</span>; <span class=\"citation\">59ᵃ</span> <span dir=\"rtl\">אין הבור מִתְמַלֵּא וכ׳</span>, v. <a href=\"#\" data-headword=\"חוּלְיָא I\"><span dir=\"rtl\">חוּלְיָא</span> I</a>. Y. Succ. III, end, 54ᵃ <span dir=\"rtl\">עד שיִתְמַלֵּא זקנו</span> until he has a full beard. Y. Ber. IX, 13ᵈ bot. <span dir=\"rtl\">הִתְמַלְּאִי דינרי זהב</span> be full of gold denars; <span dir=\"rtl\">והיתה מתְמַלְּאָה</span> and it became filled with &amp;c. <span class=\"citation\">Gen. R. s. 33</span> <span dir=\"rtl\">הִתְסַלְּאוּ רחמים אלו על אלו</span> be merciful to one another. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ראיתי … והִתְמַלֵּאתִי עליה רחמים</span> I saw her in distress and was filled with pity for her; a. fr.</div></div>","alt":[]},"13438":{"h":"מְלָא","r":"M01462","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a></div>","alt":[]},"13439":{"h":"מָלֵא II","r":"M01463","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>full.</i> <span class=\"citation\">Ab. IV, 20</span> <span dir=\"rtl\">יש … מ׳ ישן</span> many a new vessel is full of old wine (many a young man is full of wisdom). <span class=\"citation\">Meg. 6ᵃ</span> (ref. to <span class=\"citation\">Ez. XXVI, 2</span>) <span dir=\"rtl\">אם מ׳ זו חרבה זו</span> when one (of the two cities, Jerusalem and Caesarea) is full, the other is waste; a. fr.—Esp. <i>a full month</i>, of thirty days. <span class=\"citation\">Bekh. 58ᵃ</span> <span dir=\"rtl\">זימנין מ׳ וכ׳</span> at times (in some years) it is full, at times defective, v. <a href=\"#\" data-headword=\"חָסֵר\">חָסֵר</a>; a. fr.—Pl. <span dir=\"rtl\">מְלֵאִים</span>, <span dir=\"rtl\">מְלֵאִין</span>, <a href=\"#\" data-headword=\"מְלֵי\">מְלֵי׳</a>; f. <span dir=\"rtl\">מְלֵאוֹת</span>, <a href=\"#\" data-headword=\"מְלֵי\">מְלֵי׳</a>. <span class=\"citation\">Ber. 57ᵃ</span>; <span class=\"citation\">Erub. 19ᵃ</span>, a. e. <span dir=\"rtl\">מ׳ מצות כרמון</span> are full of good deeds as a pomegranate (is full of seeds); a. fr.—[<a href=\"#\" data-headword=\"מְלֵאָה\">מְלֵאָה</a> as a noun, v. <a href=\"#\" data-headword=\"מְלֵיאָה\">מְלֵיאָה</a>.]</div>","alt":["מְלֵאָה","מְלֵיאָה"]},"13440":{"h":"מְלֹא","r":"M01464","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"מְלוֹא\">מְלוֹא</a></div>","alt":["מְלָא"]},"13441":{"h":"מְלֵאָה","r":"M01465","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָלֵא II\"><span dir=\"rtl\">מָלֵא</span> II</a></div>","alt":[]},"13442":{"h":"מְלָאִי","r":"M01466","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>M’laï</i>. <span class=\"citation\">Sabb. 139ᵃ</span> (Ms. O. <a href=\"#\" data-headword=\"שמלאי\">שמלאי</a>, v. <span class=\"citation\">Snh. 98ᵃ</span>).</div>","alt":[]},"13443":{"h":"מְלָאי I","r":"M01467","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָלֵא I\">מָלֵא</a>) <i>store, goods, merchandise</i>. <span class=\"citation\">Pes. 31ᵇ</span> <span dir=\"rtl\">ומ׳ של נכרים</span> and the goods (in the store) belong to gentiles. <span class=\"citation\">Tosef. ib. I (II), 1</span>7 <span dir=\"rtl\">המ׳ של ישראל</span> if the goods belong to an Israelite. <span class=\"citation\">Pes. 53ᵇ</span> <span dir=\"rtl\">כל המטיל מ׳ לכיסוכ׳</span> one who throws the profits of merchandise into the purse of scholars, i.e., gives scholars an opportunity of gaining a livelihood.—<span class=\"citation\">Sabb. 56ᵃ</span> <span dir=\"rtl\">מ׳ הטילו על בעלי בתים</span> they (the sons of Samuel) forced goods on private people (abused their station by making people their mercantile agents or their customers); <span class=\"citation\">Tosef. Sot. XIV, 6</span>; <span class=\"citation\">ib. 5</span>; a. e.</div>","alt":[]},"13444":{"h":"מְלָאי II","r":"M01468","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>husk, glume</i>, v. <a href=\"#\" data-headword=\"מֵלַע\">מֵלַע</a>.</div>","alt":[]},"13445":{"h":"*מְלַאי","r":"M01469","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(<a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a>) <i>helve of an axe</i>. <span class=\"citation\">Y. Bets. II, 61ᶜ</span> top, quot. in Ḥiddushé Meïri, v. <a href=\"#\" data-headword=\"מוּלְיֵי\">מוּלְיֵי</a>.</div>","alt":[]},"13446":{"h":"מַלְאָךְ","r":"M01470","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> לאך <i>to work</i>, <i>messenger</i>, esp. <i>angel</i>. <span class=\"citation\">Gen. R. s. 50</span> <span dir=\"rtl\">אין מ׳ אחד עושה וכ׳</span> one angel never performs two missions. <span class=\"citation\">Snh. 96ᵃ</span> <span dir=\"rtl\">אותו מ׳ שנזדמן וכ׳</span> the name of the angel that came to Abraham was Night. <span class=\"citation\">Gen. R. s. 9</span> <span dir=\"rtl\">מַלְאַךְ חיים</span> angel of life. Ib., a. fr. <span dir=\"rtl\">מ׳ המות</span> (abbrev. <span dir=\"rtl\">מה&quot;מ</span>) angel of death; a. v. fr.—Pl. <a href=\"#\" data-headword=\"מַלְאָכִי\">מַלְאָכִים</a>. <span class=\"citation\">Gen. R. s. 50</span> <span dir=\"rtl\">ולא שני מ׳ וכ׳</span> nor do two angels go on one mission. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נדמו לו בדמות מ׳</span> they appeared to him as angels. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">משעשו שליחותן קראן מ׳</span> after they have done their mission, the text calls them messengers. <span class=\"citation\">Y. R. Hash. I, 56ᵈ</span> bot. <span dir=\"rtl\">אף שמות המ׳ עלו וכ׳</span> the names of the angels, too, came (to Palestine) with them (the exiles) from Babylonia; <span class=\"citation\">Gen. R. s. 48</span>.—<a href=\"#\" data-headword=\"מַלְאָכִי\">מַלְאֲכֵי</a> (<a href=\"#\" data-headword=\"ה\">ה</a>)<span dir=\"rtl\">שרת</span> (abbrev. <span dir=\"rtl\">מה&quot;ש</span>, <span dir=\"rtl\">מ&quot;ה</span>) the ministering angels. <span class=\"citation\">Sabb. 55ᵇ</span> <span dir=\"rtl\">תנא דמ&quot;ה</span> the teacher who said (ib. top) that the angels asked the Lord &amp;c. <span class=\"citation\">Ned. 20ᵃ</span> <span dir=\"rtl\">ד׳ דברים סחו לי מ&quot;ה</span> four things did the ministering angels tell me; <span class=\"citation\">ib. 20ᵇ</span> מאן מ&quot;ה רבנן ‘the ministering angels’ means <i>teachers;</i> <span dir=\"rtl\">מ&quot;ה ממש</span> ministering angels in the true sense.—<span class=\"citation\">Tosef. Sabb. XVII</span> (<span class=\"citation\">XVIII), 3</span> <span dir=\"rtl\">מַלְאֲכֵי שטן</span> messengers of hindrance, opp. to <span dir=\"rtl\">מה&quot;ש</span>.—<span class=\"citation\">Y. Shebu. VI, 37ᵃ</span> bot., a. fr. <span dir=\"rtl\">מלאכי חבלה</span>, v. <a href=\"#\" data-headword=\"חַבָּלָה\">חַבָּלָה</a>.—<span class=\"citation\">Ḥag. 5ᵇ</span>, a. fr. <a href=\"#\" data-headword=\"מַלְאָכִי\">מלאכי</a> (<a href=\"#\" data-headword=\"ה\">ה</a>)<a href=\"#\" data-headword=\"שָׁלוֹם I\">שלום</a> the angels of peace; a. v. fr.</div>","alt":[]},"13447":{"h":"מַלְאָךְ ²","r":"M01471","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. I Ex. IV, 25</span>; a. fr.—Pl. <span dir=\"rtl\">מַלְאָכַיָּא</span>, <a href=\"#\" data-headword=\"מַלְאָכִי\">מַלְאָכִין</a>, <a href=\"#\" data-headword=\"מַלְאָכִי\">מַלְאָכֵי</a>. <span class=\"citation\">Targ. Gen. XIX, 1</span>; a. fr.—<span class=\"citation\">B. Bath. 75ᵃ</span> <span dir=\"rtl\">פליגי תרי מ׳ ברקיע וכ׳</span> two angels in heaven, Michael and Gabriel, differ. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חזא מ׳ שרת וכ׳</span> he saw ministering angels sitting &amp;c. <span class=\"citation\">Koh. R. to IX, 11</span> (ref. to <span class=\"citation\">Ps. LXVIII, 13</span>) <span dir=\"rtl\">אפי׳ מלכיהון דמ׳ וכ׳</span> even the chiefs of the angels, Michael and Gabriel, were afraid of Moses. <span class=\"citation\">Taan. 24ᵇ</span>, v. <a href=\"#\" data-headword=\"מַלָּחָא\">מַלָּחָא</a>; a. fr.</div>","alt":["מַלְאֲכָא"]},"13448":{"h":"מְלָאכָה","r":"M01472","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מַלְאָךְ ²\">preced.</a>) <i>work, trade, vocation; task.</i> <span class=\"citation\">Ab. I, 10</span> <span dir=\"rtl\">אהוב את המ׳</span> love trade, opp. to <a href=\"#\" data-headword=\"רַבָּנוּת\">רבנות</a>, office. <span class=\"citation\">Ned. 49ᵇ</span>, v. <a href=\"#\" data-headword=\"גָּדוֹל\">גָּדוֹל</a>. <span class=\"citation\">Ber. 17ᵃ</span> <span dir=\"rtl\">אני מְלַאכְתִּי בעיר</span> my work (study) is done in town, <span dir=\"rtl\">והוא מְלַאכְתּוֹ בשדה וכ׳</span> and his, in the field &amp;c., v. <a href=\"#\" data-headword=\"גָּדַר\">גָּדַר</a>. <span class=\"citation\">Ab. II, 14</span> <span dir=\"rtl\">בעל מְלַאכְתְּךָ</span> thy <i>employer</i> (the Lord). <span class=\"citation\">Ib. 15</span> <span dir=\"rtl\">היום קצר והמ׳ מרובה</span> the day (life) is short, and the task great. <span class=\"citation\">Ab. d’R. N. ch. XI</span> <span dir=\"rtl\">ועשו בו מ׳ בשבת</span> (not <span dir=\"rtl\">ועשה</span>) and they made him work on the Sabbath. <span class=\"citation\">Sabb. VII, 1</span> <span dir=\"rtl\">אב מ׳</span>, v. <a href=\"#\" data-headword=\"אַבָּא I\">אָב</a>; a. v. fr.—Pl. <a href=\"#\" data-headword=\"מַלְאָכוּת\">מְלָאכוֹת</a>. Ib. <span dir=\"rtl\">עשה מ׳ הרבה וכ׳</span> he did several (forbidden) labors on several successive Sabbaths. Ib. 2, v. <a href=\"#\" data-headword=\"אַבָּא I\">אָב</a>; a. v. fr.</div>","alt":["מְלֶאכֶת"]},"13449":{"h":"מַלְאָכוּת","r":"M01473","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>messenger’s function, angeldom</i>. <span class=\"citation\">Gen. R. s. 50</span>; <span class=\"citation\">Yalk. ib. 84</span> <span dir=\"rtl\">לבשו מ׳</span> they put on the appearance of angels.</div>","alt":[]},"13450":{"h":"מַלְאָכִי","r":"M01474","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Malachi</i>, the prophet. <span class=\"citation\">Meg. 15ᵃ</span> מ׳ זה מרדכי M. means Mordecai, <span dir=\"rtl\">ולמה נקרא שמו מ׳ וכ׳</span> and why is he called M. (minister)? Because he was viceroy. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מ׳ שמו</span> the prophet’s real name was M. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בנביאות מ׳</span> in the prophetic book of M.—<span class=\"citation\">Ex. R. s. 28</span>; a. e.</div>","alt":[]},"13451":{"h":"מְלֶאכֶת","r":"M01475","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְלָאכָה\">מְלָאכָה</a></div>","alt":[]},"13452":{"h":"מַלְאֲתָא","r":"M01476","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , (<i>the priestly gift from</i>) <i>the fruits laid in store</i>. <span class=\"citation\">Targ. O. Num. XVIII, 27</span> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"מַלְאֲתָא\">מְלֵאָתָא</a>; Ms. I <span dir=\"rtl\">מְלֵיתָא</span>, II <a href=\"#\" data-headword=\"מַלְיְיתָא\">מַלְיְיתָא</a>; Y. <span dir=\"rtl\">חמרא דמַלְיָתָא</span>).</div>","alt":[]},"13453":{"h":"מַלְבּוּשׁ","r":"M01477","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>dress, cover.</i> <span class=\"citation\">Shek. V, 1</span> <span dir=\"rtl\">על המ׳</span>, v. <a href=\"#\" data-headword=\"לָבַשׁ\">לָבַשׁ</a> <i>Hif.</i>—<span class=\"citation\">Deut. R. s. 7</span>, end <a href=\"#\" data-headword=\"מַלְבּוּשׁ\">מַלְבּוּשׁוֹ</a> its dress (shell), v. <a href=\"#\" data-headword=\"חִלָּזוֹן\">חִלָּזוֹן</a>. <span class=\"citation\">Sabb. 113ᵃ</span> <span dir=\"rtl\">שלא יהא מַלְבּוּשְׁךָ של שבת כמלבושך וכ׳</span> that thy Sabbath dress be not the same as thy weekday dress.</div>","alt":[]},"13454":{"h":"מַלְבֵּין","r":"M01478","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַלְבֵּן\">מַלְבֵּן</a></div>","alt":[]},"13455":{"h":"מַלְבִּינִיקֵי","r":"M01479","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (a corrupt. of mala pumica) <i>pome-granates</i>. <span class=\"citation\">Y. Sabb. VI, 8ᵃ</span> bot.; <span class=\"citation\">Y. Yeb. XII, 12ᵈ</span> top, v. <a href=\"#\" data-headword=\"אֱגוֹד\">אֱגוֹד</a>.</div>","alt":["מַלְבְּנִיקֵי"]},"13456":{"h":"מַלְבֵּינְתָּא","r":"M01480","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*מַלְבֵּנְתָּא\">מַלְבֵּנְתָּא</a></div>","alt":[]},"13457":{"h":"מַלְבִּישׁ","r":"M01481","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"לָבַשׁ\">לָבַשׁ</a></div>","alt":[]},"13458":{"h":"מַלְבֵּן","r":"M01482","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"לְבֵנָה\">לְבֵנָה</a>) </div><div class=\"sense\"><b>1)</b> <i>press, frame, mould</i>. <span class=\"citation\">Sot. 11ᵃ</span> (ref. to <span class=\"citation\">Ex. I, 11</span>) <span dir=\"rtl\">הביאו מ׳ וכ׳</span> they brought a brick mould and suspended it from Pharaoh’s neck; <span class=\"citation\">Ex. R. s. 1</span>. <span class=\"citation\">Zeb. 54ᵃ</span> <span dir=\"rtl\">מ׳ שהוא שלשים וכ׳</span> a frame of thirty-two by thirty-two cubits (which was filled with stones, cement &amp;c.). <span class=\"citation\">Y. Sabb. XII, beg. 13ᶜ</span> <span dir=\"rtl\">כנוטל מ׳ וכ׳</span> like taking a frame and putting it over the piled up bricks (which cannot be called building). <span class=\"citation\">Tosef. Sabb. XIII</span> (<span class=\"citation\">XIV), 15</span> <span dir=\"rtl\">מ׳ של מיטה</span> the frame (bottom) of a bedstead. Tosef. Erub. XI (VIII), 17 <span dir=\"rtl\">מ׳ של ספקלריא</span> a window frame. <span class=\"citation\">Tosef. B. Bath. II, 14</span> <span dir=\"rtl\">מ׳ או צורת וכ׳</span> a window frame or the shape of a door; <span class=\"citation\">B. Bath. III, 6</span>. <span class=\"citation\">Tosef. Kel. B. Mets. V, 9</span> <span dir=\"rtl\">מ׳ להיות נותנו וכ׳</span> a bedstead bottom intended to be moved from one bed to another, opp. intended for one particular bed. <span class=\"citation\">Tosef. Ohol. XIII, 5</span> [read:] <span dir=\"rtl\">מ׳ שהוא מלובש וכ׳</span>, v. <a href=\"#\" data-headword=\"לָבַשׁ\">לָבַשׁ</a>. <span class=\"citation\">Tosef. Kel. B. Bath. I, 8</span> <span dir=\"rtl\">מ׳ של מסר הגדול</span> the frame of a large saw. <span class=\"citation\">Neg. XIII, 3</span> <span dir=\"rtl\">מ׳ הבנוי וכ׳</span> a casing to protect that portion of the beam which rests on the wall.—<span class=\"citation\">Gen. R. s. 38</span>; <span class=\"citation\">Yalk. Prov. 961</span> (ref. to <span class=\"citation\">Prov. XXVII, 22</span>) <span dir=\"rtl\">כזה שהוא … במ׳</span> like one undertaking to crush barley in a frame; a. fr.—Pl. <span dir=\"rtl\">מַלְבֵּנִים</span>, <span dir=\"rtl\">מַלְבֵּנִין</span>, <span dir=\"rtl\">מַלְבֵּנוֹת</span>, <a href=\"#\" data-headword=\"מַלְבֵּין\">מַלְבֵּי׳</a>. Neg. l. c. <span class=\"citation\">B. Bath. 69ᵃ</span> <span dir=\"rtl\">מ׳ של פתחים</span> door frames; <span dir=\"rtl\">מ׳ של חלונות</span> window frames; <span dir=\"rtl\">מ׳ של כרעי המטה</span> sockets for the legs of a bedstead. <span class=\"citation\">Kel. XVIII, 3</span> <span dir=\"rtl\">מֵלְבְּנֵי בני לוי</span> stands for the musical instruments of the Levites; <span class=\"citation\">Tosef. Kel. B. Mets. V, 9</span> <span dir=\"rtl\">מ׳ לוי</span> ed. Zuck. (corr. acc.); a. e.—2) (from its shape) <i>a small garden-bed, a plot</i> (of three hand-breadths in width).—Pl. as ab. <span class=\"citation\">Peah III, 1</span>. <span class=\"citation\">Ib. 4</span> <span dir=\"rtl\">מ׳ הבצלים שבין הירק</span> plots of onions between vegetables. <span class=\"citation\">Ib. VII, 2</span> <span dir=\"rtl\">ג׳ שורות של שני מ׳</span> three rows at a distance of two <i>malbenim</i> (six hand-breadths) from one another; <span class=\"citation\">Tosef. ib. III, 10</span>. <span class=\"citation\">Ter. IV, 8</span> <a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a> (sub. <span dir=\"rtl\">דבלי</span>) figs pressed in quadrangular moulds, opp. <span dir=\"rtl\">עגולים</span>.</div>","alt":["מַלְבֵּין"]},"13459":{"h":"מַלְבְּנָא","r":"M01483","html":"<div class=\"sense\">, <i>a quadrangular piece</i>. <span class=\"citation\">B. Mets. 116ᵇ</span> <span dir=\"rtl\">מ׳ רווחא</span> a wide piece of cemented bricks of a fallen wall (Ms. F. <span dir=\"rtl\">ליבנא רווחא</span> a brick wider than the usual size, v. Rashi a. l.).</div>","alt":[]},"13460":{"h":"*מַלְבֵּנְתָּא","r":"M01484","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַלְבְּנָא\">preced.</a> wds.) <i>quadrangular frame</i>. <span class=\"citation\">Targ. Y. Num. XXXIII, 20</span> [prob. to be read:] <span dir=\"rtl\">מַלְבֵּינָתָא דבניין</span> (<i>pl.</i>) building moulds.</div>","alt":["מַלְבֵּינְ׳"]},"13461":{"h":"מַלְבֶּשְׁתָּא","r":"M01485","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּבֶשְׁתָּא\">דְּבֶשְׁתָּא</a></div>","alt":[]},"13462":{"h":"מָלַג","r":"M01486","html":"<div class=\"sense\"> (cmp. Syr. <span dir=\"rtl\">מלג</span>, P. Sm. 2131) <i>to pluck, to strip</i> (of hair, feathers &amp;c.). <span class=\"citation\">Tosef. Bets. III, 19</span> <span dir=\"rtl\">מוֹלְגִין את וכ׳</span> you may cleanse the head and legs of an animal (by scalding).</div>","alt":[]},"13463":{"h":"מְלַג","r":"M01487","html":"<div class=\"sense\">, <i>to pluck</i> (cmp. Pesh. <span class=\"citation\">Deut. XXIII, 26</span>). <span class=\"citation\">Gen. R. s. 45</span>, beg. (expl. <a href=\"#\" data-headword=\"מְלוֹג\">מְלוֹג</a>) <span dir=\"rtl\">מה את מָלֵיג מְלִיג</span> Ar. whatever thou pluckest, is plucked; (ed. <span dir=\"rtl\">כמה דתימא מְלוֹג מְלוֹג</span> as you say, ‘pluck, pluck’); <span class=\"citation\">Y. Yeb. VII, 8ᵃ</span> bot. <span dir=\"rtl\">כמה דאת אמר מליג מליג</span> (corr. acc.).</div>","alt":[]},"13464":{"h":"מַלְגֵּז","r":"M01488","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (transpos. of <a href=\"#\" data-headword=\"מַזְלֵג\">מַזְלֵג</a>) <i>pitch-fork; the cook’s fork</i>. <span class=\"citation\">Sabb. XVII, 2</span> (<span class=\"citation\">122ᵇ</span>; Mish. a. Ms. M. <a href=\"#\" data-headword=\"מַזְלֵג\">מזלג</a>); Y. ib. 16ᵇ top <span dir=\"rtl\">את המ׳ לתת עליו לקטן</span> the kitchen fork to place food for a child upon it. Tosef. ib. X (XI), 7; Sifra Vayikra, Ḥobah, ch. IX, Par. 7, a. e., v. <a href=\"#\" data-headword=\"לָגַז\">לָגַז</a>.</div>","alt":[]},"13465":{"h":"מִלָּה","r":"M01489","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>word</i>. <span class=\"citation\">Lev. R. s. 16</span> (prov.) <span dir=\"rtl\">מ׳ בסלע משתוקא בשנים</span> where a word is worth a Sela, silence is worth two; <span class=\"citation\">Meg. 18ᵃ</span> (v. Rabb. D. S. a. l. note 1).—Pl. <span dir=\"rtl\">מִלִּין</span>, <a href=\"#\" data-headword=\"מִי I\">מִי</a>. <span class=\"citation\">Cant. R. to IV, 4</span>, v. <a href=\"#\" data-headword=\"קָצַב\">קָצַב</a>; a. e.—Ch. <a href=\"#\" data-headword=\"מִלָּה\">מִלָּה</a>, v. <a href=\"#\" data-headword=\"מִילָּא I\">מִילָּא</a>.]</div>","alt":["מִי׳"]},"13466":{"h":"מל\"ה","r":"M01490","html":"<div class=\"sense\">, <span class=\"citation\">Y. Naz. II, 51ᵈ</span> bot., v. <a href=\"#\" data-headword=\"דל\">דל&quot;ה</a></div>","alt":[]},"13467":{"h":"מלהטמייא","r":"M01491","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"לָטוֹמְיָא\">לָטוֹמְיָא</a></div>","alt":[]},"13468":{"h":"מְלוֹא","r":"M01492","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>fulness, contents.</i> <span class=\"citation\">Mikv. III, 1</span>, sq. <span dir=\"rtl\">עד שיצא ממנו מְלוֹאוֹ ועוד</span> until a quantity equal to its original contents and something besides have run off. <span class=\"citation\">Y. Succ. I, 51ᵈ</span> top <span dir=\"rtl\">אכסדרה שנפרצה במְלוֹאָהּ וכ׳</span> an <i>exedra</i> which is (on one side) entirely open towards the public road. Ib. bot. <span dir=\"rtl\">כמְלוֹאוֹ של דלי</span> as far as the bucket is let down into the water (for filling it). <span class=\"citation\">Ḥull. II, 3</span> <span dir=\"rtl\">אם יש בסכין מְלֹא צואר</span> if the slaughtering knife has the length of the width of the neck. <span class=\"citation\">Kidd. 33ᵃ</span> <span dir=\"rtl\">מ׳ עיניו</span> as far as his eye can reach. <span class=\"citation\">Sabb. 30ᵃ</span>, a. e. <span dir=\"rtl\">כמ׳ נימא</span> as much as a hair’s breadth. <span class=\"citation\">Sifré Num. 160</span> (expl. <span dir=\"rtl\">אבן יד</span>, <span class=\"citation\">Num. XXXV, 17</span>) <span dir=\"rtl\">מ׳ יד</span> as large as the grasp of the hand; a. fr.—[<span class=\"citation\">Tosef. Ohol. XVII, 3</span> <span dir=\"rtl\">מ׳ טימיא</span>, v. <a href=\"#\" data-headword=\"לָטוֹמְיָא\">לָטוֹמְיָא</a>.]</div>","alt":["מְלֹא"]},"13469":{"h":"מְלוֹא ²","r":"M01493","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Num. XXXV, 17</span>. <span class=\"citation\">Targ. O. Deut. XXXIII, 16</span> (Y. <span dir=\"rtl\">ומַלְיָהּ</span>, v. <a href=\"#\" data-headword=\"מַלְיָא\"><span dir=\"rtl\">מַלְיָא</span> II</a>); a. e.—<span class=\"citation\">Ab. Zar. 29ᵃ</span> <span dir=\"rtl\">מ׳ חמש אצבעתיה</span> as much as one can pinch with five fingers; <span dir=\"rtl\">מ׳ אצבעיה … ומ׳ וכ׳</span> as much as one can pinch with thumb and little finger; a. e.</div>","alt":["מְלָא"]},"13470":{"h":"מִלּוּא","r":"M01494","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מְלוֹא ²\">same</a>, <i>full capacity</i>. <span class=\"citation\">Gitt. 70ᵃ</span> <span dir=\"rtl\">מִילּוּאֲךָ</span> (Ar. <span dir=\"rtl\">מליאה</span>), v. <a href=\"#\" data-headword=\"כָּעַס\">כָּעַס</a> 2. Ohol. XIV, 2 <span dir=\"rtl\">מִלּוּאוֹ</span>; Tosef. ib. XIV, 7 <span dir=\"rtl\">במִילּוּאוֹ</span> the full extent of the hole which the carpenter’s borer is capable of making, opp. <span dir=\"rtl\">מְלֹא מקדח כל שהוא</span>, v. <a href=\"#\" data-headword=\"מַקְדֵּחַ\">מַקְדֵּחַ</a>. Ib. 4, a. e.—Pl. <span dir=\"rtl\">מִלּוּאִים</span>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a> (b. h.) [<i>filling one’s hands</i>,] <i>investment, inauguration</i>. <span class=\"citation\">Lev. R. s. 11</span>, a. fr. <span dir=\"rtl\">שבעת ימי המ׳</span> the seven days of the inauguration of the priests (<span class=\"citation\">Lev. VIII). Y. Yoma I, 38</span>I, 38ᵇ bot. <span dir=\"rtl\">מ׳ מה היו</span> of what nature were the sacrifices at the inauguration?; a. e.—<i>Milluim</i>, name of the first division of Sifra Sh’mini.</div>","alt":["מִילּוּא"]},"13471":{"h":"מְלוֹג","r":"M01495","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָלַג\">מָלַג</a>, v. <a href=\"#\" data-headword=\"מְלַג\">מְלַג</a>) [<i>plucking</i>,] <i>usufruct</i>.—<span dir=\"rtl\">עבדי מ׳</span> (<a href=\"#\" data-headword=\"נִכְסִין\">נכסי</a>) a wife’s estate of which the husband has the fruition without responsibility for loss or deterioration, contrad. to <span dir=\"rtl\">צאן ברזל</span>, v. <a href=\"#\" data-headword=\"בַּרְזֶל\">בַּרְזֶל</a>. <span class=\"citation\">Yeb. VII, 1</span>; <span class=\"citation\">Tosef. ib. IX, 1</span>. <span class=\"citation\">Keth. 79ᵇ</span> <span dir=\"rtl\">בהמת מ׳</span> a domestic animal belonging to the wife &amp;c.—<span class=\"citation\">Gen. R. s. 45</span> שפחת מ׳ היתה וכ׳ Hagar was a handmaid of Sarah whom Abraham had to support but could not sell; a. fr.</div>","alt":[]},"13472":{"h":"*מְלוֹגָא","r":"M01496","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(v. <a href=\"#\" data-headword=\"מָלַג\">מָלַג</a>) <i>a hairless skin, bag</i>.—<span dir=\"rtl\">מ׳ דשטרי</span> a bag containing documents. <span class=\"citation\">Keth. 85ᵃ</span>. <span class=\"citation\">B. Bath. 151ᵃ</span></div>","alt":[]},"13473":{"h":"מָלוּגְמָא","r":"M01497","html":"<div class=\"sense\"> c. (μάλαγμα) <i>any emollient, plaster, poultice</i>. Sifra B’har ch. I (ref. to <span class=\"citation\">Lev. XXV, 6</span>) <span dir=\"rtl\">ולא לעשות ממנה מ׳</span> but not to use (the fruits of the Sabbatical year) for a poultice; <span class=\"citation\">Succ. 40ᵇ</span>; <span class=\"citation\">B. Kam. 102ᵃ</span>. <span class=\"citation\">Tosef. Dem. I, 25</span> <span dir=\"rtl\">קמח לעשות מ׳</span> flour to make poultices; a. fr.—Trnsf. <i>a soothing remedy</i>. <span class=\"citation\">Sabb. 119ᵇ</span> <span dir=\"rtl\">חמין … מ׳</span> hot water after the exit of the Sabbath is soothing. <span class=\"citation\">Deut. R. s. 8</span> <span dir=\"rtl\">מ׳ למכה</span> the Law is an emollient for every wound; <span class=\"citation\">Midr. Till. to Ps. XIX</span> <span dir=\"rtl\">מ׳ ללב</span> soothing for the heart; <span class=\"citation\">Yalk. Ps. 675</span>; <span class=\"citation\">Lev. R. s. 12</span> <a href=\"#\" data-headword=\"מולגיה\">מוליגא</a>, <span dir=\"rtl\">מוליגי׳</span> (corr. acc.)</div>","alt":["מָלוּגְמָה"]},"13474":{"h":"מְלוֹגְנָאָה","r":"M01498","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>of M’loga</i> (supposed to be a Babylonian place), <span dir=\"rtl\">קבא מ׳</span> name of a particular <i>Kab</i> measure. <span class=\"citation\">Pes. 48ᵃ</span> <span dir=\"rtl\">קבא מ׳</span> (Ar. a. Ms. M. 2 מַגְלוֹנָאָה <i>of Magla</i>, v. Rabb. D. S. a. l. note 100). Ib.ᵇ <span dir=\"rtl\">קבא מְלוֹגְנַאי</span> (Ms. M. 2 a. oth. … <span dir=\"rtl\">אה</span>).</div>","alt":[]},"13475":{"h":"מַלְוֶה","r":"M01499","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>creditor</i>, v. <a href=\"#\" data-headword=\"לָוָה\">לָוָה</a>.</div>","alt":[]},"13476":{"h":"מִלְוָה","r":"M01500","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"לָוָה\">לָוָה</a>) <i>loan, debt</i>. <span class=\"citation\">Keth. IX, 2</span> <span dir=\"rtl\">והיה לו פקדון או מ׳ וכ׳</span> and left a trust or a loan in the hands of strangers. <span class=\"citation\">Ib. 84ᵃ</span> <span dir=\"rtl\">מ׳ להוצאה ניתנה</span> a loan is made to be spent (opp. to trust). <span class=\"citation\">Kidd. 6ᵇ</span>, a. e. <span dir=\"rtl\">המקדש במ׳ וכ׳</span> if one betroths a woman to himself by remitting her indebtedness to him, she is not betrothed (there being no consideration offered to her at the time); <span dir=\"rtl\">בהנאת מ׳</span> offering as a consideration the benefit of the loan (by extension). Ib. 47ᵇ, a. fr. <span dir=\"rtl\">מ׳ על פה</span> a verbal loan, <span dir=\"rtl\">מ׳ בשטר</span> against a note. Ib. 46ᵃ, a. e. <span dir=\"rtl\">המקדש במ׳ ופרוטה</span> if one betroths a woman with remittance of a loan and the offer of a P’rutah besides.—<span class=\"citation\">Bekh. 48ᵃ</span>; a. e. <span dir=\"rtl\">מ׳ הכתובה בתורה</span> an obligation arising from a Biblical law, e.g. the duty of redeeming the first-born; a. fr.</div>","alt":[]},"13477":{"h":"מְלַוִּויתָא","r":"M01501","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"לְוִי\">לְוֵי</a>) <i>funeral escort, wailing ceremonies</i>. <span class=\"citation\">Midr. Till. to Ps. CIV, 26</span> (play on <span dir=\"rtl\">לויתן זה</span>, ib.) <span dir=\"rtl\">זה טובוי מן הדא מ׳</span> this (the reward of the hereafter) does him more good than that funeral service (with its eulogies, <span class=\"citation\">Koh. XII, 5</span>; ed. Bub. <span dir=\"rtl\">טיבוי מן ואת מלוותא</span>; <span class=\"citation\">Yalk. Ps. 862</span> <span dir=\"rtl\">זה טיביו מן דאת מְלַוִּיתֵי׳</span> (corr. acc.).</div>","alt":[]},"13478":{"h":"מִלְוָון","r":"M01502","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Beth Milvan</i> (prob. = b. h. <span dir=\"rtl\">בֵּית מִלֹּא</span>, <span class=\"citation\">II Kings XII, 21</span>; cmp. <a href=\"#\" data-headword=\"מַלְיְתָא\">מִלֵּיתָא</a>). <span class=\"citation\">Y. Meg. IV, 75ᶜ</span> bot.</div>","alt":["בֵּית מ׳"]},"13479":{"h":"מלוותא","r":"M01503","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְלַוִּויתָא\">מִלַוִּויתָא</a></div>","alt":[]},"13480":{"h":"מְלוּזְמָא","r":"M01504","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a Babylonian corrupt. of νόμισμα, numisma) <i>stamp</i> of a coin. <span class=\"citation\">Ber. 53ᵇ</span> <span dir=\"rtl\">כדי שיכיר בין מ׳ … למ׳ וכ׳</span> when one can distinguish the stamp of a Tiberian coin from that of a Sepphorian coin.</div>","alt":["מְלוּזְמָה"]},"13481":{"h":"מָלוּחַ","r":"M01505","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">מְלוּחִים</span>, <span dir=\"rtl\">מְלוּחִין</span>, v. <a href=\"#\" data-headword=\"מָלַח\">מָלַח</a>.</div>","alt":[]},"13482":{"h":"מַלּוּחַ","r":"M01506","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>a salt-plant, sea-purslane</i> (Halineus).—Pl. <span dir=\"rtl\">מַלּוּחִים</span>, <span dir=\"rtl\">מַלּוּחִין</span>. <span class=\"citation\">Kidd. 66ᵃ</span>. <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">כל מי … אוכל מ׳ וכ׳</span></div>","alt":[]},"13483":{"h":"מַלּוּחָא","r":"M01507","html":"<div class=\"sense\"> . <span class=\"citation\">Targ. Zeph. II, 9</span> (h. text <a href=\"#\" data-headword=\"חָרוּל\">חָרוּל</a>).</div>","alt":[]},"13484":{"h":"מִלּוּט","r":"M01508","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִילּוּט\">מִילּוּט</a></div>","alt":[]},"13485":{"h":"מְלוֹטוֹמְיָא","r":"M01509","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִילוֹטוֹמְיָא\">מִילוֹטוֹמְיָא</a></div>","alt":[]},"13486":{"h":"מִלּוּי","r":"M01510","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִילּוּי\">מִילּוּי</a></div>","alt":[]},"13487":{"h":"מְלוֹיְתָא","r":"M01511","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a>) <i>place for drawing water, well</i>. <span class=\"citation\">Lev. R. s. 21</span> <span dir=\"rtl\">ויתיב ליה על מְלוֹיַתְהָן דנשיא</span> sat down by the place where the women draw water; Pesik. Aḥăré, p. 176ᵇ; <span class=\"citation\">Yalk. Lev. 571</span> <span dir=\"rtl\">מְלַתְהוֹן</span>; (<span class=\"citation\">Keth. 62ᵇ</span> <span dir=\"rtl\">אגודא דנהרא</span>).</div>","alt":[]},"13488":{"h":"מְלַוִּיתָא","r":"M01512","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְלַוִּויתָא\">מְלַוִּויתָא</a></div>","alt":[]},"13489":{"h":"מַלּוּךְ","r":"M01513","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Malluch</i>, an Amora. <span class=\"citation\">Ḥull. 49ᵃ</span> <span dir=\"rtl\">מ׳ ערבאה וכ׳</span> you quote M. the Arabian, but he said &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אתריה דר׳ מ׳</span> the home of R. M. (in Arabia). <span class=\"citation\">Y. Succ. III, beg. 53ᶜ</span>. Y. B. Bath. 16ᵃ top; a. fr.</div>","alt":[]},"13490":{"h":"מָלוֹכָא","r":"M01514","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְלִיכָא\">מְלִיכָא</a></div>","alt":[]},"13491":{"h":"מְלוּכָה","r":"M01515","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>rulership, office</i>. <span class=\"citation\">Midr. Prov. ch. XXI</span> <span dir=\"rtl\">בו&quot;ד עולה למ׳ וכ׳</span> when a human being rises to rulership, he is in the hands of the Lord; <span class=\"citation\">Yalk. ib. 959</span>. <span class=\"citation\">Sabb. 56ᵇ</span> <span dir=\"rtl\">יחלקו את המ׳</span> shall divide the rulership between themselves. <span class=\"citation\">Num. R. s. 3</span> <span dir=\"rtl\">בעלי מ׳</span> rulers; a. e.</div>","alt":[]},"13492":{"h":"מִלּוּל","r":"M01516","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"מִלְכָנָא\">מִילּ׳</a>.</div>","alt":["מִלּוּלָא"]},"13493":{"h":"מָלוֹן","r":"M01517","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>lodging</i>. <span class=\"citation\">Snh. 95ᵇ</span> <span dir=\"rtl\">צדיק … לבית מְלוֹנִי</span> this righteous man (Jacob) has come to my lodging place; <span class=\"citation\">Ḥull. 91ᵇ</span>, v. <a href=\"#\" data-headword=\"לִינָה\">לִינָה</a>. <span class=\"citation\">Midr. Prov. ch. IX</span> <span dir=\"rtl\">שנמצא לך מ׳ טוב וכ׳</span> a beautiful lodging has been offered thee in the hour of thy death; a. fr.</div>","alt":[]},"13494":{"h":"מִלּוּסָא","r":"M01518","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"מִלֵּיסָא\">מִלֵּיסָא</a></div>","alt":[]},"13495":{"h":"מָלוֹשׁ","r":"M01519","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"לוּשׁ\">לוּשׁ</a>) <i>kneading trough</i>. <span class=\"citation\">Y. Gitt. VIII, 49ᵇ</span> bot.</div>","alt":[]},"13496":{"h":"מָלַח","r":"M01520","html":"<div class=\"sense\"><i>to salt, brine</i>; esp. (in ritual law) <i>to strew salt on raw meat</i> to resorb its blood. <span class=\"citation\">Midd. V, 3</span> <span dir=\"rtl\">היו מוֹלְחִין עורות וכ׳</span> they put salt on the hides of sacrifices.—<span class=\"citation\">Ḥull. 113ᵃ</span> <span dir=\"rtl\">אלא א&quot;כ מוֹלְחוֹ יפה יפה וכ׳</span> unless one salts it carefully and washes it thoroughly. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מדיח ומוֹלֵחַ וכ׳</span> one must first wash the meat, then salt it and again wash it. <span class=\"citation\">B. Bath. 74ᵇ</span> <span dir=\"rtl\">ומְלָחָהּ לצדיקים וכ׳</span> and preserved it in salt for the benefit of the righteous &amp;c. Ḥull. l. c. <span dir=\"rtl\">דג טהור שמְלָחוֹ וכ׳</span> a clean fish which was salted together with an unclean one; a. fr.—Part. pass. <a href=\"#\" data-headword=\"מָלוּחַ\">מָלוּחַ</a> (v. <a href=\"#\" data-headword=\"מְלִיחַ\">מְלִיחַ</a>); pl. <span dir=\"rtl\">מְלוּחִים</span>, <span dir=\"rtl\">מְלוּחִין</span>. Ib. <span dir=\"rtl\">שניהם מ׳</span> both were salted, opp. <a href=\"#\" data-headword=\"תָּפֵל\">תָּפֵל</a>. <span class=\"citation\">Yalk. Ps. 887</span> <a href=\"#\" data-headword=\"מ׳\">מ׳</a> salty secretions.—<span class=\"citation\">Y. Taan. IV, 69ᵇ</span> top <span dir=\"rtl\">מיני מ׳</span> various kinds of salted food. <span class=\"citation\">Y. Sabb. I, 3ᶜ</span> bot. <span dir=\"rtl\">מְלוּחֵיהֶן</span> brines prepared by gentiles; a. fr.</div><div class=\"sense\"><b>Hof. הוּמְלָח  הָמְלַח</b> <div class=\"sense\"><i>to be strewn with salt</i>. Sifra Vayikra, N’dab., Par. 9, ch. XI <span dir=\"rtl\">שלא הוּמְלְחָה</span> no salt had been put on it.</div></div><div class=\"sense\"><b>Pu. מוּלָּח</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"מָלוֹשׁ\">same</a>. Part. <span dir=\"rtl\">מְמוּלָּח</span> <i>salted</i>, trnsf. <i>bright</i>. <span class=\"citation\">Kidd. 29ᵇ</span> <span dir=\"rtl\">אם היה בנו זריז וממ׳</span> (Var. <span dir=\"rtl\">וממולא</span>) if his son is eager to learn and bright; [our w. missing in <span class=\"citation\">Tosef. Bekh. VI, 10</span>).</div></div>","alt":[]},"13497":{"h":"מְלַח I","r":"M01521","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Lev. II, 13</span>. <span class=\"citation\">Targ. Y. Gen. XXXI, 19</span>.—<span class=\"citation\">Sabb. 75ᵇ</span> <span dir=\"rtl\">האי מאן דמ׳ בשרא וכ׳</span> he who salts raw meat (on the Sabbath) &amp;c. <span class=\"citation\">Ḥull. 113ᵃ</span> <span dir=\"rtl\">מ׳ ליה גרמא גרמא</span> salted each piece separately. <span class=\"citation\">B. Bath. 74ᵇ</span> <span dir=\"rtl\">לִימְלְחָהּ לנקבה</span> let him preserve in salt the female (Behemoth); a. fr.—Part. pass. <a href=\"#\" data-headword=\"מְלִיחַ\">מְלִיחַ</a>, <a href=\"#\" data-headword=\"מְלִיחָא\">מְלִיחָא</a>, pl. <span dir=\"rtl\">מְלִיחֵי</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כוורא מ׳ מעלי</span> fish in salt is good; <span dir=\"rtl\">בשרא מ׳ וכ׳</span> meat in salt is not.—Ib. <span dir=\"rtl\">ציפרי מ׳</span> fowls in salt; a. fr.—V. <a href=\"#\" data-headword=\"מְלִיחָא\">מְלִיחָא</a>.</div><div class=\"sense\"><b>Ithpe. אִתְמְלַח  אִימְּלַח</b> <div class=\"sense\"><i>to be strewn with salt, be salted</i>. <span class=\"citation\">Targ. Ez. XVI, 4</span>.—<span class=\"citation\">Ḥull. 112ᵇ</span>. <span class=\"citation\">Ib. 97ᵇ</span> <span dir=\"rtl\">אִימְּלִיחוּ וכ׳</span> were (ritually) salted … with the nervus ischiadicus left therein; a. fr.</div></div>","alt":[]},"13498":{"h":"מְלַח II","r":"M01522","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מַלָּח\">מַלָּח</a>) <i>to row</i>; <i>to balance</i>. <span class=\"citation\">Keth. 85ᵃ</span> <span dir=\"rtl\">מְמַלַּח מַלּוּחֵי</span> (not <span dir=\"rtl\">מימלח</span>) rowed the boat (as an act of possession). <span class=\"citation\">B. Kam. 117ᵇ</span> <span dir=\"rtl\">מ׳ ביה חד מינייהו</span> (Alf.) one of them tried to keep the boat in balance (against the ass that threatened to upset it); [ed. <span dir=\"rtl\">מַ׳ ליה לחמרא</span> (Var. <a href=\"#\" data-headword=\"מָלֵא I\">מלא</a>, v. Rabb. D. S. a. l. note 90) he tried to counterbalance the ass].</div>","alt":["מַלֵּחַ"]},"13499":{"h":"מֶלַח","r":"M01523","html":"<div class=\"sense\"> c. (b. h.;  [<i>brittle</i>,] <i>salt</i>. <span class=\"citation\">Ker. 6ᵃ</span>; <span class=\"citation\">B. Bath. 20ᵇ</span> <span dir=\"rtl\">מ׳ סדומית</span> (sub. <a href=\"#\" data-headword=\"אֶרֶץ\">ארץ</a>) sea-salt, v. <a href=\"#\" data-headword=\"אִסְתְּרוֹקָנִית\">אִסְתְּרוֹקָנִית</a>. <span class=\"citation\">Ḥull. 112ᵃ</span> <span dir=\"rtl\">נאכל מחמת מִלְחוֹ</span> is eaten on account of (with) the salt it has absorbed. <span class=\"citation\">Keth. 66ᵇ</span> (prov.) <span dir=\"rtl\">מ׳ ממון חֶסֶר וא&quot;ל חסד</span> the salt (means of preservation) of wealth is its diminution (by charitable deeds), and some say <i>ḥesed</i> (benevolence). <span class=\"citation\">Gen. R. s. 51</span> <span dir=\"rtl\">חטאה במ׳</span> she (Lot’s wife) sinned through salt; <span dir=\"rtl\">הולכת … תנו לי מ׳ מ׳</span> she went to all her neighbors and said, give me salt for we have guests; a. fr.</div>","alt":[]},"13500":{"h":"מֶלַח ²","r":"M01524","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Lev. II, 13</span> <a href=\"#\" data-headword=\"מְלַח I\">מַלַח</a> constr. ed. Berl. (Var. <span dir=\"rtl\">מָ׳</span>, <a href=\"#\" data-headword=\"מָנִיכָא\">מְ׳</a>, v. Berl. Targ. O. II, p. 32; Y. <span dir=\"rtl\">מֶ׳</span>). <span class=\"citation\">Targ. II Chr. XIII, 5</span>. <span class=\"citation\">Targ. Y. Gen. XIX, 26</span> (v. <span class=\"citation\">Gen. R. s. 51</span> quot. in <a href=\"#\" data-headword=\"מֶלַח\">preced.</a>); a. fr.—<span class=\"citation\">Kidd. 62ᵃ</span>; <span class=\"citation\">Ḥull. 113ᵃ</span>, v. <a href=\"#\" data-headword=\"גְּלַלְנִיתָא\">גְּלַלְנִיתָא</a>. <span class=\"citation\">Bekh. 8ᵇ</span> <span dir=\"rtl\">מ׳ כי סרי וכ׳</span> when salt becomes unsavory, wherewith do they salt it? <span class=\"citation\">B. Bath. 74ᵇ</span> <span dir=\"rtl\">מִלְחָהּ מעלי</span> (differ. vers. in Ms. M., v. Rabb. D. S. a. l. note) as to the female (Behemoth), its brine is more savory. <span class=\"citation\">Yeb. 63ᵃ</span>, v. <a href=\"#\" data-headword=\"חֲפוּרָה ²\"><span dir=\"rtl\">חֲפוּרָה</span> II</a>; a. fr.—Pl. <span dir=\"rtl\">מִלְחֵי</span>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a>. <span class=\"citation\">Pes. 8ᵃ</span> <a href=\"#\" data-headword=\"מְשָׁכָא\">בי מ׳</a> salt-store. <span class=\"citation\">Ab. Zar. 33ᵃ</span> <span dir=\"rtl\">שדא חמרא לבי מ׳ דישראל</span> poured wine into a Jew’s salt-store (Rashi: a vessel filled with salt).</div>","alt":["מְלַח","מִלְחָא","מִי׳"]},"13501":{"h":"מַלָּח","r":"M01525","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> cmp. meaning of ἅλς a. <i>mariner, sailor</i>. <span class=\"citation\">Koh. R. to IX, 8</span>.</div>","alt":[]},"13502":{"h":"מַלָּחָא","r":"M01526","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"מַלָּח\">same</a>.—Pl. <span dir=\"rtl\">מַלָּחֵי</span>. <span class=\"citation\">Gitt. 73ᵃ</span>, v. <a href=\"#\" data-headword=\"אֲגַר II\"><span dir=\"rtl\">אֲגַר</span> II</a>. <span class=\"citation\">Taan. 24ᵇ</span> <span dir=\"rtl\">חזאי מלאכי דאידמו למ׳ וכ׳</span> (differ. vers. in Ms. M.; v. Rabb. D. S. a. l. note) I saw angels disguised as boatmen who brought sand and loaded the ships.</div><div class=\"sense\"><b>—2)</b> <i>dealer in sailors’ outfits</i>. <span class=\"citation\">Y. B. Mets. IV, end, 9ᵈ</span>, v. <a href=\"#\" data-headword=\"סַרְדּוּתָא\">סַרְדּוּתָא</a>.</div>","alt":[]},"13503":{"h":"מִלְחָא","r":"M01527","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֶלַח\">מֶלַח</a> ch.</div>","alt":[]},"13504":{"h":"מַלְחָא","r":"M01528","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Tower of Malḥa</i>, near Caesaraea (v. Hildesh. Beitr. p. 9). <span class=\"citation\">Y. Dem. II, 22ᶜ</span></div>","alt":["מִגְּדַּל מ׳"]},"13505":{"h":"מִלְחַיָּיא","r":"M01529","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Milḥaya</i>, native place of R. José, prob. in Galilee (v. Hildesh. Beitr. p. 9; Neub. Géogr. p. 269). <span class=\"citation\">Y. Ab. Zar. II, 41ᶜ</span> top. <span class=\"citation\">Gen. R. s. 42</span>. <span class=\"citation\">Lev. R. s. 26</span>. <span class=\"citation\">Lam. R. to I, 9</span>; <span class=\"citation\">Yalk. Is. 302</span> <span dir=\"rtl\">יוסף ממלי</span> (corr. acc.).</div>","alt":["מִלְחַיָּא"]},"13506":{"h":"מִלְחָמָה","r":"M01530","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>war, contest</i>. <span class=\"citation\">Sot. VIII, 1</span>, a. fr. <span dir=\"rtl\">משוח מ׳</span> chaplain of the army (<span class=\"citation\">Deut. XX, 2</span>), v. <a href=\"#\" data-headword=\"מָשַׁח I\"><span dir=\"rtl\">מָשַׁח</span> I</a>. Ib. 7 <span dir=\"rtl\">מִלְחֶמֶת הרשות</span> (Bab. ed. 44ᵇ, <i>pl.</i>) secular (political) warfare; <span dir=\"rtl\">מ׳ מצוה</span> a war for religious causes; <span dir=\"rtl\">מ׳ חובה וכ׳</span> a war of duty. Ib. 44ᵇ <span dir=\"rtl\">מ׳ יהושע וכ׳</span> the war of conquest under Joshua, all agree, is a war of duty &amp;c.—<span class=\"citation\">Meg. 15ᵇ</span> <span dir=\"rtl\">מִלְחַמְתָּהּ של תורה</span> disputes about the Law; a. fr.—<i>Pl.</i> <span dir=\"rtl\">מִלְחָמוֹת</span>. Sot. l. c. <span dir=\"rtl\">מִלְחֲמוֹת בית דוד לרווחה</span> the wars of the house of David for extending the dominion. <span class=\"citation\">M. Kat. 25ᵇ</span> (in a eulogy) <span dir=\"rtl\">גזע … ועמו ספר מ׳</span> an offspring of worthies came up from Babylonia and with him came the book of wars (allegorically for <i>knowledge of the Law;</i> oth. interpret. <i>R. Hamnuna</i> who came with Rabbah). <span class=\"citation\">Snh. 97ᵃ</span> <span dir=\"rtl\">בשביעית מ׳</span> in the seventh Messianic year there will be wars; a. fr.</div>","alt":[]},"13507":{"h":"מְלֶחֶת","r":"M01531","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מֶלַח\">מֶלַח</a>) <i>saline atmosphere, corrosion produced by saline influences.</i> Ohol. III, 7 <span dir=\"rtl\">חור … שאכלתו מ׳</span> a cave formed through saline corrosion.</div>","alt":[]},"13508":{"h":"מִלְחֲתָא","r":"M01532","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(<a href=\"#\" data-headword=\"מְלֶחֶת\">preced.</a>) <i>salt deposit</i> in a cavity in which sea-water was allowed to evaporate. <span class=\"citation\">Sabb. 66ᵇ</span>. <span class=\"citation\">Ib. 73ᵇ</span>, v. <a href=\"#\" data-headword=\"כְּנַף I\"><span dir=\"rtl\">כְּנַף</span> I</a>.</div>","alt":[]},"13509":{"h":"מָלַט","r":"M01533","html":"<div class=\"sense\"> (b. h.) [<i>to stand forth, project</i> (cmp. <a href=\"#\" data-headword=\"בָּלַט\">בָּלַט</a>),] <i>to escape</i>.</div><div class=\"sense\"><b>Pi. מִלֵּט</b> <div class=\"sense\"><i>to rescue</i>. <span class=\"citation\">Midr. Till. to Ps. XLI</span> <span dir=\"rtl\">ביום רעה אֲמַלֶּטְךָ</span> on the day of evil I shall save thee. <span class=\"citation\">Taan. 23ᵃ</span> <span dir=\"rtl\">מִילַּטְתּוֹ בתפלתךָ</span> thou hast saved it (the generation) through thy prayer. <span class=\"citation\">Yalk. Ps. 777</span> מיכל מְמַלֶּטֶת וכ׳ Michael helped David to escape from within and Jonathan from without; a. e.</div></div><div class=\"sense\"><b>Nif. נִמְלָט</b> <div class=\"sense\"><i>to be saved, to escape</i>. Esth. R. introd. <span dir=\"rtl\">נח ראש לנִמְלָטִים</span> Noah is the first of those saved (mentioned in the Bible). <span class=\"citation\">Koh. R. to IX, 15</span> <span dir=\"rtl\">כל השומע ליצר טוב נ׳</span> whosoever listens to the suggestions of his good inclination will be saved; a. e.</div></div><div class=\"sense\"><b>Hithpa. הִתְמַלֵּט</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"מִלְחֲתָא\">same</a>. <span class=\"citation\">Yalk. Deut. 854</span> <span dir=\"rtl\">ואתם מִתְמַלְּטִים וכ׳</span></div></div>","alt":[]},"13510":{"h":"מְלַט","r":"M01534","html":"<div class=\"sense\"><i>Ithpe.</i> אִתְמְלִיט <i>to be saved</i>. <span class=\"citation\">Targ. Prov. XIX, 5</span> <span dir=\"rtl\">נִתְמְלִיט</span> (ed. Wil. <a href=\"#\" data-headword=\"מָעַט\">נִתְמַלֵט</a>; Ms. <span dir=\"rtl\">נתפליט</span>).</div>","alt":[]},"13511":{"h":"מֶלֶט","r":"M01535","html":"<div class=\"sense\"> m. (b. h.), pl. <span dir=\"rtl\">מִלְטִין</span>, v. <a href=\"#\" data-headword=\"מַלְטֵט\">מַלְטֵט</a></div>","alt":[]},"13512":{"h":"מלטוכים","r":"M01536","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִילוֹטוֹמְיָא\">מִילוֹטוֹמְיָא</a></div>","alt":[]},"13513":{"h":"מלטומיא","r":"M01537","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"לָטוֹמְיָא\">לָטוֹמְיָא</a></div>","alt":[]},"13514":{"h":"מלטוס","r":"M01538","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַלְטֵט\">next w.</a></div>","alt":[]},"13515":{"h":"מַלְטֵט","r":"M01539","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מֶלֶט\">מֶלֶט</a>, fr. <a href=\"#\" data-headword=\"לוֹט I\">לוט</a> or <a href=\"#\" data-headword=\"לְטַט\">לטט</a> <i>to wrap, cover</i>; cmp. Syr. <span dir=\"rtl\">מלט</span> P. Sm. 2136) <i>frame</i> or <i>casing</i> around the beam-rest in the wall (corresp. to <a href=\"#\" data-headword=\"מַלְבֵּן\">מַלְבֵּן</a>).—Pl. <span dir=\"rtl\">מַלְטֵטִין</span>. <span class=\"citation\">B. Kam. 67ᵃ</span> (expl. <span dir=\"rtl\">צלעות</span>, <span class=\"citation\">Ez. XLI, 26</span>) <a href=\"#\" data-headword=\"מ׳\">מ׳</a> (Ms. M. <span dir=\"rtl\">מלטוסין</span>; Ms. H. <span dir=\"rtl\">מלוטסין</span>, Ms. R. <span dir=\"rtl\">מִלְטִין</span>), v. <a href=\"#\" data-headword=\"*הִימְלְטָא\">הִימְלְטָא</a>.</div>","alt":[]},"13516":{"h":"מַלְטִיתָא","r":"M01540","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">מלט</span>; cmp. <a href=\"#\" data-headword=\"בּוּלְטִיתָא\">בּוּלְטִיתָא</a>) <i>crumbling, corrosion</i>. <span class=\"citation\">Targ. Prov. XII, 4</span>. <span class=\"citation\">Ib. XIV, 30</span> <a href=\"#\" data-headword=\"מַלְטִיתָא\">מִלְטֵיתָא</a> (Var. ed. Lag. <a href=\"#\" data-headword=\"ניטליתא\">ניטליתא</a>, cler. error). <span class=\"citation\">Targ. I Chr. XIV, 1</span>.</div>","alt":[]},"13517":{"h":"מלטמיא","r":"M01541","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִילוֹטוֹמְיָא\">מִילוֹטוֹמְיָא</a>, a. <a href=\"#\" data-headword=\"לָטוֹמְיָא\">לָטוֹמְיָא</a>.</div>","alt":["מלטמייא"]},"13518":{"h":"מַלֵּי","r":"M01542","html":"<div class=\"sense\"><i>to speak</i>, v. <a href=\"#\" data-headword=\"מְלַל II\"><span dir=\"rtl\">מְלַל</span> II</a>.</div>","alt":[]},"13519":{"h":"מְלֵי","r":"M01543","html":"<div class=\"sense\"><b>1)</b> <i>to be full</i>. <span class=\"citation\">Targ. Josh. III, 15</span>; a. fr.; v. <a href=\"#\" data-headword=\"מלו\">next art.</a> <span class=\"citation\">Ab. Zar. 28ᵃ</span> <span dir=\"rtl\">דלא מָלוּ תִילתא</span>, v. <a href=\"#\" data-headword=\"תִּילְתָּא\">תִּילְתָּא</a>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to fill</i>. <span class=\"citation\">Targ. Gen. I, 22</span>. <span class=\"citation\">Targ. Deut. VI, 11</span> (O. ed. Vienna <a href=\"#\" data-headword=\"מַלֵּי\">מַלֵּ׳</a> <i>Pa</i>.); a. fr.—Part. <a href=\"#\" data-headword=\"מְלֵי\">מָלֵי</a>; f. <a href=\"#\" data-headword=\"מַלְיָא\">מַלְּיָא</a>; pl. <span dir=\"rtl\">מָלָן</span>; <a href=\"#\" data-headword=\"מַלְיָאתָא\">מַלְיָאתָא</a>, <a href=\"#\" data-headword=\"מַלְיְיתָא\">מַלְיָיתָא</a>. Ib. O. XXIX, 10. <span class=\"citation\">Targ. Josh. IX, 21</span> (ed. Wil. <span dir=\"rtl\">מְלָן</span>). <span class=\"citation\">Targ. Gen. XXIV, 11</span>; a. fr.</div><div class=\"sense\"><b>Pa. מַלֵּי</b> <div class=\"sense\"><b>1)</b> <i>to fill</i>. <span class=\"citation\">Targ. Jer. XIII, 13</span>; a. fr.—<span class=\"citation\">Lev. R. s. 21</span> <span dir=\"rtl\">מַלּוֹי קולתיך</span> fill thy vessel; Pesik. Aḥăré, p. 176ᵇ; <span class=\"citation\">Yalk. Lev. 571</span> <span dir=\"rtl\">מלתי</span> (read: <a href=\"#\" data-headword=\"מְלָאי I\">מַלְּאִי</a>); <span class=\"citation\">Keth. 62ᵇ</span> <a href=\"#\" data-headword=\"מַלֵּי\">מַלִּי</a>. <span class=\"citation\">Ab. Zar. 29ᵃ</span> <span dir=\"rtl\">ומַלְּיֵיה מיא</span> and fill it with water. <span class=\"citation\">Taan. 29ᵃ</span>; <span class=\"citation\">Shebu. 10ᵃ</span>; <span class=\"citation\">Pes. 77ᵃ</span> <span dir=\"rtl\">תמוז … מַלּוּיֵי מַלְּיוּהָ</span> they made the Tammuz of that year a full month (of thirty days); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to complement, compensate, replace</i>. <span class=\"citation\">Targ. O. Gen. II, 21</span> <span dir=\"rtl\">ומַלִי</span> ed. Berl. (ed. Amst. <span dir=\"rtl\">ומְ׳</span>, corr. acc.).—<span class=\"citation\">B. Mets. 105ᵃ</span> <span dir=\"rtl\">טרח ומַלְּיֵיה</span> he took pains to make up for the loss. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">טרחת ומַלְּיָיתֵיה וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">למַלָּיוּתֵיה</span>) thou didst take pains to make up &amp;c.; a. e.—[</div><div class=\"sense\"><b>3)</b>  מ׳ על לבא <i>to comfort</i>. <span class=\"citation\">Targ. O. Gen. XXXIV, 3</span> ed. Berl. (v. Berl. Mass., p. 27); v., however, <span class=\"citation\">Kidd. 50ᵃ</span>, quot. s. v. <a href=\"#\" data-headword=\"מְלַל II\"><span dir=\"rtl\">מְלַל</span> II</a>.]</div></div><div class=\"sense\"><b>Ithpe. אִתְמְלִי</b> <div class=\"sense\"><i>to be filled, full</i>. <span class=\"citation\">Targ. Gen. VI, 13</span>. <span class=\"citation\">Targ. Ex. XL, 34</span> <span dir=\"rtl\">א׳ ית וכ׳</span> (<i>filled</i>); a. fr.</div></div>","alt":["מְלָא"]},"13520":{"h":"מלו","r":"M01544","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ḥall. I, 57ᵈ</span> <span dir=\"rtl\">מלי גאלה</span>, v. <a href=\"#\" data-headword=\"מְלִיגָאלָה\">מְליגָאלָה</a>.—<span class=\"citation\">Yalk. Is. 302</span> <span dir=\"rtl\">יוסף ממלי</span>, v. <a href=\"#\" data-headword=\"מִלְחַיָּיא\">מִלְחַיָּא</a>.</div>","alt":[]},"13521":{"h":"מְלִי","r":"M01545","html":"<div class=\"sense\"> c. ch. = h., <i>full</i>. <span class=\"citation\">Targ. Deut. XXXIII, 23</span> (Var. <a href=\"#\" data-headword=\"מְלִי\">מַלִי</a>, <a href=\"#\" data-headword=\"מַלֵּי\">מַלִּי</a>, <a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a>). <span class=\"citation\">Targ. Ruth I, 21</span>; a. fr.—<span class=\"citation\">Erub. 84ᵃ</span> <span dir=\"rtl\">כי מליא</span> when the pit is full of water; a. fr.—Pl. <span dir=\"rtl\">מְלַן</span>, <a href=\"#\" data-headword=\"מַלְיָיא\">מַלְיָין</a>. <span class=\"citation\">Targ. Deut. VI, 11</span>; a. fr.—[<span class=\"citation\">Targ. O. Deut. XXIII, 26</span> <span dir=\"rtl\">דמַלְיָן</span> ed. Berl. those ears which are full (ripe; oth. ed. <a href=\"#\" data-headword=\"מְלִילָא\">מְלִילָן</a>).]</div>","alt":["מַלְיָא","מַלְיָיא I"]},"13522":{"h":"מַלְיָא","r":"M01546","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְלִי\">preced.</a>) <i>fulness</i>. Pesik. Haḥod., p. 53ᵃ (ref. to <span class=\"citation\">Ps. LXXXIX, 38</span>) <span dir=\"rtl\">כהדין סיהרא על מ׳</span> like the moon growing to fulness. Ib.; <span class=\"citation\">Yalk. Ex. 190</span> <span dir=\"rtl\">הא סיהרא על מ׳</span> this (Solomon’s reign) is the full moon; Yalk. Chr. 1082; (<span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">מְלֵיאָתָהּ</span>).—Constr. <a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a> (= h. <a href=\"#\" data-headword=\"מְלֹא\">מְלֹא</a>) <i>the fill of, as much as</i>. <span class=\"citation\">Targ. Ex. IX, 8</span>. <span class=\"citation\">Targ. Ps. XCVI, 11</span>; a. fr.—<span class=\"citation\">Meg. 16ᵃ</span> <span dir=\"rtl\">מ׳ קומציה</span> a handful.—V. <a href=\"#\" data-headword=\"מְלוֹא\">מְלוֹא</a>.</div>","alt":["מַלְיָיא II"]},"13523":{"h":"מְלֵיאָה","r":"M01547","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>full</i>, v. <a href=\"#\" data-headword=\"מָלֵא I\">מָלֵא</a>.</div><div class=\"sense\"><b>—2)</b> <i>fulness, full growth</i>. Pesik. Haḥod., p. 53ᵃ (ref. to <span class=\"citation\">Ps. LXXXIX, 38</span>, v. <a href=\"#\" data-headword=\"מַלְיָא\">preced.</a>) <span dir=\"rtl\">אם זכיתם … למְלֵיאָתָהּ</span> if you will do good, you shall count (your historical records) by the nation’s growth to fulness, opp. <span dir=\"rtl\">פגם</span> decrease; <span class=\"citation\">Pesik. R. s. 15</span>, a. e., v. <a href=\"#\" data-headword=\"מַלְיָא\">preced.</a> <span class=\"citation\">Gen. R. s. 12</span> <span dir=\"rtl\">נבראו … על מְלֵיאָתָן</span> those things had been created in perfect condition. <span class=\"citation\">Gen. R. s. 14</span> <span dir=\"rtl\">על מְלֵיאָתָהּ על מְלֵיאָתוֹ</span> fully developed. <span class=\"citation\">Num. R. s. 12</span>; a. e.—<span class=\"citation\">Gitt. 70ᵃ</span> Ar., v. <a href=\"#\" data-headword=\"מִלּוּא\">מִלּוּא</a>.</div><div class=\"sense\"><b>—3)</b>  (<i>the priestly gifts from</i>) <i>the ripe or stored fruits</i>. <span class=\"citation\">Tem. 4ᵃ</span> (ref. to <span class=\"citation\">Ex. XXII, 28</span>) <span dir=\"rtl\">מ׳ זו ביכורים</span> <i>m’leah</i> means the first fruits; Mekh. Mishp. s. 19 <span dir=\"rtl\">אלו ביכורים הנטלין מהמ׳</span> that means the first fruits which are taken from the fulness (the stored fruits). Ib. <span dir=\"rtl\">בכורים שהם קרויין … ומ׳</span> first fruits which go by four names, <i>reshith</i> … and <i>m’leah</i>; <span class=\"citation\">Yalk. Ex. 351</span>.</div>","alt":["מְלֵאָה"]},"13524":{"h":"מליאדין","r":"M01548","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"כִּילְיָאדִין\">כִּילְיָאדִין</a>.</div>","alt":["מליארין"]},"13525":{"h":"מַלְיָאתָא","r":"M01549","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"><i>women drawing water</i>, v. <a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a>.</div>","alt":[]},"13526":{"h":"מְלִיגָאלָה","r":"M01550","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μελίγαλα, S.) <i>honey- and milk-cake</i>. Y. Ḥall. I, 57ᵈ, v. <a href=\"#\" data-headword=\"דּוּבְשָׁן\">דּוּבְשָׁן</a>.</div>","alt":[]},"13527":{"h":"מַלָּיוּתָא","r":"M01551","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a>) <i>filling, replacing</i>, v. <a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a><i>Pa</i>.</div>","alt":[]},"13528":{"h":"מְלִיחַ","r":"M01552","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָלַח\">מָלַח</a>) </div><div class=\"sense\"><b>1)</b> <i>preserved in salt, pickled</i>. <span class=\"citation\">Ḥull. 113ᵃ</span> <span dir=\"rtl\">(<span dir=\"rtl\">בשר</span>) <a href=\"#\" data-headword=\"מ׳\">מ׳</a></span> salted meat, opp. <a href=\"#\" data-headword=\"תָּפֵל\">תָּפֵל</a>. <span class=\"citation\">Ib. 97ᵇ</span>, a. fr. <span dir=\"rtl\">מ׳ … כרותח</span> what is preserved in salt, is ritually to be considered as if boiled or roasted; a. fr.—[Pl., v. <a href=\"#\" data-headword=\"מָלַח\">מָלַח</a>.]</div><div class=\"sense\"><b>—2)</b> <i>salted relish, dessert</i>. <span class=\"citation\">Ber. VI, 7</span>. <span class=\"citation\">Ib. 44ᵃ</span> כל סעודה שאין בה מ׳ וכ׳ Ms. M. (ed. <a href=\"#\" data-headword=\"מְלַח I\">מלח</a>, corr. acc.; v. Rabb. D. S. a. l. note) a meal without salted preserves is no meal.</div>","alt":[]},"13529":{"h":"מְלִיחָא","r":"M01553","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"מְלַח I\"><span dir=\"rtl\">מְלַח</span> I</a></div>","alt":[]},"13530":{"h":"מַלְיָיא","r":"M01554","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַלְיָא\">מַלְיָא</a></div>","alt":[]},"13531":{"h":"מַלְיְיתָא","r":"M01555","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַלְאֲתָא\">מַלְאֲתָא</a>.—<a href=\"#\" data-headword=\"מַלְיְיתָא\">מַלְיָיתָא</a>, v. <a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a>.</div>","alt":[]},"13532":{"h":"מְלִיךְ","r":"M01556","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְלַךְ\">מְלַךְ</a> a. <a href=\"#\" data-headword=\"מֶלֶךְ\">מֶלֶךְ</a> ch.</div>","alt":["מְלֵיךְ"]},"13533":{"h":"מְלִיכָא","r":"M01557","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְלַךְ\">מְלַךְ</a>) <i>counsellor</i>. <span class=\"citation\">Targ. II Sam. XV, 12</span> (ed. Lag. <a href=\"#\" data-headword=\"מָלוֹכָא\">מָלוֹכָא</a>; Levita <a href=\"#\" data-headword=\"מַלָּכָא\">מַלָּכָא</a>).</div>","alt":[]},"13534":{"h":"מַלִּילָא","r":"M01558","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַלָּלָא\">מַלָּלָא</a></div>","alt":[]},"13535":{"h":"מְלִילָא","r":"M01559","html":"<p class=\"morphology\">f.</p><div class=\"sense\">—Pl. <a href=\"#\" data-headword=\"מְלִילָא\">מְלִילָן</a>. <span class=\"citation\">Targ. O. Deut. XXIII, 26</span> (ed. Berl. <span dir=\"rtl\">דמַלְיָן</span>, v. <a href=\"#\" data-headword=\"מְלִי\">מְלִי</a>).</div>","alt":[]},"13536":{"h":"מְלִילָה","r":"M01560","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>ripe ear</i>, esp. <i>parched ear</i>.—Pl. <span dir=\"rtl\">מְלִילוֹת</span>. <span class=\"citation\">Maasr. IV, 5</span> <span dir=\"rtl\">המולל מ׳</span> he who rubs parched ears; <span class=\"citation\">Tosef. Bets. I, 20</span>. <span class=\"citation\">Tosef. Ter. III, 18</span> … <span dir=\"rtl\">הכניס שובלין … לעשותן מ׳</span> if one brought ears to his house with the intention of parching them.—<span class=\"citation\">Y. Pes. III, beg. 29ᵈ</span>, v. <a href=\"#\" data-headword=\"עָמִיל\">עָמִיל</a>. <span class=\"citation\">Pesik. R. s. 43</span>, a. e., v. <a href=\"#\" data-headword=\"קָמָה\">קָמָה</a>; a. fr.</div>","alt":[]},"13537":{"h":"מִלֵּיסָא","r":"M01561","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pʿales noun of <a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a>, cmp. <a href=\"#\" data-headword=\"מִילּוּסָא\">מִילּוּסָא</a>) [<i>water-pot</i> (cmp. ὑδρία),] <i>a cooking vessel</i>. <span class=\"citation\">Targ. I Sam. II, 14</span> (ed. Lag. <a href=\"#\" data-headword=\"מִילְסָא\">מִילֵּסָא</a>, Var. <span dir=\"rtl\">אִילְפֵיסָא</span>; h. text <span dir=\"rtl\">פרור</span>). <span class=\"citation\">Targ. Y. Num. XI, 8</span> מילסא Levita (ed. <a href=\"#\" data-headword=\"לאפוסיא\">לאפוסיא</a>, <a href=\"#\" data-headword=\"*לַפֶּדְיָא\">לפדיא</a>; h. text <span dir=\"rtl\">פרור</span>).—Pl. <span dir=\"rtl\">מִלּוּסַיָּא</span>, <a href=\"#\" data-headword=\"מִלְכָנָא\">מִילּ׳</a>. <span class=\"citation\">Targ. II Chr. XXXV, 13</span> (h. text <span dir=\"rtl\">צלחות</span>).</div>","alt":[]},"13538":{"h":"מַלֵּיף","r":"M01562","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">מְאַלֵּף</span>; <a href=\"#\" data-headword=\"אֲלַף I\">אֲלַף</a>) <i>teacher</i>. <span class=\"citation\">Targ. I Sam. XIX, 20</span>. <span class=\"citation\">Targ. Ez. III, 17</span>.—Pl. <a href=\"#\" data-headword=\"מלפין\">מַלְּפִין</a>. <span class=\"citation\">Targ. Jer. VI, 17</span>. <span class=\"citation\">Targ. Is. L, 4</span>; a. e.</div>","alt":["מַלֵּף"]},"13539":{"h":"מֵלִיץ","r":"M01563","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"לוּץ\">לוּץ</a></div>","alt":[]},"13540":{"h":"מְלִיצָה","r":"M01564","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>speech, argument, defence;</i> (in an evil sense) <i>sneer, scorn</i>. <span class=\"citation\">Midr. Prov. to I, 6</span> מ׳ זו התורה וכ׳ <i>m’litsah</i> (ib.) means the Law proper &amp;c., <span dir=\"rtl\">ולמה נקראת שמה מ̇ל̇יצ̇ה שהיא מ̇צ̇ל̇ת וכ׳</span> and why is it called <i>m</i>.? Because it saves those engaged in it from the judgment of Gehenna; <span dir=\"rtl\">למה נקראת שמה מ׳ שכל מי שמתלוצץ וכ׳</span> why is it called <i>m’litsah</i> (scoff-producing)? Because whoever desires to scoff, will be amply supplied with scoffing.</div><div class=\"sense\"><b>—2)</b> <i>metaphor</i>. <span class=\"citation\">Cant. R. to I, 1</span> <span dir=\"rtl\">יש להם מקרא … משל … מ׳</span> they find confirmation in plain Biblical prose, in proverbs, and in metaphors.</div>","alt":[]},"13541":{"h":"מְלִיקָה","r":"M01565","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָלַק\">מָלַק</a>) <i>pinching a bird’s head</i>. Sifra Vayikra, N’dab., ch. VIII, Par. 7; <span class=\"citation\">Zeb. 65ᵃ</span> <span dir=\"rtl\">מ׳ שקבע לה כהן</span> the pinching, for which function the Text appoints a priest; a. fr.</div>","alt":[]},"13542":{"h":"מלישות","r":"M01566","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Neg. IV, 10</span> ed. Zuck. <a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a> (oth. ed. <span dir=\"rtl\">המול׳</span>), read with R. S. to <span class=\"citation\">Neg. X, 10</span> <span dir=\"rtl\">התְּלִישׁוֹת</span>.</div>","alt":[]},"13543":{"h":"מַלֵּיתָא","r":"M01567","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְלֵי\">מְלֵי</a>) <i>filling up, complement</i>. <span class=\"citation\">B. Bath. 104ᵇ</span> top [read:] <span dir=\"rtl\">ואי איכא יתירא למ׳ דתשעה וכ׳</span> (v. Rabb. D. S. a. l. note 40) and if there is a surplus, it must go to make up the nine <i>ḳab</i></div>","alt":[]},"13544":{"h":"מַלְיְתָא","r":"M01568","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַלֵּיתָא\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>mound, rampart</i>. <span class=\"citation\">Targ. II Sam. V, 9</span>; <span class=\"citation\">Targ. I Kings IX, 24</span> (ed. Lag. <span dir=\"rtl\">מי׳</span>; h. text <a href=\"#\" data-headword=\"מִלּוּא\">מִלּוֹא</a>). <span class=\"citation\">Targ. II Sam. XX, 15</span> (h. text <span dir=\"rtl\">סללה</span>); a. e.—Pl. <a href=\"#\" data-headword=\"מַלְיְתָא\">מַלְיָתָא</a>, <span dir=\"rtl\">מִילְיָ׳</span>. <span class=\"citation\">Targ. Jer. XXXII, 24</span>.</div><div class=\"sense\"><b>—2)</b> <i>stuffing</i>. <span class=\"citation\">Pes. 74ᵃ</span>, v. <a href=\"#\" data-headword=\"מוּלְיְיתָא\">מוּלְיְיתָא</a>.</div>","alt":["מִלֵּיתָא","מִי׳","(מִלֵּתָא)"]},"13545":{"h":"*מַלָּךְ","r":"M01569","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"מַהֲלָךְ\">מַה לָךְ</a>) <i>what is it to thee?; of no practical value</i>. <span class=\"citation\">Sabb. 150ᵃ</span> sq. <span dir=\"rtl\">חשבונות של מ׳ ושל מה בכך</span> (Ms. M. <span dir=\"rtl\">מה לך</span>, v. Rabb. D. S. a. l. note) accounts of ‘what is it to thee?’ and of ‘what is in it?’, i.e. for no practical purpose. [Oth. opin., v. Ar.]</div>","alt":[]},"13546":{"h":"מָלַךְ","r":"M01570","html":"<div class=\"sense\"> (b. h.) [<i>to lead in council</i>,] <i>to preside</i>; <i>to officiate; to be ruler</i>. <span class=\"citation\">B. Bath. 164ᵇ</span> <span dir=\"rtl\">מ׳ שנה מונין לו שתים</span> when he has been in office one year, they date (in documents) ‘the second year’. <span class=\"citation\">Meg. 11ᵃ</span> (ref. to <span dir=\"rtl\">המֹלֵךְ</span>, <span class=\"citation\">Esth. I, 1</span>) <span dir=\"rtl\">מ׳ מעצמו</span> started a dynasty with himself (had no claims of succession). Ib. <span dir=\"rtl\">מָלְכוּ בכיפה</span>, v. <a href=\"#\" data-headword=\"כִּיפָּה\">כִּיפָּה</a>. <span class=\"citation\">Zeb. 118ᵇ</span> <span dir=\"rtl\">עשרה שנה שמ׳ וכ׳</span> ten years during which Samuel ruled alone, <span dir=\"rtl\">ושנה שמ׳ שאול וכ׳</span> and one year during which Saul and Samuel ruled conjointly; <span class=\"citation\">Tem. 15ᵃ</span>; a. fr.</div><div class=\"sense\"><b>Nif. נִמְלַךְ</b> <div class=\"sense\"> [<i>to be led</i>,] </div><div class=\"sense\"><b>1)</b> <i>to take council, to ask advice</i> or <i>permission</i>. <span class=\"citation\">Ber. 3ᵇ</span> <span dir=\"rtl\">נִמְלָכִין בסנהדרין</span> they ask the Sanhedrin for their confirmation. Ib. 4ᵃ <span dir=\"rtl\">כל מה … אני נ׳ במפיבשת וכ׳</span> in whatever I undertake, I consult the opinion of M., my teacher. Ib. 29ᵇ <span dir=\"rtl\">וכשאתה … הִמָּלֵךְ בקונך וצא</span> and when thou art about to go on a journey, take council of thy Maker (pray) and go out. <span class=\"citation\">B. Mets. 14ᵃ</span> <span dir=\"rtl\">צריך לִימָּלֵךְ</span> the scribe must ask for authorization (to insert in the contract); a. fr.</div><div class=\"sense\"><b>—2)</b>  [<i>to take council with one’s self</i>,] <i>to reconsider, change one’s mind.</i> <span class=\"citation\">Gitt. III, 1</span>. <span class=\"citation\">Dem. III, 2</span> <span dir=\"rtl\">הלוקח … ונ׳ להחזיר</span> if one buys vegetables …. and then decides to return (the goods). <span class=\"citation\">Ib. 3</span> <span dir=\"rtl\">נטלן לאוכלן ונ׳ להצניע</span> if he took them up to eat them and changed his mind (deciding) to keep them; a. fr.</div></div><div class=\"sense\"><b>Hif. הִמְלִיךְ</b> <div class=\"sense\"><i>to appoint</i> or <i>elect for rulership, to acknowledge the authority of</i>. <span class=\"citation\">Snh. 64ᵃ</span> <span dir=\"rtl\">שהִמְלִיכוּהוּ עליהם</span>, v. <a href=\"#\" data-headword=\"מוֹלֶךְ\">מוֹלֶךְ</a>. Y. Ned. IX, beg. 41ᵇ (ref. to <span class=\"citation\">Ps. LXXXI, 10</span>) <span dir=\"rtl\">זר שבקרבך אל תַּמְלִיכֵהוּ עליך</span> allow not the tyrant within thee (the evil inclination) to rule over thee. <span class=\"citation\">Ab. Zar. 18ᵃ</span> <span dir=\"rtl\">אומה זו מן השמים הִמְלִיכוּהָ</span> this (Roman) nation has been given the rulership by divine decree. <span class=\"citation\">R. Hash. 16ᵃ</span> <span dir=\"rtl\">אמרו לפני … מלכיות שתַּמְלִיכוּנִי עליכם</span> recite before me verses of homage (v. <a href=\"#\" data-headword=\"מַלְכוּת\">מַלְכוּת</a>), in order that you may declare me your ruler; a. fr.</div></div>","alt":[]},"13547":{"h":"מְלַךְ","r":"M01571","html":"<div class=\"sense\"><b>1)</b> <i>to rule</i>. <span class=\"citation\">Targ. Gen. XXXVII, 8</span>; a. fr.—Part. <a href=\"#\" data-headword=\"מְלִיךְ\">מָלִיךְ</a>. <span class=\"citation\">Targ. Jer. XXXIII, 21</span> (ed. Wil. <a href=\"#\" data-headword=\"מְלִיךְ\">מְלִיךְ</a>, corr. acc.); a. fr.—<span class=\"citation\">Ab. Zar. 10ᵃ</span> בעינא דיִמְלַךְ וכ׳ I desire that my son Severus be king after me; <span class=\"citation\">ib.</span> <span dir=\"rtl\">דיִמְלוֹךְ</span>.—<span class=\"citation\">Ber. 64ᵃ</span> מ׳ רבה Rabbah officiated (as teacher and judge); a. fr.</div><div class=\"sense\"><b>—2)</b>  (mostly <span dir=\"rtl\">מליך</span>) <i>to decide</i>. <span class=\"citation\">Targ. Is. XIV, 27</span>. <span class=\"citation\">Ib. XXIII, 8</span> (ed. Ven. <a href=\"#\" data-headword=\"מְלַךְ\">מַלִּיךְ</a>). <span class=\"citation\">Ib. 9</span> <span dir=\"rtl\">מִילְכָהּ</span> ed. Lag. (some ed. <span dir=\"rtl\">מלכא</span>, read: <a href=\"#\" data-headword=\"מַלְכָּה\">מִלְכָהּ</a>); a. fr.—Part. pass. <a href=\"#\" data-headword=\"מְלִיךְ\">מְלִיךְ</a>. <span class=\"citation\">Ib. XIV, 26</span>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to advise</i>. <span class=\"citation\">Targ. II Sam. XVII, 7</span>. <span class=\"citation\">Targ. I Kings I, 12</span>; a. fr.</div><div class=\"sense\"><b>Pa. מַלֵּיךְ</b> <div class=\"sense\"><b>1)</b> <i>to advise</i>. <span class=\"citation\">Targ. Job XXVI, 3</span>.</div><div class=\"sense\"><b>—2)</b> <i>to decide</i>, v. supra.</div></div><div class=\"sense\"><b>Af. אַמְלִיךְ</b> <div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"מָלַךְ\">preced.</a> = <a href=\"#\" data-headword=\"מָלַךְ\">preced.</a> <i>Hif.</i> <span class=\"citation\">Targ. I Kings III, 7</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to counsel, persuade</i>. <span class=\"citation\">Targ. Josh. XV, 18</span>. <span class=\"citation\">Targ. Y. Deut. XXX, 6</span>; a. e.—[<span class=\"citation\">Targ. Prov. VIII, 15</span> <span dir=\"rtl\">מַמְלְכִין</span> ed. Lag. <i>rule</i> (oth. ed. <span dir=\"rtl\">מלכין</span>).]</div></div><div class=\"sense\"><b>Ithpa. אִתְמַלֵּךְ</b> </div><div class=\"sense\"><b>Ithpe. אִתְמְלִיךְ  אִימְּלִיךְ</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"מְצִי I\">אִמְּ׳</a> = <a href=\"#\" data-headword=\"מָלַךְ\">preced.</a> <i>Nif.</i>—<span class=\"citation\">Targ. Is. XXXII, 7</span>; a. fr.—<span class=\"citation\">B. Bath. 4ᵃ</span> <span dir=\"rtl\">בתר דעבדין מִתְמַלְּכִין</span> do people ask for advice (or permission) after they have acted? <span class=\"citation\">Ber. 27ᵇ</span> <span dir=\"rtl\">אִימְּלִיךְ וכ׳</span> consult my family. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אזיל ואִמְּ׳ וכ׳</span> he went and consulted his wife. <span class=\"citation\">Ned. 54ᵃ</span> <span dir=\"rtl\">כל מילתא דצריך שליחא לאִמְּלוּכֵי וכ׳</span> any change of order for which the messenger has to ask special authorization, is heterogeneous (to the object of the original commission); <span dir=\"rtl\">כל מילתא דמִימְּלִיךְ שליח עלה וכ׳</span> a change for which the messenger asks for instructions is homogeneous. <span class=\"citation\">Sot. 43ᵇ</span> <span dir=\"rtl\">אי אימ׳ עלה</span> if he reconsiders his original disposal; a. fr.</div></div>","alt":["מְלֵיךְ"]},"13548":{"h":"מֶלֶךְ","r":"M01572","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מְלַךְ\">preced.</a>) <i>leader in council, chief, king</i>. <span class=\"citation\">Ber. 3ᵇ</span> <span dir=\"rtl\">אדוננו המ׳</span> our lord the king! <span class=\"citation\">Tosef. Snh. VIII, 5</span>, a. fr. <span dir=\"rtl\">מ׳ מלכי המלכים</span> the Most Supreme King (the Lord). <span class=\"citation\">Ib. IX, 8</span> <span dir=\"rtl\">אפי׳ מ׳ של מלכים</span> even a king of kings (great sovereign). <span class=\"citation\">Snh. 38ᵃ</span>, a. fr. <span dir=\"rtl\">מ׳ בו&quot;ד</span> (v. <a href=\"#\" data-headword=\"בָּשָׂר\">בָּשָׂר</a>) a human chief. <span class=\"citation\">Ab. Zar. 10ᵃ</span> <span dir=\"rtl\">אין מושיבין מ׳ בן מ׳</span> they (the Romans) do not allow the son of a king to succeed his father. <span class=\"citation\">Kerith. 5ᵇ</span> <span dir=\"rtl\">מ׳ ראשון</span> a first king, starter of a dynasty. <span class=\"citation\">Shebu. 6ᵇ</span> <span dir=\"rtl\">מַלְכֹּו של זה</span> this hyparch’s chief. <span class=\"citation\">Num. R. s. 18</span> משה מ׳ וכ׳ Moses has made himself the chief, and Aaron is high priest &amp;c.; a. v. fr.—Pl. <span dir=\"rtl\">מְלָכִים</span>. <span class=\"citation\">Hor. 12ᵃ</span> <span dir=\"rtl\">כיצד מושחין את המ׳ וכ׳</span> how are kings anointed? By drawing with the oil the outlines of a crown; <span class=\"citation\">Ker. 5ᵇ</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מַלְכֵי בית דוד</span> the kings of the house of David (southern kingdom); <span dir=\"rtl\">מ׳ ישראל</span> the kings of the northern kingdom; a. v. fr.—בַּת מְ׳ <i>Princess</i>, name of a demon afflicting the eye, also <i>a certain disorder of the eye</i>, v. <a href=\"#\" data-headword=\"בַּת I\"><span dir=\"rtl\">בַּת</span> I</a>. <span class=\"citation\">Sabb. 109ᵃ</span> (Var. <span dir=\"rtl\">בת חורין</span>, v. Rabb. D. S. a. l. note).—Pl. <span dir=\"rtl\">בנות מֶלֶךְ</span>. <span class=\"citation\">Tosef. B. Kam. IX, 27</span> <span dir=\"rtl\">יצאו בנות מ׳</span> the ‘princesses’ (humors of the eye) escaped (in consequence of a blow).</div>","alt":[]},"13549":{"h":"מֶלֶךְ ²","r":"M01573","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ps. XXIV, 7</span>; <span class=\"citation\">9</span>. <span class=\"citation\">Targ. Ex. I, 8</span>; a. fr.—<span class=\"citation\">Snh. 110ᵃ</span> <span dir=\"rtl\">איהו הוה מ׳</span> he (Moses) himself is chief. <span class=\"citation\">Y. Yeb. XVI, 15ᶜ</span>, v. <a href=\"#\" data-headword=\"אָרְסְקִינָס\">אָרְסְקִינָס</a>. <span class=\"citation\">Y. Ter. VIII, 46ᵇ</span> bot. <span dir=\"rtl\">אתעביד מ׳</span> he (Dioclet) became king; a. fr.—Pl. <span dir=\"rtl\">מַלְכֵין</span>, <a href=\"#\" data-headword=\"מַלְכִּיָּא\">מַלְכַיָּא</a>, <a href=\"#\" data-headword=\"*מִלְכָי\">מַלְכֵי</a>. <span class=\"citation\">Targ. Gen. XVII, 6</span>. <span class=\"citation\">Ib. XIV, 5</span>. <span class=\"citation\">Targ. Prov. VIII, 15</span>; a. fr.—<span class=\"citation\">Gitt. 62ᵃ</span> <span dir=\"rtl\">שלמא עלייכו מ׳</span> (to scholars) peace be with you, chiefs!—<span class=\"citation\">Shebu. 6ᵇ</span> <span dir=\"rtl\">תרי מ׳ וכ׳</span> two kings and two viceroys (hyparchs); a. fr.</div>","alt":["מְלֵיךְ","מַלְכָּא"]},"13550":{"h":"מֵלַךְ","r":"M01574","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מֶלֶךְ ²\">preced.</a> wds.) <i>counsel, advice</i>. <span class=\"citation\">Targ. Is. III, 3</span>. <span class=\"citation\">Targ. Y. Deut. VIII, 18</span> (O. <a href=\"#\" data-headword=\"עֵצָה I\">עצה</a>; h. text <a href=\"#\" data-headword=\"כֹּחַ\">כֹּחַ</a>); a. fr.—Pl. <span dir=\"rtl\">מִלְכִין</span>, <a href=\"#\" data-headword=\"מִלְחַיָּיא\">מִלְכַיָּא</a>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a>. <span class=\"citation\">Targ. Is. XXV, 1</span>. <span class=\"citation\">Targ. Job XII, 17</span> (not <span dir=\"rtl\">מַ׳</span>). <span class=\"citation\">Targ. Hos. X, 6</span>; a. e.</div>","alt":["מֵי׳","מִלְכָא","מִי׳"]},"13551":{"h":"מַלָּכָא","r":"M01575","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְלִיכָא\">מְלִיכָא</a></div>","alt":[]},"13552":{"h":"מַלְכָּה","r":"M01576","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>queen, king’s wife</i>. <span class=\"citation\">B. Bath. 15ᵇ</span> <span dir=\"rtl\">כל האומר מַלְכַּת שבא וכ׳</span> whoever says <i>malkath Sheba</i> (<span class=\"citation\">I Kings X, 1</span>) means a woman is mistaken; … it means the kingdom (<span dir=\"rtl\">מַלְכֻת</span>) of Sheba. <span class=\"citation\">Sabb. 119ᵃ</span> <span dir=\"rtl\">שבת המ׳</span> the queen Sabbath; a. fr.</div>","alt":[]},"13553":{"h":"מִלְכוּ","r":"M01577","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְלַךְ\">מְלַךְ</a>) <i>consultation</i>. <span class=\"citation\">Gen. R. s. 8</span>; <span class=\"citation\">Yalk. ib. 13</span> (ref. to <span class=\"citation\">Gen. I, 26</span>) <span dir=\"rtl\">לית הכא מ׳</span> this does not mean holding council (with the ministering angels).</div>","alt":[]},"13554":{"h":"מַלְכוּ","r":"M01578","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַלְכוּתָא\">מַלְכוּתָא</a></div>","alt":[]},"13555":{"h":"מַלְכוּת","r":"M01579","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>kingdom, government; office.</i> <span class=\"citation\">Ab. III, 5</span> <span dir=\"rtl\">עול מ׳</span> the yoke of (secular) government (burden of office). <span class=\"citation\">Ber. 13ᵇ</span>, a. fr. <span dir=\"rtl\">עול מ׳ שמים</span> the yoke of (submission to) divine government. <span class=\"citation\">Gitt. VIII, 5</span>, v. <a href=\"#\" data-headword=\"הוּגָּן\">הוּגָּן</a>. <span class=\"citation\">Ber. 48ᵇ</span>, a. e. <span dir=\"rtl\">אין מ׳ נוגעת וכ׳</span>, v. <a href=\"#\" data-headword=\"חָבֵר\">חָבֵר</a>. <span class=\"citation\">Sot. 11ᵇ</span> (ref. to <span dir=\"rtl\">בתים</span>, <span class=\"citation\">Ex. I, 21</span>) <span dir=\"rtl\">בתי מ׳</span> dynasties.—<span dir=\"rtl\">מרד במ׳</span> to rebel against the government, to commit treason. <span class=\"citation\">Snh. 49ᵃ</span>; a. fr.—<span dir=\"rtl\">מ׳ הָרִשְׁעָה</span> the wicked government (Rome). <span class=\"citation\">Ber. 61ᵇ</span> Ms. M. a. early ed. (later ed. <span dir=\"rtl\">יון</span>); a. fr.—<span dir=\"rtl\">קרוב למ׳</span> connected with the court (influential). <span class=\"citation\">B. Kam. 83ᵃ</span>. <span class=\"citation\">Gitt. 14ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">מַלְכִיּוֹת</span>. <span class=\"citation\">Gen. R. s. 44</span> <span dir=\"rtl\">ארבעה … גיהינם ומ׳ וכ׳</span> the Lord showed him (Abraham) four things: future punishment, (persecution by foreign) governments &amp;c.; Mekh. Yithro, s. 9 <span dir=\"rtl\">ארבע מ׳ וכ׳</span> the four empires which were destined to subject his descendants. <span class=\"citation\">Ber. 34ᵇ</span>, a. e. <span dir=\"rtl\">אין בין … אלא שעבוד מ׳ מלבד</span> there will be no difference (in the conditions of life) between the present and the Messianic days except (the delivery from) the oppression of governments; a. fr.</div><div class=\"sense\"><b>—2)</b>  (in liturgy) <i>a benediction invoking God as king</i> <span dir=\"rtl\">(אלהינו מלך העולם</span>). Ib. 12ᵃ <span dir=\"rtl\">כל ברכה שאין בה מ׳ וכ׳</span> a benediction in which the word ‘king’ does not occur, is no benediction.—Pl. <span dir=\"rtl\">מַלְכִיּוֹת</span> <i>the references to the divine kingdom in the Musaf of the New Year’s Day, the section called Malkhiyoth</i>. <span class=\"citation\">R. Hash. IV, 5</span>. <span class=\"citation\">Ib. 6</span> <span dir=\"rtl\">עשרה מ׳</span> the recitation of ten Biblical verses referring to the divine government. Ib. (32ᵇ) <span dir=\"rtl\">זכרונות מ׳ וכ׳</span> Ms. M. (ed. sing.), v. <a href=\"#\" data-headword=\"זִכָּרוֹן\">זִכָּרוֹן</a>. Y. ib. III, 58ᵈ; a. e.</div>","alt":[]},"13556":{"h":"מַלְכוּתָא","r":"M01580","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מַלְכוּת\">same</a>, <i>kingdom, rulership</i>. <span class=\"citation\">Targ. Ob. I, 21</span>. <span class=\"citation\">Targ. Jud. IX, 9</span>; a. fr.—<span class=\"citation\">B. Kam. 113ᵃ</span>, v. <a href=\"#\" data-headword=\"דִּין ²\">דִּינָא</a>. <span class=\"citation\">Ber. 58ᵃ</span> <span dir=\"rtl\">מ׳ דארעא כעין מ׳ דרקיעא</span> royal majesty on earth is similar to that of heaven. <span class=\"citation\">Ab. Zar. 10ᵇ</span> <span dir=\"rtl\">חשיבי דמ׳</span> the notables of the (Roman) empire. <span class=\"citation\">Tam. 32ᵃ</span> <span dir=\"rtl\">יסני מלכו וכ׳</span> let him shun government and governor; <span dir=\"rtl\">ירחם מ׳ וכ׳</span> let him be a friend of government and ruler and (use his influence to) do good to mankind. <span class=\"citation\">Pes. 113ᵃ</span> <span dir=\"rtl\">מַלְכוּתַיְיהוּ אחורי וכ׳</span> their rulership dwells behind their ears, i.e. they may rise to power at some future time. <span class=\"citation\">Ab. Zar. 2ᵇ</span> <span dir=\"rtl\">משכי במַלְכוּתַיְיהוּ עד וכ׳</span> (or <span dir=\"rtl\">מַלְכְוָ׳</span>, <i>Pl.</i>) they will continue in power until the Messiah comes; a. fr.—Pl. <span dir=\"rtl\">מַלְכְוָן</span>, <a href=\"#\" data-headword=\"מַלְכוּתָא\">מַלְכְוָתָא</a>, <span dir=\"rtl\">מַלְכְוָו׳</span>. <span class=\"citation\">Targ. Gen. XXV, 23</span>. <span class=\"citation\">Targ. Deut. III, 21</span>; a. fr.</div>","alt":["מַלְכוּ"]},"13557":{"h":"*מִלְכָי","r":"M01581","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"מְלַךְ\">מְלַךְ</a>, cmp. <a href=\"#\" data-headword=\"מִלְכוּ\">מִלְכוּ</a>) <i>deliberation, vacillation</i>. <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">פסוק הדא מלכי לבך</span> cut (end) this deliberation of thy heart (decide); Pesik. Haḥod. p. 43ᵃ <span dir=\"rtl\">מילניה מן לבך</span> (read: <span dir=\"rtl\">מילכיא</span>, and insert <span dir=\"rtl\">פסוק</span>); <span class=\"citation\">Yalk. Gen. 77</span> <span dir=\"rtl\">קטע הדין מלני מלבך</span> (read with Matt. K. to <span class=\"citation\">Gen. s. 44</span>: <span dir=\"rtl\">מלכיא</span>); <span class=\"citation\">Gen. R. s. 44</span> <span dir=\"rtl\">קטע הדין מוטניא מן כדו</span> (ed. Wil. <a href=\"#\" data-headword=\"מוֹנִיטָא\">מוניטא</a>; Ar. s. v. <span dir=\"rtl\">קטע</span>: <span dir=\"rtl\">חד פטטיא</span>); <span class=\"citation\">Midr. Till. to Ps. XL</span>, end <span dir=\"rtl\">הדא מיליא</span> (ed. Bub. <span dir=\"rtl\">מילתא</span>); <span class=\"citation\">Yalk. Ps. 737</span> <span dir=\"rtl\">הדין מלניא</span> (corr. acc.). [<a href=\"#\" data-headword=\"מוטניא\">מוטניא</a>, seems to be a corrupt. of μετάνοια in the sense of <i>change of mind</i>, the Greek equivalent of our w.]</div>","alt":["מִלְכְיָא"]},"13558":{"h":"*מַלַכְיָא","r":"M01582","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (μαλακία, malacia) <i>want of appetite, nausea</i>. <span class=\"citation\">Deut. R. s. 6</span> <span dir=\"rtl\">שעלת מ׳ באחותו</span> (not <span dir=\"rtl\">לראותה</span>) whose sister was suffering from malacia.</div>","alt":[]},"13559":{"h":"מַלְכִּיָּא","r":"M01583","html":"<div class=\"sense\"> (b. h.) pr. n. m., <span dir=\"rtl\">רב מ׳</span> <i>Rab Malkia</i>, an Amora. <span class=\"citation\">Sabb. 46ᵃ</span>; a. e., v. <a href=\"#\" data-headword=\"מְלַכְיוּ\">next w.</a></div>","alt":["מַלְכִּיָּה"]},"13560":{"h":"מְלַכְיוּ","r":"M01584","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>M’lakhiu</i>, </div><div class=\"sense\"><b>1)</b>  father of R. Kahăna. <span class=\"citation\">Erub. 8ᵇ</span></div><div class=\"sense\"><b>—2)</b>  רב מ׳ Rab M., an Amora. <span class=\"citation\">Keth. 61ᵇ</span>; <span class=\"citation\">Macc. 21ᵃ</span>; <span class=\"citation\">Nidd. 52ᵇ</span>. <span dir=\"rtl\">אמר ר׳ מ׳ אמר ר׳ וכ׳</span> Rab M. reports in the name of R. Ada &amp;c.; <span class=\"citation\">Bets. 28ᵇ</span> Ms. M. (v. Rabb. D. S. a. l. note). <span class=\"citation\">Ib.</span> (mnemonical rules by which to distinguish between the subjects reported by R. Malkia and those by R. M’lakhiu); <span class=\"citation\">ib.</span> <span dir=\"rtl\">וסימנך מתניתן מַלְכִּתָא</span> and the mnemotechnical mark is: the Mishnah is queen, i.e. all opinions referring to Mishnah (and Boraitha) belong to Rab Malkiya (<i>God is King</i>).</div>","alt":[]},"13561":{"h":"מִלְכָנָא","r":"M01585","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְלַךְ\">מְלַךְ</a>) <i>counsel, wisdom</i>. <span class=\"citation\">Targ. Prov. VIII, 14</span>. <span class=\"citation\">Ib. XXIV, 6</span> (ed. Lag. <a href=\"#\" data-headword=\"מוֹלְכָנָא\">מוֹלְכָנָא</a>); a. e.—V. <a href=\"#\" data-headword=\"מוֹלְכָנָא\">מוֹלְכָנָא</a>.</div>","alt":["מִילְ׳"]},"13562":{"h":"מַלְכְּתָא","r":"M01586","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. I Kings XI, 19</span>; a. fr.—<span class=\"citation\">Ker. 28ᵇ</span>; <span class=\"citation\">Pes. 57ᵃ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"מֶלֶךְ ²\">מַלְכָּן</a>, <a href=\"#\" data-headword=\"מַלְיָאתָא\">מַלְכָאתָא</a>. <span class=\"citation\">Targ. I Kings XI, 3</span>. Targ. II Esth. V, 1.</div>","alt":[]},"13563":{"h":"מִלְכְּתָא","r":"M01587","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"מֵלַךְ\">מִלְכָא</a>, <i>counsel</i>. <span class=\"citation\">Targ. Ps. XXXIII, 11</span>. <span class=\"citation\">Ib. I, 1</span>; a. e.—Pl. <a href=\"#\" data-headword=\"מִלְכְּתָא\">מִלְכָּתָא</a>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a>. <span class=\"citation\">Ib. V, 11</span>; a. e.</div>","alt":["מִילְ׳"]},"13564":{"h":"מִלְכְּתָנוּתָא","r":"M01588","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִלְכְּתָא\">preced.</a>) <i>consultation, meeting of councilmen</i>. <span class=\"citation\">Targ. Prov. XI, 14</span>.</div>","alt":["מִילְ׳"]},"13565":{"h":"מָלָל","r":"M01589","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מוֹל\">מוֹל</a>) <i>border, hem.</i> <span class=\"citation\">Kel. XXVIII, 7</span>; <span class=\"citation\">Sabb. 29ᵃ</span> <span dir=\"rtl\">שלש על … חוץ מן המ׳</span> the measure of three square handbreadths of which the Rabbis speak, means exclusive of the portion used for hemming. <span class=\"citation\">M. Kat. 26ᵇ</span> <span dir=\"rtl\">הקורע … מתוך המ׳</span> he who rends his garment only as far as the hem goes; Y. ib. III, 83ᵇ top <span dir=\"rtl\">מן המ׳</span>.—Denom.:</div>","alt":[]},"13566":{"h":"מָלַל I","r":"M01590","html":"<div class=\"sense\"><i>to hem, edge</i>. <span class=\"citation\">M. Kat. 26ᵃ</span> <span dir=\"rtl\">וכולן רשאין … למוֹלְלָן</span> and all these rents may be mended by … hemming. <span class=\"citation\">Kil. IX, 9</span> <span dir=\"rtl\">מוֹלֵל עד וכ׳</span> he hems (the purple band) before he knots it.</div>","alt":[]},"13567":{"h":"מָלַל II","r":"M01591","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to crush, squeeze</i>, esp. <i>to rub ears</i> for husking the grain. <span class=\"citation\">Taan. 6ᵃ</span> <span dir=\"rtl\">דבר שמָל</span>, v. <a href=\"#\" data-headword=\"מַלְקוֹשׁ\">מַלְקוֹשׁ</a>. <span class=\"citation\">Maasr. IV, 5</span>, v. <a href=\"#\" data-headword=\"מְלִילָה\">מְלִילָה</a>. <span class=\"citation\">Bets. 13ᵃ</span> <span dir=\"rtl\">למוֹלְלָן במלילות</span> with the intention of husking them when parched. <span class=\"citation\">Tosef. Sabb. XVI</span> (<span class=\"citation\">XVII), 22</span>; <span class=\"citation\">Sabb. 12ᵃ</span> <span dir=\"rtl\">מוֹלֵל</span> he rubs it between two fingers; a. fr.—Part. pass. <a href=\"#\" data-headword=\"מִלּוּל\">מָלוּל</a>. <span class=\"citation\">Tosef. ib. XIV</span> (<span class=\"citation\">XV), 17</span> <span dir=\"rtl\">מוֹלְלִין את המ׳</span> you may husk that which needs husking.</div><div class=\"sense\"><b>—2)</b> <i>to stir a mush, make a pulp</i>. <span class=\"citation\">Pes. 40ᵇ</span> <span dir=\"rtl\">אין מוֹלְלִין … והרוצה שיִמְלוֹל וכ׳</span> you must not stir a dish (in the usual way) on Passover, but he who desires to make a mush, must put in the flour and then add vinegar.—Part. pass. as ab. <span class=\"citation\">Tosef. Maasr. I, 7</span> <span dir=\"rtl\">מן המלול</span> ed. (ed. Zuck. <span dir=\"rtl\">המאמל</span>, Var. <span dir=\"rtl\">הממל</span>) out of the olive pulp.</div><div class=\"sense\"><b>Nif. נִמְלַל</b> <div class=\"sense\"><i>to be compressible</i>, (of webs) <i>to be soft and downy</i>. <span class=\"citation\">Gitt. 59ᵃ</span> (ref. to <span dir=\"rtl\">מ̇ל̇ת̇ח̇ה</span>, <span class=\"citation\">II Kings X, 22</span>) <span dir=\"rtl\">דבר הנמ̇ל̇ל ונמת̇ח̇</span> a cloth which can be compressed (creased) and stretched (again, showing no creases when unfolded); [Rashi: a stuff the thread of which is twisted between the spinner’s fingers and stretched].—V. <a href=\"#\" data-headword=\"מַלְמֵלָה\">מַלְמֵלָה</a>.</div></div>","alt":[]},"13568":{"h":"מְלַל I","r":"M01592","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"מוּל\">מוּל</a> ch.</div>","alt":[]},"13569":{"h":"מֶלֶל","r":"M01593","html":"<div class=\"sense\"> ch., constr. of <a href=\"#\" data-headword=\"מַלְלָא\">מַלְלָא</a>.</div>","alt":[]},"13570":{"h":"מָלַל III","r":"M01594","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">מִלֵּל</span>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a> (b. h.;  [<i>to present, show</i>; cmp. <a href=\"#\" data-headword=\"נָגַד\">הִגִּיד</a>, <a href=\"#\" data-headword=\"חיי\">חִוָּה</a>,] <i>to proclaim, utter, speak</i>. <span class=\"citation\">Hor. 13ᵇ</span>; <span class=\"citation\">Meg. 18ᵃ</span>; <span class=\"citation\">Macc. 10ᵃ</span> (ref. to <span class=\"citation\">Ps. CVI, 2</span>) <span dir=\"rtl\">למי נאה למַלֵּל וכ׳</span> whom does it become to utter the mighty deeds &amp;c.?—<span class=\"citation\">Y. Keth. II, 26ᵈ</span> bot. <span dir=\"rtl\">שמענו פלוני מְמַלֵּל על פלו׳ אשתו</span> we heard that man speaking of (pointing out) that woman as his wife; <span dir=\"rtl\">מְמַלֶּלֶת על בניה</span> speaking of her children; a. e.—[<span class=\"citation\">Lev. R. s. 27</span> <span dir=\"rtl\">מי מלל</span>, read: <a href=\"#\" data-headword=\"מָל\">מָל</a>, v. <a href=\"#\" data-headword=\"מוּל\">מוּל</a>, II, 2.—Lam. R. introd. (R. Hăn. 1) <span dir=\"rtl\">מְמַלְּלִים</span>, v. <a href=\"#\" data-headword=\"לִמְלֵם\">לִמְלֵם</a>.]</div>","alt":[]},"13571":{"h":"מְלַל II","r":"M01595","html":"<div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"מַלֵּי\">מַלֵּיל</a>, <span dir=\"rtl\">מַלֵּל</span> ch. same, in gen. <i>to speak</i> (corresp. to b. h. <a href=\"#\" data-headword=\"דִּיבֵּר\">דִּבֵּר</a>, <a href=\"#\" data-headword=\"שִׂיחַ\">שִׂיחַ</a>). <span class=\"citation\">Targ. Gen. XXXIV, 3</span> (O. ed. Berl. <a href=\"#\" data-headword=\"מַלֵּי\">מַלֵּי</a>). Ib. XVII, 22, sq.; a. v. fr.—Part. <a href=\"#\" data-headword=\"מַמְלָל\">מְמַלֵּל</a>, <span dir=\"rtl\">מְמַלְּלָא</span> &amp;c. (in ed. frequ. with one <a href=\"#\" data-headword=\"מ\">מ</a>, corr. acc.). <span class=\"citation\">Targ. Job II, 10</span>; a. fr.—<span class=\"citation\">Kidd. 50ᵃ</span> <span dir=\"rtl\">מְמַלֵּי מילי עלוי</span> (= <span dir=\"rtl\">מְמלְּלֵי</span>) they speak against me.</div><div class=\"sense\"><b>Ithpa. אִיתְמַלֵּל</b> <div class=\"sense\"><b>1)</b> <i>to be spoken, said, told</i>. <span class=\"citation\">Targ. Ps. LXXXVII, 3</span>. <span class=\"citation\">Targ. Y. Ex. XX, 16</span>; a. e.—Y. Shek. VI, 50, top (play on <span dir=\"rtl\">שחו</span>, <span class=\"citation\">Ez. XLVII, 5</span>) [read:] <span dir=\"rtl\">מאי מי שחו מיין דמִתְמַלְּלִין וכ׳</span> what is <i>me saḥu?</i> Waters which are spoken of in the world (v. <a href=\"#\" data-headword=\"שִׂיחַ\">שִׂיחַ</a>).</div><div class=\"sense\"><b>—2)</b> <i>to converse</i>. <span class=\"citation\">Targ. Y. Ex. XXXIII, 9</span>. <span class=\"citation\">Targ. Ez. II, 2</span>; <span class=\"citation\">I, 28</span>; a. e.</div></div>","alt":[]},"13572":{"h":"מַלְלָא","r":"M01596","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְלַל II\">preced.</a>) <i>word, speech</i>. <span class=\"citation\">Targ. Job XV, 11</span>. Targ. II Esth. VII, 9 <a href=\"#\" data-headword=\"מֶלֶל\">מֶלֶל</a> (constr.); a. e.—Pl. <span dir=\"rtl\">מַלְלִין</span>, constr. <span dir=\"rtl\">מַלְלֵי</span>. <span class=\"citation\">Targ. Y. II, Deut. XXXI, 24</span> (ed. Amst. <span dir=\"rtl\">מַלָּלֵי</span>).</div>","alt":["(מִלְלָא)"]},"13573":{"h":"מִלְלָא","r":"M01597","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (מְלַל I) </div><div class=\"sense\"><b>1)</b>  only in <span dir=\"rtl\">מ׳ דנורא</span> <i>embers</i>. [Comm. identify our w. with <a href=\"#\" data-headword=\"מַלְלָא\">preced.</a>, referring to the double meaning of <span dir=\"rtl\">לָהַשׁ</span>.] <span class=\"citation\">Ab. Zar. 28ᵇ</span> (Var. <a href=\"#\" data-headword=\"מוֹלְלָא\">מוֹלְלָא</a>, v. Rabb. D. S. a. l. note 400).—Pl. <span dir=\"rtl\">מִלְלֵי</span>, <a href=\"#\" data-headword=\"מִכְלָה\">מִי׳</a>. <span class=\"citation\">Sabb. 109ᵇ</span> <span dir=\"rtl\">בי מיללי דנ׳</span> (Ms. M. <span dir=\"rtl\">במל׳</span>) between the embers.—</div><div class=\"sense\"><b>*2)</b> <i>gold ore</i> as broken in the mine. <span class=\"citation\">Keth. 67ᵃ</span> במ׳ Ar. (ed. <span dir=\"rtl\">במַמְלָא</span>) it means ore (Rashi: <i>gold leaf</i>).</div>","alt":["מִי׳"]},"13574":{"h":"מַלָּלָא","r":"M01598","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"מְאַלְלָא\">מְאַלְּלָא</a>, v. <a href=\"#\" data-headword=\"אֲלַל\">אֲלַל</a>) <i>spy</i>.—Pl. <span dir=\"rtl\">מַלָּלַיָּא</span>, <span dir=\"rtl\">(מַלִּי׳</span>). <span class=\"citation\">Targ. Y. II, Deut. I, 1</span> (Y. I <a href=\"#\" data-headword=\"אַלְלַיָּא\">אלליא</a>).—[<span dir=\"rtl\">מַלָּלֵי</span>, v. <a href=\"#\" data-headword=\"מַלְלָא\">מַלְלָא</a>.]</div>","alt":[]},"13575":{"h":"מַלָּלוּתָא","r":"M01599","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (מְלַל II) <i>speaking</i>. Constr. <span dir=\"rtl\">מַלְּלוּת</span>. <span class=\"citation\">Targ. Y. Ex. XXXIII, 16</span>.</div>","alt":[]},"13576":{"h":"מַלְמֵד","r":"M01600","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>ox-goad.</i> <span class=\"citation\">Kel. IX, 6</span>, v. <a href=\"#\" data-headword=\"דָּֽרְבָן\">דָּֽרְבָן</a>. <span class=\"citation\">Y. Snh. X, 28ᵃ</span> <span dir=\"rtl\">מ׳ שהוא מְלַמֵּד וכ׳</span> it is called <i>malmed</i>, because it trains the cow &amp;c.; Pesik. Baḥod., p. 153ᵃ; a. e.</div>","alt":[]},"13577":{"h":"מִלְמוּל","r":"M01601","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָלַל II\"><span dir=\"rtl\">מָלַל</span> II</a>), pl. <span dir=\"rtl\">מִלְמוּלִין</span> <i>crumbs.</i> <span class=\"citation\">Mikv. IX, 2</span> <a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a> the crumb-like particles of dirty or sweaty hands when they are rubbed against each other.</div>","alt":[]},"13578":{"h":"מִלְמוּלָא","r":"M01602","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"מִלְמוּל\">same</a>. Y. Pes. III, beg. 29ᵈ, v. <a href=\"#\" data-headword=\"לִישׁ\">לִישׁ</a>.</div>","alt":[]},"13579":{"h":"מִלְמֵל","r":"M01603","html":"<div class=\"sense\"> (Pilpel of <span dir=\"rtl\">מִלֵּל</span>) <i>to talk</i>, v. <a href=\"#\" data-headword=\"לִמְלֵם\">לִמְלֵם</a>.</div>","alt":[]},"13580":{"h":"מַלְמֵלָה","r":"M01604","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (מָלַל II; cmp. <a href=\"#\" data-headword=\"מֵילַת\">מֵילַת</a>) <i>cloth of a fine and downy texture</i>. <span class=\"citation\">Gitt. 59ᵃ</span>, explained <span dir=\"rtl\">דבר הנמלל</span>, v. <a href=\"#\" data-headword=\"מָלַל II\"><span dir=\"rtl\">מָלַל</span> II</a>, <i>Nif.</i></div>","alt":["(מַלְמֵלָא)"]},"13581":{"h":"מלני","r":"M01605","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*מִלְכָי\">מִלְכָי</a></div>","alt":["מלניא"]},"13582":{"h":"מלספנון","r":"M01606","html":"<div class=\"sense\"> Tanḥ. Yithro 7, v. <a href=\"#\" data-headword=\"מִילְפִּפּוֹן\">מִילְפִּפּוֹן</a></div>","alt":[]},"13583":{"h":"מֵלַע","r":"M01607","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">לעע</span>, v. <a href=\"#\" data-headword=\"לוֹעַ\">לוֹעַ</a>) <i>whiskers</i>; <span dir=\"rtl\">מ׳ של שיבולין</span> <i>glume, the outer husk of grains</i>.—Pl. <span dir=\"rtl\">מְלָעִין</span>. <span class=\"citation\">Ukts. I, 3</span>; <span class=\"citation\">Ḥull. 119ᵇ</span>, sq. <a href=\"#\" data-headword=\"מְלָאי I\">מְלָאי</a>; <span class=\"citation\">Tosef. Ukts. I, 2</span> <span dir=\"rtl\">מְלָאִין של שובלין</span> ed. Zuck. (R. S. to Ukts. l. c. <span dir=\"rtl\">מלעין</span>; Var. Tosef. ed. Zuck. <span dir=\"rtl\">סלעי׳</span>, corr. acc.).—Ḥull. l. c. <span dir=\"rtl\">במלאי שבין המְלָאִים</span> when he takes hold of a number of glumes (which do not break).</div>","alt":[]},"13584":{"h":"מַלֵּף","r":"M01608","html":"<div class=\"sense\">, pl. <a href=\"#\" data-headword=\"מלפין\">מַלְּפִין</a>, v. <a href=\"#\" data-headword=\"מַלֵּיף\">מַלֵּיף</a>.</div>","alt":[]},"13585":{"h":"מַלְּפָא","r":"M01609","html":"<div class=\"sense\">, infinit. <i>Paël</i> of <a href=\"#\" data-headword=\"אֲלַף I\">אֲלַף</a> or <a href=\"#\" data-headword=\"יְלֵיף\">יְלֵיף</a>. <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> bot.; <span class=\"citation\">Y. Keth. XII, 35ᵃ</span> bot. <span dir=\"rtl\">גלי מ׳</span>, v. <a href=\"#\" data-headword=\"אֲלַף II\"><span dir=\"rtl\">אֲלַף</span> II</a>.</div>","alt":["מַלְּפָה"]},"13586":{"h":"מלפין","r":"M01610","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Ukts. II, 10</span>, v. <a href=\"#\" data-headword=\"מִילְפִּפּוֹן\">מִילְפִּפּוֹן</a></div>","alt":[]},"13587":{"h":"מַלְּפָנָא","r":"M01611","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַלֵּיף\">מַלֵּיף</a>) <i>teacher</i>. <span class=\"citation\">Yeb. 21ᵇ</span> <span dir=\"rtl\">מ׳ הוית</span> thou shalt be a teacher. <span class=\"citation\">Gen. R. s. 68</span>, beg. <span dir=\"rtl\">מַלְּפָנִי</span>, v. <a href=\"#\" data-headword=\"מַעַבְדָּנָא\">מַעַבְדָּנָא</a>.</div>","alt":[]},"13588":{"h":"מלפניא","r":"M01612","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">מִילְפּ׳</span>.</div>","alt":["מִלְפִּפּוֹן","מִלְפִּפּוֹנָא"]},"13589":{"h":"מָלַק","r":"M01613","html":"<div class=\"sense\"> (b. h.) <i>to pinch</i> a bird’s neck with the finger nail. <span class=\"citation\">Zeb. VI, 5</span>; <span class=\"citation\">Ib. VII, 5</span>; a. fr.—Part. pass. <span dir=\"rtl\">מָלוּק</span>; f. <a href=\"#\" data-headword=\"מְתוּקָה\">מְלוּקָה</a>, pl. <span dir=\"rtl\">מְלוּקוֹת</span>. Sifra Vayikra, N’dab., Par. 9, ch. XI <span dir=\"rtl\">מְלוּקַת רשות</span> a bird that has been pinched for a profane purpose, opp. <span dir=\"rtl\">מ׳ מציה</span>. Ib. <span dir=\"rtl\">מלוקית ישראל</span> birds pinched by Israelites (not for sacrificial purposes), opp. <span dir=\"rtl\">מ׳ כהנים</span>.</div><div class=\"sense\"><b>Nif. נִמְלַק</b> <div class=\"sense\"><i>to be killed by pinching</i>. Y. Sabb. II, 5ᵃ bot. <span dir=\"rtl\">משנִמְלְקָה</span> after the pinching has been performed. <span class=\"citation\">Ab. d’R. N. ch. I</span> <span dir=\"rtl\">כמה עופות נִמְלְקוּ עליך</span> how many birds have been pinched for thee (the altar)!; a. fr.</div></div>","alt":[]},"13590":{"h":"מְלַק","r":"M01614","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Lev. I, 15</span>; a. e. (Y. <span dir=\"rtl\">חזם</span>).</div>","alt":[]},"13591":{"h":"מַלְקוֹט","r":"M01615","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"לָקַט\">לָקַט</a>) <i>bag.</i> <span class=\"citation\">Kel. XVI, 7</span> <span dir=\"rtl\">המ׳ של בקר</span> the bag for receiving the excrements of working cattle; [Tosaf. Yom. Tob a. l. attests a version <a href=\"#\" data-headword=\"מַקְלוֹט\">מַקְלוֹט</a>]. [<span class=\"citation\">Tosef. Kel. B. Mets. III, 14</span>, v. <a href=\"#\" data-headword=\"מְלַקֵּט II\"><span dir=\"rtl\">מְלַקֵּט</span> II</a>.]</div>","alt":[]},"13592":{"h":"מַלְקוֹשׁ","r":"M01616","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>late rain</i>. <span class=\"citation\">Taan. 6ᵃ</span> <span dir=\"rtl\">מ׳ בניסן</span> the late rain (the <i>malḳosh</i> of the Bible) is the rain in Nisan. <span class=\"citation\">Ib.</span> (play on <span dir=\"rtl\">מ̇ל̇ק̇וש̇</span>) <span dir=\"rtl\">דבר שמ̇ל̇ ק̇ש̇יותן וכ׳</span> Rashi (ed. <span dir=\"rtl\">קשיותיהן</span>) something which crushes the stiffneckedness of the Israelites (who humble themselves in prayer for rain); <span dir=\"rtl\">דבר הממ̇ל̇א תבואה ב̇קש̇יה</span> something which fills the grain in its stalks; <span dir=\"rtl\">דבר שיורד על המ̇ל̇ילות ועל הק̇ש̇ין</span> which falls upon both the ears and the stalks; <span class=\"citation\">Yalk. Deut. 863</span>. Sifré Deut. s. 41; a. fr.</div>","alt":[]},"13593":{"h":"מַלְקוֹשָׁא","r":"M01617","html":"<div class=\"sense\"> Targ. O. a. Y. II <span class=\"citation\">Deut. XXXII, 2</span>.—Pl. <span dir=\"rtl\">מַלְקוֹשִׁין</span>. <span class=\"citation\">Targ. Y. Ex. XL, 4</span>.</div>","alt":[]},"13594":{"h":"מַלְקוּת","r":"M01618","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"לְקָא\">לָקָה</a>) <i>the punishment of lashes</i>. <span class=\"citation\">Macc. I, 3</span> <span dir=\"rtl\">שהוא חייב מ׳ ארבעים</span> that he (has done something for which he) is subject to forty lashes. <span class=\"citation\">Y. Naz. IV, 53ᵃ</span> bot. <span dir=\"rtl\">מ׳ תורה ארבעים וכ׳</span> the Biblical punishment consists of thirty-nine lashes; a. fr.—Pl. <span dir=\"rtl\">מַלְקִיּוֹת</span>. <span class=\"citation\">Snh. 81ᵇ</span> <span dir=\"rtl\">מ׳ של כריתות</span> the punishment of lashes for offences punishable with extinction. <span class=\"citation\">Ber. 7ᵃ</span>, v. <a href=\"#\" data-headword=\"מַרְדּוּת I\"><span dir=\"rtl\">מַרְדּוּת</span> I</a>; a. fr.</div>","alt":[]},"13595":{"h":"מַלְקוּת ²","r":"M01619","html":"<div class=\"sense\">, <i>chastisement</i>. <span class=\"citation\">Targ. Y. Deut. XXV, 3</span>. <span class=\"citation\">Targ. II Sam. VII, 14</span>.</div>","alt":["מַלְקוּתָא"]},"13596":{"h":"מֶלְקָחָה","r":"M01620","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֶלְקַחַת\">מֶלְקַחַת</a></div>","alt":[]},"13597":{"h":"מֶלְקָחַיִם","r":"M01621","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> du. (b. h.; <a href=\"#\" data-headword=\"לָקַח\">לָקַח</a>) <i>tongs</i>; (in Midr.) <i>two pairs of tongs</i>. <span class=\"citation\">Pesik. R. s. 33</span>; <span class=\"citation\">Yalk. Is. 271</span> (ref. to <span class=\"citation\">Is. VI, 6</span>) <span dir=\"rtl\">מהו במ׳</span> why with two pairs?; v. <a href=\"#\" data-headword=\"מֶלְקַחַת\">next w.</a></div>","alt":[]},"13598":{"h":"מֶלְקַחַת","r":"M01622","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מֶלְקָחַיִם\">preced.</a>) <i>tongs</i>. <span class=\"citation\">Pesik. R. s. 33</span>; <span class=\"citation\">Yalk. Is. 271</span> <span dir=\"rtl\">נטל מ׳ אחרת</span> (some ed. <a href=\"#\" data-headword=\"מֶלְקָחָה\">מֶלְקָחָה</a>) he took another pair of tongs.</div>","alt":[]},"13599":{"h":"מְלַקֵּט I","r":"M01623","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"לָקַט\">לָקַט</a>) <i>gatherer, eclectic scholar</i>. <span class=\"citation\">Ab. d’R. N. ch. XVIII</span>, end <span dir=\"rtl\">מ׳ יפה יפה בלא וכ׳</span> a discriminating eclectic scholar without any pride.</div>","alt":[]}};
